def normalize_dates(data):
    if isinstance(data, dict):
        return {k: normalize_dates(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [normalize_dates(item) for item in data]
    elif isinstance(data, date):
        return datetime.combine(data, datetime.min.time())
    return data




@router.post("/medical_context_save")
async def save_medical_context(payload: MedicalContextRequest):
    doctor_id = payload.doctor_id
    patient_id = payload.patient_id

    for ctx in payload.current_context:
        context_date = ctx.date.isoformat()

        # Normalize & dedupe conditions
        normalized_conditions = []
        seen = set()

        for cond in ctx.conditions:
            key = cond.text.lower()
            logger.info("Conditionnn Text",key)
            if key not in seen:
                seen.add(key)
                normalized_conditions.append({
                    "id": cond.id or str(uuid4()),
                    "text": cond.text
                })

        # Try updating existing context (by date)
        result = await medical_context_collection.update_one(
            {
                "doctor_id": doctor_id,
                "patient_id": patient_id,
                "medical_contexts.date": context_date
            },
            {
                "$addToSet": {
                    "medical_contexts.$.conditions": {
                        "$each": normalized_conditions
                    }
                },
                "$set": {"updated_at": datetime.utcnow()},
                "$setOnInsert": {
                    "doctor_id": doctor_id,
                    "patient_id": patient_id
                }
            }
        )

        # Insert new date context if not exists
        if result.matched_count == 0:
            await medical_context_collection.update_one(
                {
                    "doctor_id": doctor_id,
                    "patient_id": patient_id
                },
                {
                    "$push": {
                        "medical_contexts": {
                            "date": context_date,
                            "conditions": normalized_conditions,
                            "enabled": True
                        }
                    },
                    "$set": {"updated_at": datetime.utcnow()},
                    "$setOnInsert": {
                        "doctor_id": doctor_id,
                        "patient_id": patient_id
                    }
                },
                upsert=True
            )

    return {
        "status": "success",
        "doctor_id": doctor_id,
        "patient_id": patient_id
    }
