@router.post("/current_context_save")
async def save_current_context(payload: CurrentContextBulkRequest):
    logger.info("Current Context Save Payload",payload)
    doctor_id = payload.doctor_id
    logger.info("Doctor ID",doctor_id)
    patient_id = payload.patient_id
    logger.info("Patient ID",patient_id)

    for context in payload.contexts:
        context_date = context.date.isoformat()
        logger.info("Context Date",context_date)
        # 🔒 Normalize & deduplicate conditions
        normalized_conditions = []
        seen = set()

        for cond in context.current_condition:
            key = cond.text.lower()
            logger.info("Condition Text",key)
            if key not in seen:
                seen.add(key)
                normalized_conditions.append({
                    "id": cond.id or str(uuid4()),
                    "text": cond.text
                })
        logger.info("Normalized Conditions",normalized_conditions)
        # Try updating existing context for the same date
        update_result = await current_context_collection.update_one(
            
            {
                "doctor_id": doctor_id,
                "patient_id": patient_id,
                "current_contexts.date": context_date
            },
            {
                "$addToSet": {
                    "current_contexts.$.current_condition": {
                        "$each": normalized_conditions
                    }
                },
                "$set": {"updated_at": datetime.utcnow()}
            }
        )
        logger.info("Update Result: %s", update_result)
        # If no context exists for that date → insert new
        if update_result.matched_count == 0:
            await current_context_collection.update_one(
                {
                    "doctor_id": doctor_id,
                    "patient_id": patient_id
                },
                {
                    "$push": {
                        "current_contexts": {
                            "date": context_date,
                            "current_condition": normalized_conditions,
                            "enabled": True
                        }
                    },
                    "$set": {"updated_at": datetime.utcnow()}
                },
                upsert=True
            )
        logger.info("Update2 Result: %s", update_result)
    return {
        "status": "success",
        "doctor_id": doctor_id,
        "patient_id": patient_id,
        "contexts_processed": len(payload.contexts)
    }

