@router.post("/documentation_save")
async def save_documentation(doc: documentation):
    if not doc.doctor_id:
        return {
            "status": "error",
            "message": "doctor_id is required"
        }

    doctor_id = doc.doctor_id

    # Normalize dates & nested datetimes
    doc_data = normalize_dates(doc.dict())
    doc_data["enabled"] = True

    # Remove existing documentation with same ID
    await document_user_collection.update_one(
        {"doctor_id": doctor_id},
        {"$pull": {"documents": {"id": doc_data["id"]}}},
    )

    # Insert new documentation
    await document_user_collection.update_one(
        {"doctor_id": doctor_id},
        {
            "$push": {"documents": doc_data},
            "$set": {"updated_at": datetime.utcnow()}
        },
        upsert=True
    )

    return {
        "status": "success",
        "documentation_id": doc_data["id"],
        "doctor_id": doctor_id
    }
