@router.get("/medical_contextu")
async def get_medical_context(
    doctor_id: str,
    patient_id: str
):
    document = await medical_context_collection.find_one(
        {
            "doctor_id": doctor_id,
            "patient_id": patient_id
        },
        {"_id": 0}
    )

    # No document found
    if not document:
        return {
            "status": "success",
            "doctor_id": doctor_id,
            "patient_id": patient_id,
            "medical_contexts": []
        }

    contexts = document.get("medical_contexts", [])

    # 🔒 Safe date sort (handles YYYY-MM-DD and YYYY-MM-DDTHH:MM:SS)
    def safe_date(ctx):
        try:
            return datetime.fromisoformat(ctx["date"].split("T")[0])
        except Exception:
            return datetime.min

    contexts.sort(key=safe_date, reverse=True)

    return {
        "status": "success",
        "doctor_id": doctor_id,
        "patient_id": patient_id,
        "medical_contexts": contexts
    }


@router.get("/current_contextu")
async def get_current_context(
    doctor_id: str,
    patient_id: str
):
    document = await current_context_collection.find_one(
        {
            "doctor_id": doctor_id,
            "patient_id": patient_id
        },
        {"_id": 0}
    )

    if not document:
        return {
            "status": "success",
            "doctor_id": doctor_id,
            "patient_id": patient_id,
            "current_contexts": []
        }

    contexts = document.get("current_contexts", [])
    contexts.sort(
        key=lambda x: datetime.fromisoformat(x["date"]),
        reverse=True
    )

    return {
        "status": "success",
        "doctor_id": doctor_id,
        "patient_id": patient_id,
        "current_contexts": contexts
    }



