@router.post("/process_feature_context_llm")
async def process_feature_context_llm(request: Request):
    logger.info("Processing feature context LLM")
    body = await request.json()

    doctor_id = body.get("doctor_id")
    patient_id = body.get("patient_id")
    feature_id = body.get("feature_id")
    new_data = body.get("new_data")
    logger.info("HASNA | new_data=%s", new_data)


    if not doctor_id or not patient_id or not feature_id or new_data is None:
        raise HTTPException(
            status_code=400,
            detail="doctor_id, patient_id, feature_id, new_data required"
        )

    """
    LLM-Driven Clinical Decision Support Context Processor
    
    - Analyzes new feature data against existing medical context
    - Extracts clinically relevant conditions for treatment decisions
    - Filters out non-relevant information
    - Maintains strict accuracy without hallucination
    """

    # ==========================================================
    # 1️⃣ FETCH FEATURE CONFIGURATION
    # ==========================================================
    doctor_node = await doctor_nodes_collection.find_one(
        {"doctor_id": doctor_id, "features.feature_id": feature_id},
        {"features.$": 1, "_id": 0}
    )
    # if not doctor_node:
    #     raise HTTPException(404, "Feature configuration not found")



    # if not doctor_node:
    #     raise HTTPException(404, "Feature configuration not found")
    if not doctor_node or not doctor_node.get("features"):
        logger.warning(
            f"Feature configuration not found | "
            f"doctor_id={doctor_id} | feature_id={feature_id}"
        )
        return {
            "feature_id": feature_id,
            "saved": False,
            "collection": "conditions",
            "reason": "Feature configuration not found or not enabled"
        }

    feature = doctor_node["features"][0]

    # if not feature.get("enabled"):
    #     logger.info(
    #         "Skipping LLM | reason=feature_disabled | "
    #         "doctor_id=%s | patient_id=%s | feature_id=%s",
    #         doctor_id,
    #         patient_id,
    #     feature_id
    # )
    # raise HTTPException(403, "Feature disabled")


    feature_name = feature.get("feature_name", feature_id)
    rules = feature.get("rules", "")

    # ==========================================================
    # 2️⃣ FETCH EXISTING CONTEXTS
    # ==========================================================
    medical_context = await medical_context_collection.find(
        {"patient_id": patient_id, "enabled": True},
        {"_id": 0}
    ).to_list(length=50)

    current_context = await current_context_collection.find(
        {"patient_id": patient_id, "enabled": True},
        {"_id": 0}
    ).to_list(length=50)

    # ==========================================================
    # 3️⃣ BUILD CLINICAL DECISION SUPPORT PROMPT
    # ==========================================================
    prompt = f"""
You are an EXPERIENCED CLINICIAN reviewing new patient data for clinical documentation.

Your task is to produce a SINGLE, CONCISE, CLINICIAN-STYLE SUMMARY SENTENCE
that accurately reflects the clinically relevant findings in the new data.

────────────────────────────────────────────
CLINICAL INTERPRETATION RULES
────────────────────────────────────────────
✓ You MAY apply standard, widely accepted clinical interpretation
  (e.g., normal vs elevated vs low vs borderline)
✓ Interpret values ONLY using universally accepted adult clinical ranges
✓ Do NOT invent diagnoses, causes, or treatment implications
✓ Do NOT speculate beyond the provided data
✓ If a value is ambiguous, ignore it rather than guess
✓ Patient safety is critical — accuracy over completeness
✓ Do NOT state that findings are "within normal limits" if ANY value is
  borderline, mildly abnormal, or safety-relevant.
✓ Borderline or abnormal values MUST be explicitly mentioned.


────────────────────────────────────────────
WHAT TO INCLUDE
────────────────────────────────────────────
Include:
- All clinically relevant findings in the new data
- Both normal and abnormal findings, if clinically meaningful
- Borderline or safety-relevant values (even if mild)
- Findings that a clinician would want to know at a glance

────────────────────────────────────────────
WHAT TO EXCLUDE
────────────────────────────────────────────
Exclude:
- Administrative or operational details
- Raw numeric repetition without clinical meaning
- Diagnoses not explicitly stated
- Causes, recommendations, or treatment plans
- Redundant context already known

────────────────────────────────────────────
STYLE & FORMAT REQUIREMENTS
────────────────────────────────────────────
- Output EXACTLY ONE LINE of plain text
- Write a single, grammatically correct sentence
- Use professional clinical language
- Group related normal findings together
- Clearly highlight abnormal or borderline findings
- Do NOT use bullet points, lists, headings, or symbols
- Do NOT include explanations, timestamps, or labels

────────────────────────────────────────────
PRIORITIZATION
────────────────────────────────────────────
If multiple findings exist:
1. Safety-relevant or abnormal findings first
2. Borderline findings next
3. Normal findings grouped together

If any abnormal or borderline finding exists, you MUST explicitly name it
and you MUST NOT summarize all findings as normal.


────────────────────────────────────────────
PATIENT MEDICAL HISTORY (context only)
────────────────────────────────────────────
{json.dumps(medical_context, indent=2) if medical_context else "No medical history available"}

────────────────────────────────────────────
CURRENT CLINICAL CONDITION (context only)
────────────────────────────────────────────
{json.dumps(current_context, indent=2) if current_context else "No current clinical conditions recorded"}

────────────────────────────────────────────
FEATURE BEING ANALYZED
────────────────────────────────────────────
Feature Name: {feature_name}

DOCTOR-AUTHORED GOVERNING RULES (HIGHEST PRIORITY)
────────────────────────────────────────────
The following rules were explicitly defined by the treating doctor.
They MUST directly influence how the summary sentence is written.

Rules:
{rules if rules else "No specific guidelines provided"}

MANDATORY RULE APPLICATION:
- FIRST interpret these rules
- Convert them into HARD output constraints
- Apply them to the summary sentence
- If a finding violates a rule → DO NOT INCLUDE it
- If uncertain → OMIT the finding
- Omission is ALWAYS preferred over violation

These rules OVERRIDE all other instructions.

────────────────────────────────────────────
NEW CLINICAL DATA
────────────────────────────────────────────
{json.dumps(new_data, indent=2)}

────────────────────────────────────────────
FINAL INSTRUCTION
────────────────────────────────────────────
Write ONE concise clinician-style summary sentence capturing the
clinically relevant findings from the new data.

If NO clinically relevant findings exist, output an EMPTY STRING.

Output now:
"""


    # ==========================================================
    # 4️⃣ LLM EXECUTION
    # ==========================================================
    logger.info(
        "Entering LLM execution | doctor_id=%s | patient_id=%s | "
        "feature_id=%s | feature_name=%s",
        doctor_id,
        patient_id,
        feature_id,
        feature_name
    )

    completion = groq_client.chat.completions.create(
        model="llama-3.1-8b-instant",
        messages=[{"role": "user", "content": prompt}],
        temperature=0.1,  # Lower temperature for more deterministic output
        max_tokens=250
    )

    condition_text = completion.choices[0].message.content.strip()

    logger.info(f"LLM extracted condition: {condition_text}")

    # ==========================================================
    # 5️⃣ VALIDATE OUTPUT
    # ==========================================================
    # Ensure we don't store empty or whitespace-only responses
    if not condition_text or condition_text.isspace():
        logger.info(
            "LLM ran but returned empty output | "
            "doctor_id=%s | patient_id=%s | feature_id=%s",
            doctor_id,
            patient_id,
            feature_id
        )

    # ==========================================================
    # 6️⃣ STORE CONDITION (uncomment when ready)
    # ==========================================================
    now = datetime.utcnow()
    report_date = now.date().isoformat()

    result = await condition_collection.update_one(
        {
            "patient_id": patient_id,
            "doctor_id": doctor_id
        },
        {
            "$push": {
                "conditions": {
                    "doc_type": feature_id,
                    "report_date": report_date,
                    "condition": condition_text,
                    "created_at": now
                }
            },
            "$setOnInsert": {
                "created_at": now
            },
            "$set": {
                "updated_at": now
            }
        },
        upsert=True
    )


    # ==========================================================
    # LOGGING
    # ==========================================================
    if result.upserted_id:
        logger.info(
            f"New patient condition document created | patient_id={patient_id} | doctor_id={doctor_id} | condition={condition_text}"
        )
    else:
        logger.info(
            f"Condition appended to existing patient record | patient_id={patient_id} | doctor_id={doctor_id} | condition={condition_text}"
        )


    

    # ==========================================================
    # 7️⃣ RETURN RESULT
    # ==========================================================
    return {
        "feature_id": feature_id,
        "saved": True,
        "collection": "conditions",
        "condition": condition_text
    }

@router.get("/conditions")
async def get_patient_conditions(
    patient_id: str,
    doctor_id: str
):
    logger.info("GET /conditions started")

    document = await condition_collection.find_one(
        {
            "patient_id": patient_id,
            "doctor_id": doctor_id
        },
        {"_id": 0}
    )

    if not document:
        logger.info(
            f"No conditions found for patient_id={patient_id}, doctor_id={doctor_id}"
        )
        return {
            "status": "success",
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "conditions": []
        }

    conditions = document.get("conditions", [])

    logger.info(
        f"Retrieved {len(conditions)} condition(s) for patient_id={patient_id}, doctor_id={doctor_id}"
    )

    # Sort conditions by created_at (latest first)
    conditions = sorted(
        conditions,
        key=lambda x: x.get("created_at"),
        reverse=True
    )

    logger.info("GET /conditions completed successfully")

    return {
        "status": "success",
        "patient_id": patient_id,
        "doctor_id": doctor_id,
        "conditions": conditions,
        "total_conditions": len(conditions)
    }



@router.get("/get_laboratory_pathology_reports")
async def get_laboratory_pathology_reports(
    patient_id: str,
    doctor_id: str | None = None
):

    try:
        logger.info(
            "🔍 Fetching laboratory pathology reports for patient_id=%s doctor_id=%s",
            patient_id, doctor_id
        )

        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        # ================= QUERY =================
        query = {"patient_id": patient_id}

        if doctor_id:
            query["doctor_id"] = doctor_id

        cursor = laboratory_pathology_reports_collection.find(
            query
        ).sort("report_date", -1)

        results = []

        async for doc in cursor:
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            results.append(doc)

        return {
            "status": "success",
            "count": len(results),
            "data": results
        }

    except Exception as e:
        logger.error(
            "💥 HARD FAIL:\n%s",
            traceback.format_exc()
        )

        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )

@router.get("/get_laboratory_pathology_report/{report_id}")
async def get_laboratory_pathology_report(report_id: str):

    try:
        if not ObjectId.is_valid(report_id):
            return JSONResponse(
                status_code=400,
                content={"detail": "Invalid report_id"}
            )

        doc = await laboratory_pathology_reports_collection.find_one(
            {"_id": ObjectId(report_id)}
        )

        if not doc:
            return JSONResponse(
                status_code=404,
                content={"detail": "Report not found"}
            )

        doc["id"] = str(doc["_id"])
        del doc["_id"]

        return {
            "status": "success",
            "data": doc
        }

    except Exception as e:
        logger.error(
            "💥 HARD FAIL:\n%s",
            traceback.format_exc()
        )

        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )



