@router.post("/save_dictation")
async def save_dictation(payload: dict):

    try:
        logger.info("✅ Incoming dictation payload: %s", payload)

        # ================= BASIC FIELDS =================
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        processed_data = payload.get("processed_data", [])
        raw_data = payload.get("raw_data", [])

        department = payload.get("department")
        encounter_type = payload.get("encounter_type")
        treatment_id = payload.get("treatment_id")

        # ================= VALIDATION =================
        if not patient_id or not doctor_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id and doctor_id are required"}
            )

        if not isinstance(processed_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "processed_data must be an array"}
            )

        if not isinstance(raw_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "raw_data must be an array"}
            )
        created_at = datetime.utcnow()
        # ================= DOCUMENT =================
        
        doc = {
            "_id": ObjectId(),
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "department": department,
            "encounter_type": encounter_type,
            "treatment_id": treatment_id,
            "processed_data": processed_data,
            "raw_data": raw_data,
            "created_at": created_at
        }

        # ================= SAVE DICTATION =================
        result = await dictation_collection.insert_one(doc)

        logger.info(
            "✅ Dictation saved successfully | dictation_id=%s | patient=%s",
            result.inserted_id,
            patient_id
        )

        # =====================================================
        # 🔥 ROUTE VITALS & DOCUMENTS
        # =====================================================

        logger.info(
            "🔄 Starting routing of vitals and documents | dictation_id=%s",
            result.inserted_id
        )

        for item in processed_data:
            # =====================================================
            # 🔥 ASSERTION ROUTING
            # =====================================================

            logger.info(
                "🧠 Checking assertions in processed_data block | dictation_id=%s",
                result.inserted_id
            )

            content = item.get("content", {})
            assertions_to_insert = []

            # ---------------- PRESENTING COMPLAINT ----------------
            presenting_complaint = content.get("presenting_complaint")
            if presenting_complaint:
                assertions_to_insert.append({
                    "_id": ObjectId(),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "type": "presenting_complaint",
                    "data": presenting_complaint,
                    "dictation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                })

                logger.info(
                    "📌 Presenting complaint found | patient=%s",
                    patient_id
                )

            # ---------------- DIAGNOSES ----------------
            diagnoses = content.get("diagnoses", [])
            if diagnoses and isinstance(diagnoses, list):
                for diagnosis in diagnoses:
                    assertions_to_insert.append({
                        "_id": ObjectId(),
                        "patient_id": patient_id,
                        "doctor_id": doctor_id,
                        "type": "diagnosis",
                        "data": diagnosis,
                        "dictation_id": result.inserted_id,
                        "created_at": datetime.utcnow()
                    })

                logger.info(
                    "🩺 %d diagnosis assertion(s) found | patient=%s",
                    len(diagnoses),
                    patient_id
                )

            # ---------------- FOLLOW UP ----------------
            follow_up = content.get("follow_up")
            if follow_up:
                assertions_to_insert.append({
                    "_id": ObjectId(),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "type": "follow_up",
                    "data": follow_up,
                    "dictation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                })

                logger.info(
                    "📅 Follow-up found | patient=%s",
                    patient_id
                )

            # ---------------- RED FLAGS ----------------
            red_flags = content.get("red_flags", [])
            if red_flags and isinstance(red_flags, list):
                for flag in red_flags:
                    assertions_to_insert.append({
                        "_id": ObjectId(),
                        "patient_id": patient_id,
                        "doctor_id": doctor_id,
                        "type": "red_flag",
                        "data": {"value": flag},
                        "dictation_id": result.inserted_id,
                        "created_at": datetime.utcnow()
                    })

                logger.info(
                    "🚨 %d red flag(s) found | patient=%s",
                    len(red_flags),
                    patient_id
                )

            # ---------------- BULK INSERT ----------------
            if assertions_to_insert:
                await assertion_collections.insert_many(assertions_to_insert)

                logger.info(
                    "✅ Assertions saved successfully | patient=%s | total=%d",
                    patient_id,
                    len(assertions_to_insert)
                )
            else:
                logger.info(
                    "ℹ️ No assertions found in this processed_data block | patient=%s",
                    patient_id
                )


           # ---------------- VITAL SIGNS (STRUCTURED FORMAT) ----------------
            vital_signs = content.get("vital_signs")

            if vital_signs and isinstance(vital_signs, dict):

                # Remove source field
                cleaned_vitals = {
                    k: v for k, v in vital_signs.items()
                    if k != "source" and v is not None
                }

                if cleaned_vitals:

                    # Generate timestamp key
                    timestamp = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S_%fZ")

                    structured_payload = {
                        "doctor_id": doctor_id,
                        "appointment_id": payload.get("appointment_id"),  # if passed
                        **cleaned_vitals
                    }

                    update_doc = {
                        "$set": {
                            f"vitals.{timestamp}": structured_payload,
                            "appointment_id": payload.get("appointment_id")
                        },
                        "$setOnInsert": {
                            "sys_user_id": patient_id,
                            "patient_id": patient_id
                        },
                        "$currentDate": {"updated_at": True}
                    }

                    await patient_vitals_collection.update_one(
                        {"sys_user_id": patient_id},
                        update_doc,
                        upsert=True
                    )

                    logger.info(
                        "🩺 Structured vitals saved | patient=%s | vitals=%s",
                        patient_id,
                        cleaned_vitals
                    )
            else:
                logger.info("ℹ️ No vital_signs found in this processed_data block")

            # ---------------- DOCUMENTS ----------------
            documents = item.get("documents", [])

            if documents:
                logger.info(
                    "📄 Found %d documents to save | dictation_id=%s",
                    len(documents),
                    result.inserted_id
                )

            for document in documents:
                report_date = document.get("report_date")

                if not report_date:
                    report_date = datetime.utcnow().strftime("%d-%m-%Y")

                structured_output = [
                    {
                        "source": "hospital_rule_llm",
                        "structured_data": document.get("report_content", {}),
                        "clinical_abstract": None
                    }
                ]

                document_doc = {
                    "_id": ObjectId(),
                    "document_id": document.get("test_name"),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "processed_data": structured_output,
                    "raw_data": raw_data,
                    "report_date": report_date,
                    "documents": [],
                    "category": document.get("category_key"),
                    "subcategory": document.get("subcategory_key"),
                    "dictation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                }

                await document_categories_collection.insert_one(document_doc)


                logger.info(
                    "📑 Document saved | patient=%s | test=%s | category=%s",
                    patient_id,
                    document.get("test_name"),
                    document.get("category_key")
                )

        logger.info(
            "✅ Routing completed successfully | dictation_id=%s",
            result.inserted_id
        )
        

    
        # ==========================================================
        # 🔥 3️⃣ ADD CLINICAL TRIGGER HERE (NEW)
        # ==========================================================
       

        # ==========================================================
        # 🔥 TEMP DATA SAVE TRIGGER (NEW)
        # ==========================================================
        temp_payload = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "dictation": [raw_data]   # Now using raw_data in the dictation field
        }

        logger.info(f"temp_save_payload:{temp_payload}")

        try:
            async with httpx.AsyncClient(timeout=15.0) as client:
                temp_response = await client.post(
                    f"{api_base_url}hms/users/data/context/general/temp/save",
                    json=temp_payload
                )

            if temp_response.status_code != 200:
                logger.error(
                    "Temp save trigger failed",
                    extra={
                        "status_code": temp_response.status_code,
                        "response": temp_response.text
                    }
                )

        except Exception as e:
            logger.error(f"Temp save exception: {str(e)}")        
            
        
        
        # ================= RESPONSE =================
        doc["id"] = str(doc["_id"])
        del doc["_id"]

        return {
            "status": "saved",
            "data": doc
        }

    except Exception as e:
        logger.error("💥 HARD FAIL:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )

@router.get("/get_dictation_by_patient")
async def get_dictation_by_patient(
    patient_id: str,
    department: Optional[str] = Query(None, description="Filter by department"),
    encounter_type: Optional[str] = Query(None, description="Filter by encounter type"),
    treatment_id: Optional[str] = Query(None, description="Filter by treatment ID")
):

    try:
        logger.info(
            "🔍 Fetching dictation records for patient_id=%s, department=%s, encounter_type=%s",
            patient_id, department, encounter_type
        )

        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        # ================= QUERY =================
        query = {"patient_id": patient_id}
        if department:
            query["$or"] = query.get("$or", []) + [{"department": department}, {"department": None}, {"department": {"$exists": False}}]
        if encounter_type:
            query["$or"] = query.get("$or", []) + [{"encounter_type": encounter_type}, {"encounter_type": None}, {"encounter_type": {"$exists": False}}]
        if treatment_id:
            query["treatment_id"] = treatment_id

        cursor = dictation_collection.find(query).sort("created_at", -1)

        results = []

        async for doc in cursor:
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            results.append(doc)

        return {
            "status": "success",
            "patient_id": patient_id,
            "count": len(results),
            "data": results
        }

    except Exception as e:
        logger.error("Error fetching dictation: %s", str(e))
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )

