from bson import ObjectId

def convert_objectids(obj):
    if isinstance(obj, ObjectId):
        return str(obj)
    if isinstance(obj, list):
        return [convert_objectids(i) for i in obj]
    if isinstance(obj, dict):
        return {k: convert_objectids(v) for k, v in obj.items()}
    return obj


@router.post("/save_document_categories")
async def save_document_categories(payload: dict):

    try:
        logger.info("✅ Incoming document categories payload: %s", payload)

        # ================= BASIC FIELDS =================
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        document_id = payload.get("document_id")   # 👈 FROM BODY
        processed_data = payload.get("processed_data", [])
        raw_data = payload.get("raw_data", [])
        documents = payload.get("documents", [])
        report_date = payload.get("report_date")   # ✅ ADD THIS
        category = payload.get("category")         # ✅ ADD
        subcategory = payload.get("subcategory")   # ✅ ADD
        file_url = payload.get("file_url")   # ✅ ADD THIS

        # ================= VALIDATION =================
        if not patient_id or not doctor_id or not document_id:
            return JSONResponse(
                status_code=400,
                content={
                    "detail": "patient_id, doctor_id and document_id are required"
                }
            )

        if not isinstance(processed_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "processed_data must be an array"}
            )

        if not isinstance(raw_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "raw_data must be an array"}
            )

        if not isinstance(documents, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "documents must be an array"}
            )

        # ================= DOCUMENT =================
        doc = {
            "_id": ObjectId(),              # 👈 Mongo internal ID
            "document_id": str(document_id),# 👈 EXACT value from payload
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "processed_data": processed_data,
            "raw_data": raw_data,
            "report_date": report_date,   # ✅ ADD THIS
            "documents": documents,
            "category": category,            # ✅ ADD
            "subcategory": subcategory,      # ✅ ADD
            "file_url": file_url,      # ✅ SAVE FILE URL
            "created_at": datetime.utcnow()
        }

        # ================= SAVE =================
        result = await document_categories_collection.insert_one(doc)

        # ================= RESPONSE =================
        doc["id"] = str(doc["_id"])
        del doc["_id"]

        logger.info(
            "✅ Inserted document_categories record %s",
            result.inserted_id
        )
        # ======================================================
        # 🔥 TRIGGER CONTEXT + TEMP SAVE (NEW)
        # ======================================================

        category_key = category
        subcategory_key = subcategory

        # Trigger clinical context for the document
        trigger_payload = {
            "doctor_id": doctor_id,
            "patient_id": patient_id,
            "feature_id": "document",   # 🔥 unified feature
            "new_data": {
                "category": category_key,
                "subcategory": subcategory_key,
                "data": processed_data,
                "created_at": report_date
            }
        }

        logger.info("📡 Triggering document context | %s", trigger_payload)

        try:
            async with httpx.AsyncClient(timeout=30) as client:
                trigger_response = await client.post(
                    f"{api_base_url}hms/users/data/context/trigger",
                    json=trigger_payload,
                    timeout=30
                )
            if trigger_response.status_code != 200:
                logger.error(
                    "Document trigger failed",
                    extra={
                        "status_code": trigger_response.status_code,
                        "response": trigger_response.text
                    }
                )
        except Exception as e:
            logger.error(f"Document trigger failed: {str(e)}")

        # ======================================================
        # 🔥 TEMP DATA SAVE TRIGGER
        # ======================================================

        temp_payload = {
            "doctor_id": doctor_id,
            "patient_id": patient_id,
            "documentation": [
                {
                    "category": category_key,
                    "subcategory": subcategory_key,
                    "data": processed_data,
                    "source": "document_pipeline"
                }
            ]
        }

        logger.info("📡 Triggering temp save | %s", temp_payload)

        try:
            async with httpx.AsyncClient(timeout=30) as client:
                temp_response = await client.post(
                    f"{api_base_url}hms/users/data/context/general/temp/save",
                    json=temp_payload,
                    timeout=30
                )

            if temp_response.status_code != 200:
                logger.error(
                    "Temp document save failed",
                    extra={
                        "status_code": temp_response.status_code,
                        "response": temp_response.text
                    }
                )

        except Exception as e:
            logger.error(f"Temp document save failed: {str(e)}")

        
        # ======================================================
        # 🚀 TRIGGER AGENTIC REASONING (CROSS-DOCKER SAFE)
        # ======================================================

        try:
            from users.celery_client import celery_app

            agentic_payload = {
                "category": category_key,
                "subcategory": subcategory_key,
                "raw_data": raw_data
                
            }
            logger.info(f"agentic payload:{agentic_payload}")
            celery_app.send_task(
                "agentic.trigger_clinical_reasoning",
                kwargs={
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "data": agentic_payload
                },
                queue="agentic_queue",        # ⭐ REQUIRED (your worker listens to default)
                routing_key="agentic",
                exchange="agentic"
            )

            logger.info(
                "🚀 Agentic reasoning task published | patient=%s",
                patient_id
            )

        except Exception as e:
            logger.error(f"❌ Failed to trigger agentic reasoning: {str(e)}")
        
        return {
            "status": "saved",
            "data": doc
        }

    except Exception as e:
        logger.error("💥 HARD FAIL:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )
