@router.post("/save_conversation_user")
async def save_conversation_user(payload: dict):

    try:
        logger.info("✅ Incoming conversation user payload: %s", payload)

        # ================= BASIC FIELDS =================
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        processed_data = payload.get("processed_data", [])
        raw_data = payload.get("raw_data", [])

        report_date = payload.get("report_date")
        category = payload.get("category")
        subcategory = payload.get("subcategory")
        file_url = payload.get("file_url")

        created_at = datetime.utcnow()

        # ================= VALIDATION =================
        if not patient_id or not doctor_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id and doctor_id are required"}
            )

        if not isinstance(processed_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "processed_data must be an array"}
            )

        if not isinstance(raw_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "raw_data must be an array"}
            )

        # ================= SAVE CONVERSATION =================
        doc = {
            "_id": ObjectId(),
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "processed_data": processed_data,
            "raw_data": raw_data,
            "report_date": report_date,
            "category": category,
            "subcategory": subcategory,
            "file_url": file_url,
            "created_at": created_at
        }

        result = await conversation_user_collection.insert_one(doc)

        logger.info(
            "✅ Conversation saved successfully | id=%s | patient=%s",
            result.inserted_id,
            patient_id
        )

        # =====================================================
        # 🔥 ROUTE VITALS & DOCUMENTS (SAME AS DICTATION)
        # =====================================================

        for item in processed_data:

             # =====================================================
            # 🔥 ASSERTION ROUTING (Conversation)
            # =====================================================

            logger.info(
                "🧠 Checking assertions in conversation block | conversation_id=%s",
                result.inserted_id
            )

            content = item.get("content", {})
            assertions_to_insert = []

            # ---------------- PRESENTING COMPLAINT ----------------
            presenting_complaint = content.get("presenting_complaint")
            if presenting_complaint:
                assertions_to_insert.append({
                    "_id": ObjectId(),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "type": "presenting_complaint",
                    "data": presenting_complaint,
                    "conversation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                })

                logger.info(
                    "📌 Presenting complaint found (conversation) | patient=%s",
                    patient_id
                )

            # ---------------- DIAGNOSES ----------------
            diagnoses = content.get("diagnoses", [])
            if diagnoses and isinstance(diagnoses, list):
                for diagnosis in diagnoses:
                    assertions_to_insert.append({
                        "_id": ObjectId(),
                        "patient_id": patient_id,
                        "doctor_id": doctor_id,
                        "type": "diagnosis",
                        "data": diagnosis,
                        "conversation_id": result.inserted_id,
                        "created_at": datetime.utcnow()
                    })

                logger.info(
                    "🩺 %d diagnosis assertion(s) found (conversation) | patient=%s",
                    len(diagnoses),
                    patient_id
                )

            # ---------------- FOLLOW UP ----------------
            follow_up = content.get("follow_up")
            if follow_up:
                assertions_to_insert.append({
                    "_id": ObjectId(),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "type": "follow_up",
                    "data": follow_up,
                    "conversation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                })

                logger.info(
                    "📅 Follow-up found (conversation) | patient=%s",
                    patient_id
                )

            # ---------------- RED FLAGS ----------------
            red_flags = content.get("red_flags", [])
            if red_flags and isinstance(red_flags, list):
                for flag in red_flags:
                    assertions_to_insert.append({
                        "_id": ObjectId(),
                        "patient_id": patient_id,
                        "doctor_id": doctor_id,
                        "type": "red_flag",
                        "data": {"value": flag},
                        "conversation_id": result.inserted_id,
                        "created_at": datetime.utcnow()
                    })

                logger.info(
                    "🚨 %d red flag(s) found (conversation) | patient=%s",
                    len(red_flags),
                    patient_id
                )

            # ---------------- SAVE ASSERTIONS ----------------
            if assertions_to_insert:
                await assertion_collections.insert_many(assertions_to_insert)

                logger.info(
                    "✅ Conversation assertions saved | patient=%s | total=%d",
                    patient_id,
                    len(assertions_to_insert)
                )
            else:
                logger.info(
                    "ℹ️ No assertions found in this conversation block | patient=%s",
                    patient_id
                )


            # ---------------- VITAL SIGNS ----------------
            vital_signs = content.get("vital_signs")

            if vital_signs and isinstance(vital_signs, dict):

                cleaned_vitals = {
                    k: v for k, v in vital_signs.items()
                    if k != "source" and v is not None
                }

                if cleaned_vitals:

                    timestamp = datetime.utcnow().strftime(
                        "%Y-%m-%dT%H:%M:%S_%fZ"
                    )

                    structured_payload = {
                        "doctor_id": doctor_id,
                        **cleaned_vitals
                    }

                    update_doc = {
                        "$set": {
                            f"vitals.{timestamp}": structured_payload
                        },
                        "$setOnInsert": {
                            "sys_user_id": patient_id,
                            "patient_id": patient_id
                        },
                        "$currentDate": {"updated_at": True}
                    }

                    await patient_vitals_collection.update_one(
                        {"sys_user_id": patient_id},
                        update_doc,
                        upsert=True
                    )

                    logger.info(
                        "🩺 Structured vitals saved | patient=%s | vitals=%s",
                        patient_id,
                        cleaned_vitals
                    )

            # ---------------- DOCUMENTS ----------------
            documents = item.get("documents", [])

            if documents:
                logger.info(
                    "📄 Found %d documents to save | conversation_id=%s",
                    len(documents),
                    result.inserted_id
                )

            for document in documents:

                doc_report_date = document.get("report_date")
                if not doc_report_date:
                    doc_report_date = datetime.utcnow().strftime("%d-%m-%Y")

                structured_output = [
                    {
                        "source": "conversation_llm",
                        "structured_data": document.get("report_content", {}),
                        "clinical_abstract": None
                    }
                ]

                document_doc = {
                    "_id": ObjectId(),
                    "document_id": document.get("test_name"),
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    "processed_data": structured_output,
                    "raw_data": raw_data,
                    "report_date": doc_report_date,
                    "documents": [],
                    "category": document.get("category_key"),
                    "subcategory": document.get("subcategory_key"),
                    "conversation_id": result.inserted_id,
                    "created_at": datetime.utcnow()
                }

                await document_categories_collection.insert_one(document_doc)

                logger.info(
                    "📑 Document saved | patient=%s | test=%s | category=%s",
                    patient_id,
                    document.get("test_name"),
                    document.get("category_key")
                )

        
        
        
        
        # =======================================================
        # 🔥  TEMP SAVE CONVERSATION TRIGGER (NEW)
        # =======================================================
        
        temp_payload = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "conversation": [raw_data]  # Save raw_data in the conversation field
        }

        logger.info(f"📡 Triggering temp save | {temp_payload}")

        try:
            async with httpx.AsyncClient(timeout=30) as client:
                temp_response = await client.post(
                    f"{api_base_url}hms/users/data/context/general/temp/save",
                    json=temp_payload,
                    timeout=30
                )

            if temp_response.status_code != 200:
                logger.error(
                    "Temp conversation save failed",
                    extra={
                        "status_code": temp_response.status_code,
                        "response": temp_response.text
                    }
                )

        except Exception as e:
            logger.error(f"Temp conversation save failed: {str(e)}")

        # =======================================================
        # 🔥  DOCUMENT TRIGGER CONTEXT (NEW)
        # =======================================================
        
        
        
        # ================= RESPONSE =================
        doc["id"] = str(doc["_id"])
        del doc["_id"]

        return {
            "status": "saved",
            "data": doc
        }

    except Exception as e:
        logger.error("💥 HARD FAIL:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )

