@router.post("/save_documentation_features_bulk")
async def save_documentation_features_bulk(payload: dict):

    try:
        logger.info("✅ Incoming bulk documentation payload")

        documents = payload.get("documents")

        if not documents or not isinstance(documents, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "documents must be a non-empty list"}
            )

        collection_map = {
            "documentation-treatment-plan": documentation_treatment_plan_collection,
            "documentation-investigation-notes": documentation_investigation_notes_collection,
            "documentation-medication-analysis": documentation_medication_analysis_collection,
            "documentation-treatment-summary": documentation_treatment_summary_collection,
            "documentation-clinical-notes": documentation_clinical_notes_collection,
        }

        temp_field_map = {
            "documentation-treatment-plan": "treatment_plan",
            "documentation-investigation-notes": "investigation",
            "documentation-medication-analysis": "medication_list",
            "documentation-clinical-notes": "clinical_note",
        }

        # 🔥 MAP DOCUMENTATION → CLINICAL FEATURE (FOR TRIGGER)
        trigger_feature_map = {
            "documentation-treatment-plan": "treatment_plan",
            "documentation-investigation-notes": "investigation",
            "documentation-medication-analysis": "medication",
            "documentation-clinical-notes": "clinical_note",
        }

        saved_documents = []

        for payload in documents:

            feature_id = payload.get("feature_id")
            metadata = payload.get("metadata", {})
            doctor_id = metadata.get("doctor_id")
            patient_id = metadata.get("patient_id")

            if not feature_id or not doctor_id or not patient_id:
                continue
            
            
            
            # ======================================================
            # 🔵 FETCH LATEST APPOINTMENT_ID FOR THIS PATIENT + DOCTOR
            # ======================================================
            appointment_id = None

            appt_doc = patient_appointments_collection.find_one(
                {"sys_user_id": patient_id},
                {"appointments": 1}
            )

            if appt_doc:
                matching_appts = [
                    a for a in appt_doc.get("appointments", [])
                    if a.get("doctor_id") == doctor_id
                ]
                if matching_appts:
                    def _sort_key(a):
                        return (
                            a.get("updated_at")
                            or a.get("created_at")
                            or a.get("date")
                            or ""
                        )
                    matching_appts.sort(key=_sort_key, reverse=True)
                    appointment_id = matching_appts[0].get("appointment_id")
                    logger.info(f"appointment_thomas:{appointment_id}")

            if not appointment_id:
                logger.warning(
                    f"No appointment match — patient_sys_user_id={patient_id}, "
                    f"doctor_sys_user_id={doctor_id}, "
                    f"available_doctor_ids={[a.get('doctor_id') for a in appt_doc.get('appointments', [])] if appt_doc else 'no appt_doc found'}"
                )

            collection = collection_map.get(feature_id)
            temp_field = temp_field_map.get(feature_id)

            # ======================================================
            # 🔵 TEMP CONTEXT SAVE
            # ======================================================
            if temp_field:

                temp_payload = {
                    "patient_id": patient_id,
                    "doctor_id": doctor_id,
                    temp_field: [payload.get("finaloutput")]
                }

                try:
                    async with httpx.AsyncClient(timeout=10.0) as client:
                        await client.post(
                            f"{api_base_url}hms/users/data/context/general/temp/save",
                            json=temp_payload
                        )
                except Exception as e:
                    logger.error(f"Temp reusable exception: {str(e)}")

            if collection is None:
                continue

            # ======================================================
            # 🔵 SAVE DOCUMENTATION FEATURE
            # ======================================================
            created_at = datetime.utcnow()
            document = {
                "_id": ObjectId(),
                "feature_id": feature_id,
                "feature_name": payload.get("feature_name"),
                "display_method": payload.get("display_method"),
                "patient_id": patient_id,
                "doctor_id": doctor_id,
                "appointment_id": appointment_id, 
                "finaloutput": payload.get("finaloutput"),
                "metadata": metadata,
                "status": payload.get("status"),
                "created_at": created_at
            }

            await collection.insert_one(document)
            # ======================================================
            # 🚀 HOSPITAL INTEGRATOR API TRIGGER
            # ======================================================
            try:
                await trigger_hospital_integrator(document, doctor_id,patient_id)
            except Exception as e:
                logger.error(f"Integrator trigger error: {str(e)}")
            
            document["id"] = str(document["_id"])
            del document["_id"]

            saved_documents.append(document)
            # ==========================================================
            # 🚀 TRIGGER MONGO PROCESSING (ONLY AFTER FINAL SAVE)
            # ==========================================================
            from users.celery_client import celery_app


            if saved_documents:
                try:
                    celery_app.send_task(
                        "legacy_lab_ai.process_mongo_batch",
                        kwargs={
                            "patient_id": saved_documents[0]["patient_id"],
                            "doctor_id": saved_documents[0]["doctor_id"]
                        },
                        queue="agentic_queue",
                        routing_key="agentic"
                    )

                    logger.info(
                        "🚀 Mongo processing triggered via Celery | patient=%s",
                        saved_documents[0]["patient_id"]
                    )

                except Exception as e:
                    logger.error(f"Celery Mongo trigger failed: {str(e)}")
        return {
            "status": "saved",
            "count": len(saved_documents),
            "data": saved_documents
        }

    except Exception as e:
        logger.error("💥 BULK SAVE ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )


@router.get("/get_documentation_features_by_patient/{patient_id}")
async def get_documentation_features_by_patient(patient_id: str):

    try:
        logger.info(
            "🔍 Fetching documentation features for patient_id=%s",
            patient_id
        )

        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        # ================= COLLECTIONS =================
        collections = [
            documentation_treatment_plan_collection,
            documentation_investigation_notes_collection,
            documentation_medication_analysis_collection,

            # ✅ NEW
            documentation_treatment_summary_collection,
            documentation_clinical_notes_collection,
        ]

        results = []

        for collection in collections:
            cursor = collection.find(
                {"patient_id": patient_id}
            ).sort("created_at", -1)

            async for doc in cursor:
                doc["id"] = str(doc["_id"])
                del doc["_id"]

                if doc.get("created_at"):
                    doc["created_at"] = doc["created_at"].isoformat()

                results.append(doc)

        # sort combined results by created_at desc
        results.sort(
            key=lambda x: x.get("created_at", ""),
            reverse=True
        )

        return {
            "status": "success",
            "patient_id": patient_id,
            "count": len(results),
            "data": results
        }

    except Exception as e:
        logger.error("💥 RETRIEVE ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )

@router.get("/data/context/patient/{patient_id}/consultation-history")
async def consultation_history(patient_id: str, limit: int = 5, offset: int = 0):

    cursor = dictation_collection.find(
        {"patient_id": patient_id}
    ).sort("created_at", -1)

    consultations = {}

    async for d in cursor:
        visit_id = d.get("visit_id")
        if not visit_id:
            continue

        created_at = d.get("created_at")

        created_at = d.get("created_at")

        consultations.setdefault(visit_id, {
            "date": created_at.date() if created_at else None,
            "time": created_at.strftime("%I:%M %p") if created_at else None,
            "doctor": {
                "id": d.get("doctor_id"),
                "name": d.get("doctor_name") or "-"
            },
            "notes": None,
            "vitals": None,
            "rx": [],
            "ix": []
        })



        consultations[visit_id]["notes"] = d.get("processed_data")

    cursor = conversation_user_collection.find(
        {"patient_id": patient_id}
    ).sort("created_at", -1)

    async for c in cursor:
        visit_id = c.get("visit_id")
        if visit_id in consultations:
            consultations[visit_id]["vitals"] = c.get("processed_data")

    records = list(consultations.values())[offset:offset + limit]

    return {
        
        "records": records
    }





