# ================= CORE SAVE FUNCTION =================

async def save_to_collection(payload: dict, collection):
    """
    Save logic:
    - document_type = TEST NAME
    - Append if same patient + same test (+ modality/discipline where applicable)
    - Otherwise create new document
    """

    try:
        collection_name = collection.name
        logger.info(f"✅ Incoming {collection_name} payload: %s", payload)

        # ---------- BASIC FIELDS ----------
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id", "")
        document_type = payload.get("document_type")  # ✅ TEST NAME
        report_data = payload.get("report", {})
        report_date = payload.get("report_date")
        metadata = payload.get("metadata", {})

        # ---------- HARD VALIDATION ----------
        if not patient_id:
            return JSONResponse(400, {"detail": "patient_id is required"})

        if not document_type or not document_type.strip():
            return JSONResponse(400, {"detail": "document_type (test name) is required"})

        if not report_data:
            return JSONResponse(400, {"detail": "report is required"})

        if not report_date:
            return JSONResponse(400, {"detail": "report_date is required"})

        # ---------- UNIQUE QUERY (APPEND VS CREATE) ----------
        unique_query = {
            "patient_id": patient_id,
            "document_type": document_type
        }

        # 🖼 IMAGING: modality separation REQUIRED
        if collection_name == "imaging":
            imaging_type = payload.get("imaging_type")
            if not imaging_type:
                return JSONResponse(
                    400,
                    {"detail": "imaging_type is required for imaging documents"}
                )
            unique_query["imaging_type"] = imaging_type

        # 🧪 LABORATORY: discipline separation RECOMMENDED
        if collection_name == "laboratory":
            document_subtype = payload.get("document_subtype")
            if document_subtype:
                unique_query["document_subtype"] = document_subtype

        existing_doc = await collection.find_one(unique_query)

        # ================= UPDATE (APPEND) =================
        if existing_doc:
            logger.info(f"📝 Appending report to existing {collection_name} document")

            await collection.update_one(
                {"_id": existing_doc["_id"]},
                {
                    "$push": {
                        "reports": {
                            "report": report_data,
                            "report_date": report_date,
                            "added_at": datetime.utcnow(),
                            "doctor_id": doctor_id
                        }
                    },
                    "$set": {
                        "updated_at": datetime.utcnow(),
                        "latest_report": report_data,
                        "latest_report_date": report_date,
                        "latest_doctor_id": doctor_id
                    },
                    "$inc": {"report_count": 1}
                }
            )

            return {
                "status": "updated",
                "collection": collection_name,
                "patient_id": patient_id,
                "document_id": str(existing_doc["_id"]),
                "document_type": document_type,
                "report_date": report_date,
                "report_count": existing_doc.get("report_count", 0) + 1,
                "action": "appended"
            }

        # ================= CREATE NEW =================
        logger.info(f"🆕 Creating new {collection_name} document")

        new_doc = {
            "_id": ObjectId(),
            "patient_id": patient_id,
            "document_category": collection_name,   # 🔑 links to DOCUMENT_CATEGORIES
            "document_type": document_type,         # 🔑 TEST NAME
            "created_at": datetime.utcnow(),
            "updated_at": datetime.utcnow(),
            "latest_report": report_data,
            "latest_report_date": report_date,
            "latest_doctor_id": doctor_id,
            "reports": [{
                "report": report_data,
                "report_date": report_date,
                "added_at": datetime.utcnow(),
                "doctor_id": doctor_id
            }],
            "report_count": 1,
            "metadata": metadata
        }

        # ---------- COLLECTION-SPECIFIC FIELDS ----------
        if collection_name == "imaging":
            new_doc["imaging_type"] = payload.get("imaging_type")

        if collection_name == "laboratory":
            if payload.get("document_subtype"):
                new_doc["document_subtype"] = payload.get("document_subtype")

        if collection_name == "clinical":
            if payload.get("clinical_type"):
                new_doc["clinical_type"] = payload.get("clinical_type")

        if collection_name == "surgical":
            if payload.get("procedure_name"):
                new_doc["procedure_name"] = payload.get("procedure_name")

        await collection.insert_one(new_doc)

        return {
            "status": "created",
            "collection": collection_name,
            "patient_id": patient_id,
            "document_id": str(new_doc["_id"]),
            "document_type": document_type,
            "report_date": report_date,
            "report_count": 1,
            "action": "created"
        }

    except Exception:
        logger.error(f"💥 HARD FAIL in {collection.name}:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "collection": collection.name,
                "trace": traceback.format_exc()
            }
        )



@router.get("/documents/by-patient-and-type")
async def get_documents_by_patient_and_type(
    patient_id: str,
    document_type: Optional[str] = None
):
    collections = {
        "laboratory": laboratory_collection,
        "imaging": imaging_collection,
        "clinical": clinical_collection,
        "surgical": surgical_collection,
        "pharmacy": pharmacy_collection,
        "emergency": emergency_collection,
        "discharge": discharge_collection,
        "referral": referral_collection,
        "administrative": administrative_collection,
        "specialty": specialty_collection,
        "functional": functional_collection,
    }

    results = []

    for name, collection in collections.items():
        query = {"patient_id": patient_id}

        if document_type:
            query["document_type"] = document_type  # EXACT MATCH

        cursor = collection.find(query).sort("updated_at", -1)

        async for doc in cursor:
            doc["_id"] = str(doc["_id"])
            doc["collection"] = name
            results.append(doc)

    return {
        "patient_id": patient_id,
        "document_type_filter": document_type,
        "total_documents": len(results),
        "documents": results
    }
