@router.get("/get_full_patient_record/{patient_id}")
async def get_full_patient_record(patient_id: str):
    try:
        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        # ================= PATIENT PROFILE =================
        patient_profile =  patient_user_collection.find_one(
            {"patient_id": patient_id},
            {"_id": 0}
        )

        # ================= APPOINTMENTS =================
        appointments_cursor = patient_appointments_collection.find(
            {"patient_id": patient_id}
        ).sort("date", -1)

        appointments = []
        for appt in appointments_cursor:
            doc["_id"] = str(doc["_id"])
            appointments.append(doc)  


        # ================= VITALS =================
        vitals = await patient_vitals_collection.find_one(
            {"sys_user_id": patient_id},  # <-- THIS is the real key
            {"_id": 0}
        )



        # ================= CONVERSATIONS =================
        conversation_cursor = conversation_user_collection.find(
            {"patient_id": patient_id}
        ).sort("created_at", -1)

        conversations = []
        async for doc in conversation_cursor:
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            conversations.append(doc)

        # ================= DICTATIONS =================
        dictation_cursor = dictation_collection.find(
            {"patient_id": patient_id}
        ).sort("created_at", -1)

        dictations = []
        async for doc in dictation_cursor:
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            dictations.append(doc)

        # ================= DOCUMENTATION FEATURES =================
        documentation_collections = [
            documentation_treatment_plan_collection,
            documentation_investigation_notes_collection,
            documentation_medication_analysis_collection,
            documentation_treatment_summary_collection,
            documentation_clinical_notes_collection,
        ]

        documentation = []

        for collection in documentation_collections:
            cursor = collection.find({"patient_id": patient_id}).sort("created_at", -1)
            async for doc in cursor:
                doc["id"] = str(doc["_id"])
                del doc["_id"]
                documentation.append(doc)

        documentation.sort(
            key=lambda x: x.get("created_at", ""),
            reverse=True
        )

        # ================= MEDICAL REPORTS =================
        report_collections = {
            "imaging": imaging_collection,
            "laboratory": laboratory_collection,
            "clinical": clinical_collection,
            "surgical": surgical_collection,
            "pharmacy": pharmacy_collection,
            "emergency": emergency_collection,
            "discharge": discharge_collection,
            "referral": referral_collection,
            "administrative": administrative_collection,
            "specialty": specialty_collection,
            "functional": functional_collection,
        }

        medical_documents = []

        for name, collection in report_collections.items():
            cursor = collection.find(
                {"patient_id": patient_id}
            ).sort("updated_at", -1)

            async for doc in cursor:
                doc["id"] = str(doc["_id"])
                del doc["_id"]
                doc["collection"] = name
                medical_documents.append(doc)

        # ================= DOCTOR SCREENING =================
        screening_cursor = doctor_screening_results_collection.find(
            {"patient_id": patient_id}
        ).sort("created_at", -1)

        screening_results = []
        async for doc in screening_cursor:
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            screening_results.append(doc)

        # ================= FINAL RESPONSE =================
        return {
            "status": "success",
            "patient_id": patient_id,
            "data": {
                
                "vitals": vitals,
                "conversations": conversations,
                "dictations": dictations,
                "documentation": documentation,
                "medical_documents": medical_documents,
                "screening_results": screening_results
            }
        }

    except Exception as e:
        logger.error("💥 FULL PATIENT FETCH ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )






