@router.get("/patient/{patient_id}/summary-stats")
async def get_patient_summary_stats(patient_id: str):
    """
    Get summary statistics for patient records.
    Useful for dashboard displays.
    """
    try:
        collections = get_all_collections()
        
        stats = {
            "patient_id": patient_id,
            "total_documents": 0,
            "total_reports": 0,
            "by_category": {},
            "recent_activity": [],
            "date_range": {
                "earliest": None,
                "latest": None
            }
        }
        
        earliest_date = None
        latest_date = None
        recent_docs = []
        
        for collection_name, collection in collections.items():
            count = await collection.count_documents({"patient_id": patient_id})
            
            if count > 0:
                cursor = collection.find({"patient_id": patient_id}).sort("updated_at", -1).limit(5)
                
                category_reports = 0
                async for doc in cursor:
                    category_reports += doc.get("report_count", 1)
                    
                    # Track dates
                    doc_date = doc.get("latest_report_date")
                    if doc_date:
                        if isinstance(doc_date, str):
                            doc_date = parse_date(doc_date)
                        
                        if doc_date:
                            if earliest_date is None or doc_date < earliest_date:
                                earliest_date = doc_date
                            if latest_date is None or doc_date > latest_date:
                                latest_date = doc_date
                    
                    # Add to recent activity
                    recent_docs.append({
                        "category": collection_name,
                        "document_type": doc.get("document_type"),
                        "report_date": doc.get("latest_report_date"),
                        "updated_at": doc.get("updated_at").isoformat() if isinstance(doc.get("updated_at"), datetime) else doc.get("updated_at")
                    })
                
                stats["by_category"][collection_name] = {
                    "documents": count,
                    "reports": category_reports
                }
                stats["total_documents"] += count
                stats["total_reports"] += category_reports
        
        # Sort recent activity by date
        recent_docs.sort(key=lambda x: x.get("updated_at", ""), reverse=True)
        stats["recent_activity"] = recent_docs[:10]
        
        # Set date range
        if earliest_date:
            stats["date_range"]["earliest"] = earliest_date.strftime("%Y-%m-%d")
        if latest_date:
            stats["date_range"]["latest"] = latest_date.strftime("%Y-%m-%d")
        
        return stats
        
    except Exception as e:
        logger.error(f"Error getting summary stats: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/patient/{patient_id}/document/{document_id}/full-details")
async def get_document_full_details(
    patient_id: str,
    document_id: str,
    category: str = Query(..., description="Document category")
):
    """
    Get full formatted details of a specific document.
    """
    try:
        collections = get_all_collections()
        
        if category not in collections:
            raise HTTPException(status_code=400, detail=f"Invalid category: {category}")
        
        collection = collections[category]
        
        try:
            doc = await collection.find_one({
                "_id": ObjectId(document_id),
                "patient_id": patient_id
            })
        except:
            raise HTTPException(status_code=400, detail="Invalid document_id format")
        
        if not doc:
            raise HTTPException(status_code=404, detail="Document not found")
        
        # Format for display
        formatted = format_document_for_display(doc, category)
        
        return formatted
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error getting document details: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=str(e))



@router.get("/current_context/by-patient")
async def get_current_context_by_patient(
    patient_id: str
):
    document = await current_context_collection.find_one(
        {
            "patient_id": patient_id
        },
        {"_id": 0}
    )

    if not document:
        return {
            "status": "success",
            "patient_id": patient_id,
            "current_contexts": []
        }

    contexts = document.get("current_contexts", [])

    # Sort latest first (ISO date assumed)
    contexts.sort(
        key=lambda x: datetime.fromisoformat(x["date"]),
        reverse=True
    )

    return {
        "status": "success",
        "patient_id": patient_id,
        "current_contexts": contexts
    }


@router.get("/medical_context/by-patient")
async def get_medical_context_by_patient(
    patient_id: str
):
    document = await medical_context_collection.find_one(
        {
            "patient_id": patient_id
        },
        {"_id": 0}
    )

    # No document found
    if not document:
        return {
            "status": "success",
            "patient_id": patient_id,
            "medical_contexts": []
        }

    contexts = document.get("medical_contexts", [])

    # 🔒 Safe date sort (handles YYYY-MM-DD and YYYY-MM-DDTHH:MM:SS)
    def safe_date(ctx):
        try:
            return datetime.fromisoformat(ctx["date"].split("T")[0])
        except Exception:
            return datetime.min

    contexts.sort(key=safe_date, reverse=True)

    return {
        "status": "success",
        "patient_id": patient_id,
        "medical_contexts": contexts
    }



@router.post("/save_insurance_claim")
async def save_insurance_claim(payload: dict):
    try:
        logger.info("✅ Incoming insurance claim payload: %s", payload)

        # ================= BASIC FIELDS =================
        patient_id = payload.get("patient_id")
        raw_data = payload.get("raw_data", [])

        # ================= VALIDATION =================
        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        if not isinstance(raw_data, list):
            return JSONResponse(
                status_code=400,
                content={"detail": "raw_data must be an array"}
            )

        # ================= DOCUMENT =================
        doc = {
            "_id": ObjectId(),
            "patient_id": patient_id,
            "raw_data": raw_data,
            "created_at": datetime.utcnow()
        }

        # ================= SAVE =================
        result = insurance_claims_collection.insert_one(doc)

        # ================= RESPONSE =================
        doc["id"] = str(doc["_id"])
        del doc["_id"]

        logger.info(
            "✅ Inserted insurance claim record %s",
            result.inserted_id
        )

        return {
            "status": "saved",
            "data": doc
        }

    except Exception as e:
        logger.error("💥 HARD FAIL:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )


@router.get("/get_insurance_claims/{patient_id}")
async def get_insurance_claims(patient_id: str):
    try:
        logger.info("📥 Fetching insurance claims for patient_id=%s", patient_id)

        cursor = insurance_claims_collection.find(
            {"patient_id": patient_id}
        ).sort("created_at", -1)

        claims = []
        for doc in cursor:   # ✅ NORMAL for-loop
            doc["id"] = str(doc["_id"])
            del doc["_id"]
            claims.append(doc)

        return {
            "status": "success",
            "patient_id": patient_id,
            "count": len(claims),
            "data": claims
        }

    except Exception as e:
        logger.error("💥 Failed to fetch insurance claims:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e)
            }
        )






