def normalize_llm_output(output: dict) -> dict:
    secB = (
        output
        .get("stage_mapping", {})
        .get("section_b_ajcc", {})
    )

    # Fix LLM typo
    if "prognic_stage" in secB:
        secB["prognostic_stage"] = secB.pop("prognic_stage")

    return output



