@router.post("/save_ReportAdminRule")
async def save_report_admin_rule(request: ReportAdminRuleRequest):
    try:
        logger.info("📥 Incoming rule payload: %s", request.dict())

        rule_doc = {
            "_id": ObjectId(),
            "category": request.category,
            "subcategory": request.subcategory,
            "values": request.values,
            "rule_text": request.rule_text,
            "created_at": datetime.utcnow()
        }
        logger.info("HASNA rule_doc: %s", json.dumps(rule_doc, default=str))

                           
        result = await report_rule_collection.insert_one(rule_doc)

        return {
            "status": "saved",
            "data": {
                "id": str(rule_doc["_id"]),
                "category": request.category,
                "subcategory": request.subcategory,
                "values": request.values,
                "rule_text": request.rule_text,
                "created_at": rule_doc["created_at"]
            }
        }

    except Exception as e:
        logger.error("💥 SAVE RULE ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={"detail": str(e)}
        )


@router.delete("/delete_all_ReportAdminRules")
async def delete_all_report_admin_rules():
    try:
        logger.info("🗑️ Deleting all documents from report_rule_collection")

        result = await report_rule_collection.delete_many({})

        logger.info(
            "✅ Deleted %s report admin rules",
            result.deleted_count
        )

        return {
            "status": "deleted",
            "deleted_count": result.deleted_count
        }

    except Exception as e:
        logger.error("💥 DELETE ALL RULES ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e)
            }
        )


@router.delete("/delete_ReportAdminRule/{rule_id}")
async def delete_report_admin_rule(rule_id: str = Path(...)):
    try:
        logger.info("🗑️ Delete request for rule ID: %s", rule_id)

        # ===== VALIDATE MONGO ID =====
        if not ObjectId.is_valid(rule_id):
            return JSONResponse(
                status_code=400,
                content={"detail": "Invalid rule id"}
            )

        # ===== DELETE DOCUMENT =====
        result = await report_rule_collection.delete_one(
            {"_id": ObjectId(rule_id)}
        )

        if result.deleted_count == 0:
            return JSONResponse(
                status_code=404,
                content={"detail": "Rule not found"}
            )

        logger.info("✅ Rule deleted successfully: %s", rule_id)

        return {
            "status": "deleted",
            "id": rule_id
        }

    except Exception as e:
        logger.error("💥 DELETE RULE ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e)
            }
        )


