# =========================
# ENUMS
# =========================

class StatusEnum(str, Enum):
    VERIFIED = "verified"
    PENDING = "pending"
    FLAGGED = "flagged"
    SUCCESS = "success"
    WARNING = "warning"
    DANGER = "danger"
    EXTRACTED = "Extracted"
    NOT_UPLOADED = "Not Uploaded"
    NOT_APPLICABLE = "Not Applicable"
    APPROVED = "APPROVED"


class CancerTypeEnum(str, Enum):
    BREAST_CANCER = "breast_cancer"
    LUNG_CANCER = "lung_cancer"
    COLON_CANCER = "colon_cancer"
    PROSTATE_CANCER = "prostate_cancer"
    OTHER = "other"



class VitalRecord(BaseModel):
    recorded_at: Optional[datetime] = None   # date of vitals
    temperature: Optional[float] = None      # °C
    pulse: Optional[int] = None              # bpm
    blood_pressure: Optional[str] = None     # "120/80"
    respiratory_rate: Optional[int] = None   # breaths/min
    spo2: Optional[int] = None               # %
    weight: Optional[float] = None           # kg
    height: Optional[float] = None           # cm
    bmi: Optional[float] = None              # auto or manual
    pain_score: Optional[int] = None         # 0–10

    ecog_status: Optional[int] = None
    karnofsky_score: Optional[int] = None
    chemo_cycle: Optional[int] = None
    weight_loss_percent: Optional[float] = None

    # Flexible extension field
    other_vitals: Optional[Dict[str, Any]] = None
    notes: Optional[str] = None

# =========================
# OCR MODELS
# =========================

class OCRDocumentStatus(BaseModel):
    status: Optional[str] = None
    confidence: Optional[float] = None
    document_name: Optional[str] = None


class OCRDataExtraction(BaseModel):
    accuracy: Optional[float] = None
    summary: Optional[str] = None

    # KEY CHANGE: dict instead of list
    documents_processed: Optional[Dict[str, OCRDocumentStatus]] = None

    diagnostic_data: Optional[Dict[str, Any]] = None


# =========================
# DIAGNOSIS / STAGING / PROTOCOL
# =========================

class DiagnosisValidation(BaseModel):
    status: Optional[str] = None
    summary: Optional[str] = None
    documentation_validation_score: Optional[float] = None


class StageMapping(BaseModel):
    summary: Optional[Dict[str, str]] = None
    accuracy_score: Optional[float] = None


class ProtocolVerification(BaseModel):
    guideline: Optional[str] = None
    compliance_score: Optional[float] = None


# =========================
# INSURANCE / BILLING
# =========================

class InsuranceCriteria(BaseModel):
    overall_status: Optional[str] = None
    checks_passed: Optional[int] = None


class BillVerification(BaseModel):
    summary: Optional[Dict[str, float]] = None


# =========================
# MEDICAL NECESSITY
# =========================

class MedicalNecessity(BaseModel):
    overall_score: Optional[float] = None
    confidence: Optional[float] = None


# =========================
# FINAL DECISION
# =========================

class FinalDecision(BaseModel):
    recommendation: Optional[str] = None
    confidence_score: Optional[float] = None


# =========================
# CONTEXT / FLAGS (EMPTY OBJECT SAFE)
# =========================

class CaseContext(BaseModel):
    pass


class DocumentExpectations(BaseModel):
    pass


class DataCompleteness(BaseModel):
    pass


class AuditFlags(BaseModel):
    pass



