class OncologyVerificationRequest(BaseModel):
    case_number: Optional[str] = None
    patient_name: Optional[str] = None
    patient_id: Optional[str] = None
    hospital_id: Optional[str] = None

    cancer_type_display: Optional[str] = None
    cancer_stage_display: Optional[str] = None
    claim_amount: Optional[float] = None
    policy_number: Optional[str] = None
    hospital_name: Optional[str] = None
    vitals: Optional[List[VitalRecord]] = None
    ocr_extraction: Optional[OCRDataExtraction] = None
    diagnosis_validation: Optional[DiagnosisValidation] = None
    stage_mapping: Optional[StageMapping] = None
    protocol_verification: Optional[ProtocolVerification] = None
    insurance_criteria: Optional[InsuranceCriteria] = None
    bill_verification: Optional[BillVerification] = None
    medical_necessity: Optional[MedicalNecessity] = None
    final_decision: Optional[FinalDecision] = None

    case_context: Optional[CaseContext] = None
    document_expectations: Optional[DocumentExpectations] = None
    data_completeness: Optional[DataCompleteness] = None
    audit_flags: Optional[AuditFlags] = None
    # biology: Optional[Biology] = None

    ai_confidence_score: Optional[float] = None
    processed_by: Optional[str] = None
    # ✅ ADD THESE TWO
    verification_status: Optional[str] = None
    verification_timestamp: Optional[datetime] = None


@router.post("/oncology-verification")
async def create_or_update_oncology_verification(request: Request):
    logger.info("Oncology verification upsert initiated")

    try:
        data = await request.json()
        logger.info("Payload received: %s", data)
        logger.debug(f"Incoming payload keys: {list(data.keys())}")

        # -----------------------------
        # REQUIRED VALIDATION
        # -----------------------------
        if not data.get("case_number"):
            raise HTTPException(status_code=400, detail="case_number is required")

        if not data.get("patient_id"):
            raise HTTPException(status_code=400, detail="patient_id is required")

        case_number = data["case_number"]
        patient_id = data["patient_id"]
        now = datetime.utcnow()

        logger.info(
            f"Upserting oncology verification | "
            f"case_number={case_number} | patient_id={patient_id}"
        )

        # -----------------------------
        # OBJECT CONSTRUCTION
        # -----------------------------
        # verification_obj = OncologyVerificationRequest(
        #     case_number=case_number,
        #     hospital_id=data["hospital_id"],
        #     patient_id=patient_id,

        #     patient_name=data["patient_name"],
        #     cancer_type_display=data.get("cancer_type_display"),
        #     cancer_stage_display=data.get("cancer_stage_display"),
        #     claim_amount=data["claim_amount"],
        #     policy_number=data["policy_number"],
        #     hospital_name=data.get("hospital_name"),

        #     ocr_extraction=OCRDataExtraction(**data["ocr_extraction"]),
        #     diagnosis_validation=CancerDiagnosis(**data["diagnosis_validation"]),
        #     stage_mapping=TNMStaging(**data["stage_mapping"]),
        #     protocol_verification=TreatmentProtocol(**data["protocol_verification"]),
        #     insurance_criteria=InsuranceVerification(**data["insurance_criteria"]),
        #     bill_verification=BillVerification(**data["bill_verification"]),
        #     fraud_analysis=FraudAnalysis(**data["fraud_analysis"]),
        #     medical_necessity=MedicalNecessityScore(**data["medical_necessity"]),
        #     final_decision=FinalDecision(**data["final_decision"]),

        #     case_context=CaseContext(**data["case_context"]),
        #     document_expectations=DocumentExpectations(**data["document_expectations"]),
        #     data_completeness=DataCompleteness(**data["data_completeness"]),
        #     audit_flags=AuditFlags(**data["audit_flags"]),
        #     biology=Biology(**data["biology"]) if data.get("biology") else None,



        #     verification_timestamp=now,
        #     ai_confidence_score=data.get("ai_confidence_score"),
        #     verification_status=StatusEnum.PENDING,
        #     processed_by=data.get("processed_by")
        # )

        verification_obj = OncologyVerificationRequest(
            **data,
            verification_timestamp=now,
            verification_status=StatusEnum.PENDING
        )

        verification_dict = verification_obj.model_dump(exclude_none=True)

        logger.info("Saving oncology verification document: %s", verification_dict)


        # -----------------------------
        # UPSERT INTO DB (case + patient)
        # -----------------------------
        result = insurance_verification_collection.update_one(
            {
                "case_number": case_number,
                "patient_id": patient_id
            },
            {
                "$set": {
                    **verification_dict,
                    "updated_at": now
                },
                "$setOnInsert": {
                    "created_at": now
                }
            },
            upsert=True
        )

        action = "updated" if result.matched_count > 0 else "created"

        logger.info(
            f"Oncology verification {action} | "
            f"case_number={case_number} | patient_id={patient_id}"
        )

        return {
            "status": "success",
            "action": action,
            "case_number": case_number,
            "patient_id": patient_id
        }

    except HTTPException:
        raise

    except Exception:
        logger.exception("Unexpected error during oncology verification upsert")
        raise HTTPException(status_code=500, detail="Internal server error")



