@router.get("/oncology-verification/by-patient/{patient_id}")
async def get_oncology_verifications_by_patient(patient_id: str):
    logger.info(
        f"Fetching oncology verifications for patient | patient_id={patient_id}"
    )

    try:
        records = list(
            insurance_verification_collection.find(
                {"patient_id": patient_id},
                {"_id": 0}  # exclude Mongo ObjectId
            )
        )

        if not records:
            logger.warning(
                f"No oncology verifications found | patient_id={patient_id}"
            )
            return {
                "status": "success",
                "count": 0,
                "data": []
            }

        # ✅ Re-validate using Pydantic model
        validated_records = [
            OncologyVerificationRequest(**record).model_dump()
            for record in records
        ]

        logger.info(
            f"Oncology verifications retrieved | "
            f"patient_id={patient_id} | count={len(records)}"
        )

        return {
            "status": "success",
            "count": len(records),
            "data": records
        }

    except Exception:
        logger.exception(
            "Unexpected error during oncology verification retrieval by patient_id"
        )
        raise HTTPException(
            status_code=500,
            detail="Internal server error"
        )


@router.get("/get_agentic_data")
async def get_agentic_data(
    patient_id: str = Query(...),
    doctor_id: str = Query(...)
):
    try:
        logger.info(
            "🔍 Fetching agentic data for patient=%s doctor=%s",
            patient_id,
            doctor_id
        )

        # ================= FETCH =================
        doc = await agentic_data_collection.find_one(
            {
                "patient_id": patient_id,
                "doctor_id": doctor_id
            }
        )

        if not doc:
            return JSONResponse(
                status_code=404,
                content={"detail": "No agentic data found"}
            )

        # ================= CLEAN RESPONSE =================
        doc["id"] = str(doc["_id"])
        del doc["_id"]

        return {
            "status": "success",
            "data": doc
        }

    except Exception as e:
        logger.error("💥 HARD FAIL:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e),
                "trace": traceback.format_exc()
            }
        )


