def sanitize_document_data(document_records) -> list:
    logger.info(f"🔍 sanitize_document_data received type: {type(document_records)}")
    
    sanitized = []

    if not document_records:
        logger.info("📄 document_records is empty")
        return sanitized

    if isinstance(document_records, str):
        try:
            document_records = json.loads(document_records)
            logger.info("📄 Parsed string to JSON")
        except json.JSONDecodeError:
            logger.error("❌ Failed to parse JSON string")
            return sanitized

    if not isinstance(document_records, list):
        logger.info(f"📄 document_records is not a list, it's {type(document_records)}")
        
        # Handle the case where it's a dict with 'data' key
        if isinstance(document_records, dict):
            logger.info(f"📄 Dict keys: {list(document_records.keys())}")
            
            if 'data' in document_records:
                logger.info(f"📄 Found 'data' key with type: {type(document_records['data'])}")
                if isinstance(document_records['data'], list):
                    logger.info(f"📄 'data' is a list with {len(document_records['data'])} items")
                    document_records = document_records['data']
                else:
                    logger.info(f"📄 'data' is not a list, it's {type(document_records['data'])}")
            elif 'documents' in document_records:
                logger.info(f"📄 Found 'documents' key with type: {type(document_records['documents'])}")
                if isinstance(document_records['documents'], list):
                    logger.info(f"📄 'documents' is a list with {len(document_records['documents'])} items")
                    document_records = document_records['documents']
            else:
                # Try to use the dict itself as a single document
                logger.info("📄 No list found, treating dict as single document")
                document_records = [document_records]
        else:
            logger.info(f"📄 Cannot handle type: {type(document_records)}")
            return sanitized

    logger.info(f"📄 Processing {len(document_records)} documents")

    for i, doc in enumerate(document_records):
        logger.info(f"📄 Document {i} type: {type(doc)}")
        
        if not isinstance(doc, dict):
            logger.info(f"📄 Document {i} is not a dict, skipping")
            continue

        full_text_parts = []

        # 1️⃣ RAW OCR TEXT (CRITICAL)
        raw_data = doc.get("raw_data", [])
        logger.info(f"📄 Document {i} raw_data length: {len(raw_data)}")
        
        for raw in raw_data:
            if isinstance(raw, dict):
                content = raw.get("content")
                if content:
                    full_text_parts.append(str(content))
                    logger.info(f"📄 Added raw content (length: {len(str(content))})")

        # 2️⃣ Clinical abstract
        processed_data = doc.get("processed_data", [])
        logger.info(f"📄 Document {i} processed_data length: {len(processed_data)}")
        
        for item in processed_data:
            if isinstance(item, dict):
                abstract = item.get("clinical_abstract")
                if abstract:
                    full_text_parts.append(str(abstract))
                    logger.info(f"📄 Added clinical abstract")

                # 3️⃣ Structured data flatten
                structured = item.get("structured_data", {})
                if isinstance(structured, dict):
                    structured_json = json.dumps(structured)
                    full_text_parts.append(structured_json)
                    logger.info(f"📄 Added structured data (length: {len(structured_json)})")

        sanitized.append({
            "document_id": doc.get("document_id"),
            "patient_id": doc.get("patient_id"),
            "doctor_id": doc.get("doctor_id"),
            "created_at": doc.get("created_at"),
            "document_type": f"{doc.get('category','')}_{doc.get('subcategory','')}",
            "processed_data": doc.get("processed_data", []),
            "raw_data": doc.get("raw_data", []),
            "full_text": " ".join(full_text_parts).lower()
        })
        
        logger.info(f"📄 Document {i} full_text length: {len(sanitized[-1]['full_text'])}")

    logger.info(f"✅ sanitize_document_data returning {len(sanitized)} documents")
    return sanitized

def extract_radiology_tumor_details(document_data: list) -> dict:
    tumor_info = {
        "all_tumor_sizes_cm": [],
        "largest_tumor_cm": None,
        "tumor_locations": [],
        "laterality": set(),
        "axillary_levels": set(),
        "nodal_metastasis": False,
        "distant_metastasis": False,
        "imaging_sources": set()
    }

    size_pattern = r"(\d+(?:\.\d+)?)\s*[xX]\s*(\d+(?:\.\d+)?)\s*(?:x\s*(\d+(?:\.\d+)?))?\s*(mm|cm)"

    for doc in document_data:
        doc_type = (doc.get("document_type") or "").lower()
        segment_text = ""

        for item in doc.get("processed_data", []):
            for segment in item.get("content", {}).get("segments", []):
                segment_text += json.dumps(segment.get("extracted_data", {})).lower()

        doc_text = (doc.get("full_text") or "").lower()
        text = f"{segment_text} {doc_text}"



        # ---------- Extract multi-dimensional tumor sizes ----------
        for match in re.findall(size_pattern, text):
            values = [float(v) for v in match[:3] if v]
            unit = match[3]

            largest_dimension = max(values)

            if unit == "mm":
                largest_dimension /= 10

            tumor_info["all_tumor_sizes_cm"].append(round(largest_dimension, 2))

        # ---------- Laterality ----------
        if "right breast" in text:
            tumor_info["laterality"].add("Right")
        if "left breast" in text:
            tumor_info["laterality"].add("Left")
        if "bilateral" in text:
            tumor_info["laterality"].add("Bilateral")

        # ---------- Axillary levels ----------
        if "level i" in text:
            tumor_info["axillary_levels"].add("Level I")
        if "level ii" in text:
            tumor_info["axillary_levels"].add("Level II")
        if "internal mammary" in text:
            tumor_info["axillary_levels"].add("Internal Mammary")
        if "deep pectoral" in text:
            tumor_info["axillary_levels"].add("Deep Pectoral")

        # ---------- Nodal metastasis ----------
        if any(word in text for word in [
            "fdg avid right axillary",
            "nodal metastasis",
            "metastatic lymph",
            "enlarged right axillary",
            "internal mammary lymph node",
            "deep pectoral lymph node"
        ]):
            tumor_info["nodal_metastasis"] = True



        # ---------- Distant metastasis ----------
        # if "no distant metastasis" in text:
        #     tumor_info["distant_metastasis"] = False
        # elif "metastasis" in text:
        #     tumor_info["distant_metastasis"] = True

        if any(neg in text for neg in [
            "no distant metastasis",
            "no metastasis",
            "no evidence of metastasis",
            "no metastatic lesion",
            "no definitive scan evidence"
        ]):
            tumor_info["distant_metastasis"] = False
        elif any(pos in text for pos in [
            "liver metastasis",
            "lung metastasis",
            "skeletal metastasis",
            "bone metastasis",
            "brain metastasis",
            "distant metastasis"
        ]):
            tumor_info["distant_metastasis"] = True


        tumor_info["imaging_sources"].add(doc_type.upper())

    if tumor_info["all_tumor_sizes_cm"]:
        tumor_info["largest_tumor_cm"] = max(tumor_info["all_tumor_sizes_cm"])

    tumor_info["laterality"] = list(tumor_info["laterality"])
    tumor_info["axillary_levels"] = list(tumor_info["axillary_levels"])
    tumor_info["imaging_sources"] = list(tumor_info["imaging_sources"])

    return tumor_info



def force_schema_safety(output: dict) -> dict:
    # Stage summary must be string
    if isinstance(output.get("stage_mapping", {}).get("summary"), dict):
        output["stage_mapping"]["summary"] = ""

    # Force int scores
    def clamp_score(val):
        if isinstance(val, float):
            return int(val * 100) if val <= 1 else int(val)
        if isinstance(val, int):
            return val
        return 0

    output["stage_mapping"]["accuracy_score"] = clamp_score(
        output["stage_mapping"].get("accuracy_score")
    )

    output["treatment_protocol"]["compliance_score"] = clamp_score(
        output["treatment_protocol"].get("compliance_score")
    )

    output["ai_summary"]["confidence_score"] = clamp_score(
        output["ai_summary"].get("confidence_score")
    )

    return output


