@router.get("/get-current-plan/{patient_id}/{doctor_id}")
async def get_current_plan(patient_id: str, doctor_id: str):
    try:
        # Search for documents matching the patient_id, doctor_id, and plan_status in draft, continue, or modified
        data_cursor = documentation_treatment_plan_collection.find({
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "metadata.plan_status": {"$in": ["draft", "current", "continue", "modified"]}  # Only consider plans that can be returned
        }).sort([("metadata.last_modified", -1)])  # Sort by last_modified to get the latest plan
        
        data = await data_cursor.to_list(length=1)  # Take only the latest document

        if not data:
            raise HTTPException(status_code=404, detail="No data found")

        # Get the latest plan
        latest_plan = data[0]
        plan_status = latest_plan.get("metadata", {}).get("plan_status", "")

        # Return no data if the status is "stopped"
        if plan_status == "stopped":
            return {"message": "The latest plan is stopped, no data to return."}

        # Convert the ObjectId to string for JSON serialization if needed
        latest_plan["_id"] = str(latest_plan["_id"])

        return {"data": latest_plan}  # Return the entire content of the latest plan

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.put("/update-plan-status/{patient_id}/{doctor_id}")
async def update_plan_status(patient_id: str, doctor_id: str):
    try:
        # Define the new status as "stopped"
        new_status = "stopped"

        # Search for the latest plan matching the patient_id and doctor_id
        data_cursor = documentation_treatment_plan_collection.find({
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "metadata.plan_status": {"$in": ["draft", "current","continue", "modified"]}  # Only consider plans that can be updated
        }).sort([("metadata.last_modified", -1)])  # Sort by last_modified to get the latest plan
        
        data = await data_cursor.to_list(length=1)  # Take only the latest document

        if not data:
            raise HTTPException(status_code=404, detail="No plan found")

        # Get the latest plan
        latest_plan = data[0]
        plan_status = latest_plan.get("metadata", {}).get("plan_status", "")

        # If the current status is already 'stopped' or 'deleted', do not update
        if plan_status == "stopped":
            return {"message": "The latest plan is already stopped, no updates can be made."}

        # Update the status of the plan to 'stopped'
        update_result = await documentation_treatment_plan_collection.update_one(
            {"_id": latest_plan["_id"]},
            {"$set": {"metadata.plan_status": new_status}}
        )

        if update_result.modified_count == 0:
            raise HTTPException(status_code=500, detail="Failed to update plan status")

        return {"message": "Plan status updated to stopped"}

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.get("/documentation-medication-analysis/{patient_id}/{doctor_id}")
async def get_medication_analysis_by_patient_doctor(patient_id: str, doctor_id: str):
    try:
        # Fetch all documents based on patient_id and doctor_id asynchronously from the collection
        data_cursor = documentation_medication_analysis_collection.find({
            "doctor_id": doctor_id,
            "patient_id": patient_id
        })
        data = await data_cursor.to_list(length=None)
        
        if not data:
            raise HTTPException(status_code=404, detail="No data found for this doctor and patient")

        # Prepare the data grouped by date
        result = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "data": []
        }

        for entry in data:
            # Convert the _id to string to avoid serialization issues
            entry["_id"] = str(entry["_id"])

            created_at = entry.get("created_at")
            
            if isinstance(created_at, str):
                # If created_at is a string, strip spaces and parse the date string to datetime
                date_str = datetime.strptime(created_at.strip(), "%Y-%m-%dT%H:%M:%S.%f").strftime("%Y-%m-%d")
            elif isinstance(created_at, datetime):
                # If it's already a datetime object, format it directly
                date_str = created_at.strftime("%Y-%m-%d")
            else:
                # If the format is unexpected, raise an error
                raise HTTPException(status_code=500, detail="Unexpected date format in the database")

            # Add the date for each entry
            entry['date'] = date_str  # Adding the date field to each entry

            result["data"].append(entry)

        return result
    
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))






