@router.get("/get-patient-last-appointment")
async def get_patient_last_appointment(patient_id: str, doctor_id: str):
    # Fetch the appointment document for this patient
    appointment_doc = patient_appointments_collection.find_one(
        {
            "sys_user_id": patient_id,
            "appointments.doctor_id": doctor_id  # only fetch docs that have this doctor
        }
    )

    if not appointment_doc:
        raise HTTPException(
            status_code=404,
            detail="No appointments found for this patient with the given doctor"
        )

    # Filter appointments array for the specific doctor, then pick the latest by updated_at
    doctor_appointments = [
        apt for apt in appointment_doc.get("appointments", [])
        if apt.get("doctor_id") == doctor_id
    ]

    if not doctor_appointments:
        raise HTTPException(
            status_code=404,
            detail="No appointments found for this doctor"
        )

    # Sort by updated_at descending and pick the latest
    last_appointment = sorted(
        doctor_appointments,
        key=lambda x: x.get("updated_at", datetime.min),
        reverse=True
    )[0]

    return {
        "patient_id": patient_id,
        "doctor_id": doctor_id,
        "last_appointment": last_appointment
    }


