async def get_patient_info(patient_id: str):

    # 1️⃣ Get patient basic details
    patient = patient_user_collection.find_one({"sys_user_id": patient_id})

    if not patient:
        raise HTTPException(status_code=404, detail="Patient not found")

    # 2️⃣ Get latest appointment using created_at
    appointment = patient_appointments_collection.find_one(
        {"sys_user_id": patient_id},
        sort=[("created_at", -1)]
    )

    department = None

    if appointment:
        doctor_id = appointment.get("doctor_id")

        # 3️⃣ Fetch doctor to get specialization
        doctor = db["users"].find_one({"sys_user_id": doctor_id})

        if doctor:
            department = doctor.get("specialization")

    # 4️⃣ Calculate age
    age = None
    dob = patient.get("date_of_birth")

    if dob:
        try:
            if isinstance(dob, str):
                dob = datetime.fromisoformat(dob)

            today = datetime.today()
            age = today.year - dob.year - (
                (today.month, today.day) < (dob.month, dob.day)
            )
        except:
            age = None

    # 5️⃣ Get diagnosis
    diagnosis = ""
    try:
        diagnosis_doc = await diagnosis_data_collection.find_one(
            {
                "patient_id": patient_id,
                "type": "diagnosis"
            },
            sort=[("updated_at", -1)]
        )
        if diagnosis_doc and "diagnosis" in diagnosis_doc:
            diagnosis = diagnosis_doc["diagnosis"]
    except Exception as e:
        logger.error(f"Error fetching diagnosis for patient {patient_id}: {e}")

    return {
        "patient_name": patient.get("name"),
        "hms_id": patient.get("hms_id"),
        "age": age,
        "gender": patient.get("gender"),
        "diagnosis": diagnosis
    }



