@router.post("/general/temp/save")
async def save_temp_data(data: TempDataUpdate):
    try:

        today_date = datetime.utcnow().date().isoformat()

        payload_dict: Dict[str, Any] = data.model_dump(exclude_none=True)

        patient_id = payload_dict.pop("patient_id")
        doctor_id = payload_dict.pop("doctor_id")

        # ==========================================================
        # Build Mongo Document
        # ==========================================================
        document = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "created_at": today_date,
            "updated_at": today_date,
        }

        for field_name, field_value in payload_dict.items():
            document[field_name] = {
                "data": field_value,
                "date": today_date
            }

            # Optional: Store document type
            document["document_name"] = field_name

        # ==========================================================
        # Insert New Mongo Document
        # ==========================================================
        result = await temp_data_collection.insert_one(document)

        temp_document_id = str(result.inserted_id)

        # ==========================================================
        # Trigger Mongo Processing
        # ==========================================================
        try:
            
            celery_app.send_task(
                "legacy_lab_ai.process_mongo_batch",
                kwargs={
                    "temp_document_id": temp_document_id
                },
                queue="agentic_queue",
                routing_key="agentic"
            )

        except Exception as e:
            logger.error(f"Mongo Celery Trigger Failed: {str(e)}")

        return {
            "status": "success",
            "message": "Reusable temp data saved",
            "temp_document_id": temp_document_id,
            "updated_fields": list(payload_dict.keys())
        }

    except Exception as e:
        logger.exception("Temp save failed")
        raise HTTPException(status_code=500, detail=str(e))
    
    
    
    
