def extract_feature_events(feature_name: str, feature_data: dict):
    """
    Normalize generic feature events into timeline items
    """
    items = []

    events = feature_data.get("event", [])

    for ev in events:
        ts = ev.get("timestamp") or ev.get("date") or ev.get("created_at")

        if not ts:
            continue

        try:
            if isinstance(ts, str):
                dt = datetime.fromisoformat(ts.replace("Z", ""))
            else:
                dt = ts
        except:
            continue

        items.append({
            "feature": feature_name,
            "timestamp": dt.isoformat(),
            "data": ev.get("data"),
        })

    return items


def extract_document_events(document_block: dict):
    """
    Handle:
    document.<category>.<subcategory>.event
    """
    items = []

    for category, subcats in document_block.items():

        if not isinstance(subcats, dict):
            continue

        for subcategory, payload in subcats.items():

            events = payload.get("event", [])

            for ev in events:

                ts = ev.get("timestamp") or ev.get("date")

                if not ts:
                    continue

                try:
                    dt = datetime.fromisoformat(ts.replace("Z", ""))
                except:
                    continue

                items.append({
                    "feature": f"document.{category}.{subcategory}",
                    "timestamp": dt.isoformat(),
                    "data": ev.get("data"),
                })

    return items


@router.get("/timeline/{patient_id}")
async def get_patient_timeline(patient_id: str):

    doc = await eventdb_collection.find_one({"patient_id": patient_id})

    if not doc:
        return {"timeline": []}

    timeline = []

    # =====================================================
    # GENERIC FEATURES (vitals, medication, etc.)
    # =====================================================
    for key, value in doc.items():

        if not isinstance(value, dict):
            continue

        if "event" in value:
            timeline.extend(extract_feature_events(key, value))

    # =====================================================
    # DOCUMENT FEATURES
    # =====================================================
    if "document" in doc:
        timeline.extend(extract_document_events(doc["document"]))

    # =====================================================
    # GROUP BY DATE
    # =====================================================
    grouped = defaultdict(list)

    for item in timeline:
        date_key = item["timestamp"][:10]  # YYYY-MM-DD
        grouped[date_key].append(item)

    # Sort each day by time
    for d in grouped:
        grouped[d].sort(key=lambda x: x["timestamp"], reverse=True)

    # Convert to sorted list
    result = [
        {
            "date": date,
            "events": grouped[date]
        }
        for date in sorted(grouped.keys(), reverse=True)
    ]

    return {"timeline": result}





