from bson import ObjectId


def serialize_mongo_doc(doc):
    """
    Recursively convert ObjectId to string
    """
    if isinstance(doc, list):
        return [serialize_mongo_doc(item) for item in doc]

    if isinstance(doc, dict):
        new_doc = {}
        for key, value in doc.items():
            if isinstance(value, ObjectId):
                new_doc[key] = str(value)
            elif isinstance(value, (dict, list)):
                new_doc[key] = serialize_mongo_doc(value)
            else:
                new_doc[key] = value
        return new_doc

    return doc


@router.get("/get_assertions_by_patient")
async def get_assertions_by_patient(patient_id: str):

    try:
        logger.info(
            "🔍 Fetching assertions for patient_id=%s",
            patient_id
        )

        if not patient_id:
            return JSONResponse(
                status_code=400,
                content={"detail": "patient_id is required"}
            )

        # ================= QUERY =================
        cursor = assertion_collections.find(
            {"patient_id": patient_id}
        ).sort("created_at", -1)

        results = []

        async for doc in cursor:
            doc = serialize_mongo_doc(doc)

            # Rename _id to id
            doc["id"] = doc.pop("_id")

            results.append(doc)

        logger.info(
            "✅ Assertions fetched successfully | patient=%s | count=%s",
            patient_id,
            len(results)
        )

        return {
            "status": "success",
            "patient_id": patient_id,
            "count": len(results),
            "data": results
        }

    except Exception as e:
        logger.error(
            "💥 HARD FAIL (ASSERTION FETCH):\n%s",
            traceback.format_exc()
        )

        return JSONResponse(
            status_code=500,
            content={
                "status": "error",
                "detail": str(e)
            }
        )

