@router.post("/save_ContextAdminRuleByDoctor")
async def save_context_admin_rule_by_doctor(doctor_id: str, request: ContextAdminRuleRequest):
    try:
        # 1️⃣ Fetch Doctor
        doctor = doctor_user_collection.find_one(
            {"sys_user_id": doctor_id},
            {"_id": 0, "specialization": 1, "speciality": 1}
        )

        if not doctor:
            return JSONResponse(
                status_code=404,
                content={"detail": "Doctor not found"}
            )

        # 2️⃣ Resolve Speciality (normalize)
        speciality = (
            doctor.get("specialization")
            or doctor.get("speciality")
            or ""
        ).strip()

        if not speciality:
            return JSONResponse(
                status_code=400,
                content={"detail": "Doctor has no specialization configured"}
            )

        # 3️⃣ Create Rule Document
        context_rule_doc = {
            "_id": ObjectId(),
            "speciality": speciality,
            "medical_context_categories": request.medical_context_categories,
            "medical_context_rule": request.medical_context_rule,
            "current_context_categories": request.current_context_categories,
            "current_context_rule": request.current_context_rule,
            "created_at": datetime.utcnow(),
            "created_from_doctor_id": doctor_id  # optional audit tracking
        }

        context_rule_collection.insert_one(context_rule_doc)

        return {
            "status": "saved",
            "message": f"Admin rule saved for speciality '{speciality}' (from doctor {doctor_id})",
            "data": {
                "id": str(context_rule_doc["_id"]),
                "speciality": speciality,
                "created_at": context_rule_doc["created_at"]
            }
        }

    except Exception as e:
        logger.exception("SAVE ADMIN RULE BY DOCTOR FAILED")
        return JSONResponse(
            status_code=500,
            content={"detail": str(e)}
        )
