class ContextAdminRuleDoctorRequest(BaseModel):
    doctor_id: str   # ✅ VERY IMPORTANT
    speciality: str
    medical_context_categories: List[str]
    medical_context_rule: str
    current_context_categories: List[str]
    current_context_rule: str
    is_active: bool




@router.post("/save_ContextAdminDoctorRule")
async def save_context_admin_doctor_rule(request: ContextAdminRuleDoctorRequest):
    try:
        logger.info("📥 Incoming DOCTOR CONTEXT rule payload: %s", request.dict())

        # Check if rule already exists for this doctor
        existing_rule = context_rule_doctor_collection.find_one(
            {"doctor_id": request.doctor_id}
        )

        update_data = {
            "doctor_id": request.doctor_id,
            "speciality": request.speciality,
            "medical_context_categories": request.medical_context_categories,
            "medical_context_rule": request.medical_context_rule,
            "current_context_categories": request.current_context_categories,
            "current_context_rule": request.current_context_rule,
            "is_active": request.is_active,
            "updated_at": datetime.utcnow()
        }

        if existing_rule:
            # ✅ UPDATE existing rule
            context_rule_doctor_collection.update_one(
                {"_id": existing_rule["_id"]},
                {"$set": update_data}
            )

            return {
                "status": "updated",
                "message": "Doctor context rule updated successfully",
                "id": str(existing_rule["_id"])
            }

        else:
            # ✅ INSERT new rule
            update_data["_id"] = ObjectId()
            update_data["created_at"] = datetime.utcnow()

            context_rule_doctor_collection.insert_one(update_data)

            return {
                "status": "saved",
                "message": "Doctor context rule created successfully",
                "id": str(update_data["_id"])
            }

    except Exception as e:
        logger.error("💥 SAVE DOCTOR CONTEXT RULE ERROR:\n%s", traceback.format_exc())
        return JSONResponse(
            status_code=500,
            content={"detail": str(e)}
        )



