# Create collection for patient intake data
patient_intake_collection = db["patient_intake_assessments"]

# Pydantic models for the intake form
class VitalsAssessment(BaseModel):
    heartRate: Optional[str] = ""
    systolicBP: Optional[str] = ""
    diastolicBP: Optional[str] = ""
    spo2: Optional[str] = ""
    respiratoryRate: Optional[str] = ""
    temperature: Optional[str] = ""

class NeurologicalStatus(BaseModel):
    consciousnessLevel: Optional[str] = ""
    gcsEye: Optional[str] = ""
    gcsVerbal: Optional[str] = ""
    gcsMotor: Optional[str] = ""
    pupilReaction: Optional[str] = ""

class InjurySymptoms(BaseModel):
    injuryType: Optional[str] = ""
    externalBleeding: Optional[str] = ""
    internalBleeding: Optional[str] = ""
    fractureSuspected: Optional[str] = ""
    burnInjury: Optional[str] = ""

class CriticalSymptoms(BaseModel):
    chestPain: Optional[str] = ""
    breathingDifficulty: Optional[str] = ""
    lossOfConsciousness: Optional[str] = ""
    seizures: Optional[str] = ""
    vomiting: Optional[str] = ""
    clinicalNotes: Optional[str] = ""

class MedicalBackground(BaseModel):
    medicalConditions: Optional[str] = ""
    chronicIllness: Optional[str] = ""
    chronicIllnessDetails: Optional[str] = ""

class Medications(BaseModel):
    currentMeds: Optional[str] = ""
    medDosage: Optional[str] = ""
    medFrequency: Optional[str] = ""
    lastDoseTaken: Optional[str] = ""

class Allergies(BaseModel):
    drugAllergies: Optional[str] = ""
    drugAllergiesDetails: Optional[str] = ""
    foodAllergies: Optional[str] = ""
    foodAllergiesDetails: Optional[str] = ""
    otherAllergies: Optional[str] = ""

class SurgicalHistory(BaseModel):
    previousSurgeries: Optional[str] = ""
    surgeryType: Optional[str] = ""
    surgeryDate: Optional[str] = ""

class AdditionalMedicalInfo(BaseModel):
    bloodGroup: Optional[str] = ""
    pregnancyStatus: Optional[str] = ""
    familyHistory: Optional[str] = ""

class Identification(BaseModel):
    idType: Optional[str] = ""
    idNumber: Optional[str] = ""

class InsuranceDetails(BaseModel):
    insuranceAvailable: Optional[str] = ""
    providerName: Optional[str] = ""
    policyNumber: Optional[str] = ""
    policyHolderName: Optional[str] = ""
    relationshipToPatient: Optional[str] = ""

class CoverageDetails(BaseModel):
    policyValid: Optional[str] = ""
    emergencyCoverage: Optional[str] = ""
    coverageLimit: Optional[str] = ""
    cashlessFacility: Optional[str] = ""

class Authorization(BaseModel):
    preAuthRequired: Optional[str] = ""
    preAuthStatus: Optional[str] = ""

class ContactNotes(BaseModel):
    insuranceContact: Optional[str] = ""
    insuranceRemarks: Optional[str] = ""

class PatientIntakeRequest(BaseModel):
    patient_id: str = Field(..., description="Patient ID from emergency patients")
    # Section 1: Clinical Assessment
    vitals: VitalsAssessment = Field(default_factory=VitalsAssessment)
    neurological: NeurologicalStatus = Field(default_factory=NeurologicalStatus)
    injury: InjurySymptoms = Field(default_factory=InjurySymptoms)
    criticalSymptoms: CriticalSymptoms = Field(default_factory=CriticalSymptoms)
    # Section 2: Medical History
    medicalBackground: MedicalBackground = Field(default_factory=MedicalBackground)
    medications: Medications = Field(default_factory=Medications)
    allergies: Allergies = Field(default_factory=Allergies)
    surgicalHistory: SurgicalHistory = Field(default_factory=SurgicalHistory)
    additionalMedicalInfo: AdditionalMedicalInfo = Field(default_factory=AdditionalMedicalInfo)
    # Section 3: Insurance
    identification: Identification = Field(default_factory=Identification)
    insuranceDetails: InsuranceDetails = Field(default_factory=InsuranceDetails)
    coverageDetails: CoverageDetails = Field(default_factory=CoverageDetails)
    authorization: Authorization = Field(default_factory=Authorization)
    contactNotes: ContactNotes = Field(default_factory=ContactNotes)
    # Metadata
    assessment_date: Optional[str] = None
    assessment_time: Optional[str] = None

@router.post("/patient-intake/save")
async def save_patient_intake(intake_data: PatientIntakeRequest):
    """
    Save patient intake assessment data
    """
    try:
        patient_id = intake_data.patient_id
        
        # Check if patient exists in emergency_patients collection
        patient_exists = db["patients"].find_one({"patient_id": patient_id})
        if not patient_exists:
            raise HTTPException(status_code=404, detail=f"Patient with ID {patient_id} not found")
        
        # Create document for this intake assessment
        intake_document = {
            "patient_id": patient_id,
            "assessment_id": str(uuid.uuid4()),
            # Section 1: Clinical Assessment
            "clinical_assessment": {
                "vitals": intake_data.vitals.dict(),
                "neurological_status": intake_data.neurological.dict(),
                "injury_symptoms": intake_data.injury.dict(),
                "critical_symptoms": intake_data.criticalSymptoms.dict()
            },
            # Section 2: Medical History
            "medical_history": {
                "medical_background": intake_data.medicalBackground.dict(),
                "medications": intake_data.medications.dict(),
                "allergies": intake_data.allergies.dict(),
                "surgical_history": intake_data.surgicalHistory.dict(),
                "additional_medical_info": intake_data.additionalMedicalInfo.dict()
            },
            # Section 3: Insurance Verification
            "insurance_verification": {
                "identification": intake_data.identification.dict(),
                "insurance_details": intake_data.insuranceDetails.dict(),
                "coverage_details": intake_data.coverageDetails.dict(),
                "authorization": intake_data.authorization.dict(),
                "contact_notes": intake_data.contactNotes.dict()
            },
            "assessment_date": intake_data.assessment_date or datetime.now().strftime("%Y-%m-%d"),
            "assessment_time": intake_data.assessment_time or datetime.now().strftime("%H:%M:%S"),
            "created_at": datetime.now(),
            "updated_at": datetime.now(),
            "status": "completed"
        }
        
        # Insert into patient_intake_collection
        result = patient_intake_collection.insert_one(intake_document)
        
        # Also update the main patient record with reference to this assessment
        db["emergency_patients"].update_one(
            {"patient_id": patient_id},
            {
                "$push": {
                    "intake_assessments": {
                        "assessment_id": intake_document["assessment_id"],
                        "assessment_date": intake_document["assessment_date"],
                        "assessment_time": intake_document["assessment_time"],
                        "status": "completed"
                    }
                },
                "$set": {
                    "last_intake_assessment": datetime.now(),
                    "has_intake_assessment": True
                }
            }
        )
        
        return {
            "status": "success",
            "message": "Patient intake assessment saved successfully",
            "patient_id": patient_id,
            "assessment_id": intake_document["assessment_id"],
            "created_at": intake_document["created_at"].isoformat()
        }
        
    except HTTPException:
        raise
    except Exception as e:
        print(f"Failed to save patient intake: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Failed to save: {str(e)}")

@router.get("/patient-intake/{patient_id}")
async def get_patient_intake(patient_id: str):
    """
    Get all intake assessments for a patient
    """
    try:
        assessments = list(patient_intake_collection.find(
            {"patient_id": patient_id},
            {"_id": 0}
        ).sort("created_at", -1))
        
        return {
            "status": "success",
            "patient_id": patient_id,
            "assessments": assessments,
            "count": len(assessments)
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch: {str(e)}")

@router.get("/patient-intake/{patient_id}/latest")
async def get_latest_patient_intake(patient_id: str):
    """
    Get the latest intake assessment for a patient
    """
    try:
        latest = patient_intake_collection.find_one(
            {"patient_id": patient_id},
            {"_id": 0}
        ).sort("created_at", -1)
        
        if not latest:
            return {
                "status": "success",
                "patient_id": patient_id,
                "has_assessment": False,
                "assessment": None
            }
        
        return {
            "status": "success",
            "patient_id": patient_id,
            "has_assessment": True,
            "assessment": latest
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch: {str(e)}")

