###agnetic rules save option######


async def save_single_agent_rule(
    doctor_id: str,
    agent: str,
    rule: str,
    doctor_rule_agent_collection
) -> Dict[str, Any]:
    """
    Save ONE agent rule for a doctor.
    Example:
        agent = "identity"
        rule  = "You are a Cardiology Ontology Extraction Agent..."
    """

    try:
        logger.info(
            f"🧾 Saving single agent rule | doctor_id={doctor_id} | agent={agent}"
        )

        update_doc = {
            "$set": {
                f"rules.{agent}": rule,     # 🔥 nested update
                "doctor_id": doctor_id,
                "updated_at": datetime.utcnow().isoformat()
            }
        }

        result = await doctor_rule_agent_collection.update_one(
            {"doctor_id": doctor_id},
            update_doc,
            upsert=True  # create document if not exists
        )

        logger.info(
            f"✅ Rule saved | matched={result.matched_count} modified={result.modified_count}"
        )

        return {
            "status": "success",
            "doctor_id": doctor_id,
            "agent": agent
        }

    except Exception as e:
        logger.error(f"❌ Failed to save single agent rule: {str(e)}")
        return {
            "status": "error",
            "error": str(e)
        }



