@router.get("/get_doctors_by_hospital/{hospital_id}", response_model=List[dict])
async def get_doctors_by_hospital(hospital_id: str):
    # Fetch doctors based on the provided hospital_id from doctor_users collection
    doctors_cursor = doctor_user_collection.find({"hospital_id": hospital_id})
    doctors_list = list(doctors_cursor)

    # If no doctors found, return an error response
    if not doctors_list:
        raise HTTPException(status_code=404, detail="No doctors found for this hospital")

    # Extract sys_user_ids from the doctors list
    sys_user_ids = [doctor["sys_user_id"] for doctor in doctors_list]

    # Fetch roles and status from the user_auth_collection for all sys_user_ids
    user_data_list = list(user_auth_collection.find({"sys_user_id": {"$in": sys_user_ids}}))

    # Create a dictionary of sys_user_id to role and status mapping
    user_data_dict = {
        user["sys_user_id"]: {
            "role": user["role"],
            "status": user.get("status", "active")  # Default to "active" if no status found
        }
        for user in user_data_list
    }

    # Combine doctor data with corresponding role and status
    doctor_list = [
        {
            "name": doctor["name"],
            "sys_user_id": doctor["sys_user_id"],
            "email": doctor.get("email"),
            "phone_number": doctor["phone_number"],
            "hospital_name": doctor.get("hospital_name"),
            "specialization": doctor["specialization"],
            "username": doctor["username"],
            "role": user_data_dict.get(doctor["sys_user_id"], {}).get("role", "Unknown"),  # Default to "Unknown" if no role found
            "status": user_data_dict.get(doctor["sys_user_id"], {}).get("status", "active"),  # Dynamic status from the DB
        }
        for doctor in doctors_list
    ]

    return doctor_list





