@router.put("/block_user/{sys_user_id}")
async def block_user(sys_user_id: str):
    # Find the user by sys_user_id
    user = user_auth_collection.find_one({"sys_user_id": sys_user_id})
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check if the current status is not already "blocked"
    if user.get("status") == "blocked":
        raise HTTPException(status_code=400, detail="User is already blocked")
    
    # Update the status to "blocked"
    result = user_auth_collection.update_one(
        {"sys_user_id": sys_user_id},
        {"$set": {"status": "blocked", "renewed_at": datetime.now()}}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=500, detail="Failed to update user status")
    
    return {"message": "User status changed to blocked successfully"}

# PUT endpoint to change user status to "active"
@router.put("/activate_user/{sys_user_id}")
async def activate_user(sys_user_id: str):
    # Find the user by sys_user_id
    user = user_auth_collection.find_one({"sys_user_id": sys_user_id})
    
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check if the current status is not already "active"
    if user.get("status") == "active":
        raise HTTPException(status_code=400, detail="User is already active")
    
    # Update the status to "active"
    result = user_auth_collection.update_one(
        {"sys_user_id": sys_user_id},
        {"$set": {"status": "active", "renewed_at": datetime.now()}}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=500, detail="Failed to update user status")
    
    return {"message": "User status changed to active successfully"}


@router.post("/update-doctor-info")
async def update_doctor_info(data: UpdateDoctorInfoRequest):
    # Find the doctor in the doctor_user_collection using the sys_user_id (sys_user_id)
    doctor = doctor_user_collection.find_one({"sys_user_id": data.sys_user_id})
    
    if not doctor:
        raise HTTPException(status_code=404, detail="Doctor not found")

    # Prepare the update data, only including fields that are not None
    update_data = {}

    if data.full_name:
        update_data["name"] = data.full_name
    if data.username:
        update_data["username"] = data.username
    if data.password:
        update_data["password"] = hash_password(data.password)  # Only update if password is provided
    if data.specialization:
        update_data["specialization"] = data.specialization
    if data.role:
        update_data["role"] = data.role
    if data.email:
        update_data["email"] = data.email
    if data.phone_number:
        update_data["phone_number"] = data.phone_number

    # Update the doctor_user_collection
    doctor_user_collection.update_one({"sys_user_id": data.sys_user_id}, {"$set": update_data})

    # Update the user_auth_collection if sensitive fields (password, email, phone, username) are modified
    update_user_auth_data = {}
    
    if data.password:
        update_user_auth_data["password"] = update_data["password"]
    
    if data.email:
        update_user_auth_data["email"] = data.email
        
    if data.phone_number:
        update_user_auth_data["phone_number"] = data.phone_number
        
    if data.username:
        update_user_auth_data["username"] = data.username  # Updating username here as well

    # Only update user_auth_collection if there are changes in sensitive fields
    if update_user_auth_data:
        user_auth_collection.update_one(
            {"sys_user_id": data.sys_user_id},
            {"$set": update_user_auth_data}
        )

    return {"message": "Doctor information updated successfully"}


# Endpoint to update nurse information
@router.post("/update-nurse-info")
async def update_nurse_info(data: UpdateNurseInfoRequest):
    # Find the nurse in the nurse_user_collection using sys_user_id
    nurse = nurse_user_collection.find_one({"sys_user_id": data.sys_user_id})

    if not nurse:
        raise HTTPException(status_code=404, detail="Nurse not found")

    # Log original data for comparison
    logger.info(f"Original nurse data: {nurse}")

    # Prepare the update data, only including fields that are not None
    update_data = {}
    changes = {}

    if data.full_name:
        update_data["name"] = data.full_name
        changes["full_name"] = data.full_name
    if data.username:
        update_data["username"] = data.username
        changes["username"] = data.username
    if data.password:
        update_data["password"] = hash_password(data.password)  # Only update if password is provided
        changes["password"] = "[REDACTED]"  # Log password change but don't expose the value
    if data.doctor_id:
        update_data["doctor_id"] = data.doctor_id  # Update assigned doctor if provided
        changes["doctor_id"] = data.doctor_id
    if data.role:
        update_data["role"] = data.role
        changes["role"] = data.role
    if data.email:
        update_data["email"] = data.email
        changes["email"] = data.email
    if data.phone_number:
        update_data["phone_number"] = data.phone_number
        changes["phone_number"] = data.phone_number

    # Log the changes
    logger.info(f"Changes to be made: {changes}")

    # Update the nurse_user_collection
    result = nurse_user_collection.update_one({"sys_user_id": data.sys_user_id}, {"$set": update_data})

    if result.modified_count == 0:
        logger.warning(f"No changes made for nurse with sys_user_id: {data.sys_user_id}")

    # Log the updated nurse data
    updated_nurse = nurse_user_collection.find_one({"sys_user_id": data.sys_user_id})
    logger.info(f"Updated nurse data: {updated_nurse}")

    # Update the user_auth_collection for sensitive fields (password, email, phone, username)
    update_user_auth_data = {}
    if data.password:
        update_user_auth_data["password"] = update_data["password"]
    if data.email:
        update_user_auth_data["email"] = data.email
    if data.phone_number:
        update_user_auth_data["phone_number"] = data.phone_number
    if data.username:
        update_user_auth_data["username"] = data.username  # Updating username here as well

    # Only update user_auth_collection if there are changes in sensitive fields
    if update_user_auth_data:
        result = user_auth_collection.update_one(
            {"sys_user_id": data.sys_user_id},
            {"$set": update_user_auth_data}
        )

        if result.modified_count == 0:
            logger.warning(f"No changes made in user_auth for sys_user_id: {data.sys_user_id}")

    # Return success message
    return {"message": "Nurse information updated successfully"}

