@router.post("/allocation/create")
async def save_allocation(request: Request):
    try:
        data = await request.json()

        print("Incoming Data:", data)

        # 🔑 Extract unique identifiers
        qc_id = data.get("qc_id")
        claim_number = data.get("CLAIM NUMBER")

        # ✅ Validation
        if not qc_id:
            return {"success": False, "message": "qc_id is required"}

        if not claim_number:
            return {"success": False, "message": "CLAIM NUMBER is required"}

        # ✅ Convert to string (avoid mismatch issues)
        qc_id = str(qc_id)
        claim_number = str(claim_number)

        # 🔍 Query using BOTH qc_id + claim_number
        query = {
            "qc_id": qc_id,
            "CLAIM NUMBER": claim_number
        }

        # Add metadata
        data["qc_id"] = qc_id
        data["CLAIM NUMBER"] = claim_number
        data["updated_at"] = datetime.utcnow()

        existing = quality_checker_collection.find_one(query)

        if existing:
            # ✅ UPDATE existing record
            updated = quality_checker_collection.find_one_and_update(
                query,
                {
                    "$set": data
                },
                return_document=ReturnDocument.AFTER
            )

            return {
                "success": True,
                "message": "Record updated successfully",
                "data": updated
            }

        else:
            # ✅ INSERT new record
            data["created_at"] = datetime.utcnow()

            result = quality_checker_collection.insert_one(data)

            return {
                "success": True,
                "message": "Record inserted successfully",
                "inserted_id": str(result.inserted_id)
            }

    except Exception as e:
        print("Error:", str(e))
        return {
            "success": False,
            "message": "Error saving data",
            "error": str(e)
        }

