@router.post("/context/save")
async def save_context_data(payload: dict):
    try:
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        appointment_id = payload.get("appointment_id")
        
        # ==========================================================
        # 📝 LOGGER - SAVE REQUEST RECEIVED
        # ==========================================================
        logger.info("=" * 50)
        logger.info("🔵 CONTEXT SAVE REQUEST RECEIVED")
        logger.info("=" * 50)
        logger.info(f"📌 Patient ID: {patient_id}")
        logger.info(f"📌 Doctor ID: {doctor_id}")
        logger.info(f"📌 Appointment ID: {appointment_id}")
        logger.info(f"📌 Has Current Clinical Context: {bool(payload.get('current_clinical_context'))}")
        logger.info(f"📌 Has Medical Clinical Context: {bool(payload.get('medical_clinical_context'))}")
        
        # Validation
        if not patient_id or not doctor_id:
            error_msg = "Missing patient_id or doctor_id"
            logger.error(f"❌ Validation Failed: {error_msg}")
            raise HTTPException(status_code=400, detail=error_msg)
        
        if not appointment_id:
            error_msg = "appointment_id is required"
            logger.error(f"❌ Validation Failed: {error_msg}")
            raise HTTPException(status_code=400, detail=error_msg)
        
        # Prepare document
        document = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "appointment_id": appointment_id,
            "current_clinical_context": payload.get("current_clinical_context") or {},
            "medical_clinical_context": payload.get("medical_clinical_context") or {},
            "created_at": datetime.utcnow(),
            "updated_at": datetime.utcnow(),
            "type": "clinical_context"
        }
        
        logger.info("📝 Document prepared for insertion")
        logger.info(f"   - Document ID will be auto-generated")
        logger.info(f"   - Timestamp: {document['created_at']}")
        
        # Insert into database
        result = await context_data_collection.insert_one(document)
        
        # ==========================================================
        # ✅ LOGGER - SAVE SUCCESSFUL
        # ==========================================================
        logger.info("=" * 50)
        logger.info("✅ CONTEXT SAVED SUCCESSFULLY")
        logger.info("=" * 50)
        logger.info(f"🆔 Saved Document ID: {str(result.inserted_id)}")
        logger.info(f"👤 Patient ID: {patient_id}")
        logger.info(f"👨‍⚕️ Doctor ID: {doctor_id}")
        logger.info(f"📅 Appointment ID: {appointment_id}")
        logger.info(f"⏰ Saved at: {document['created_at']}")
        logger.info(f"📊 Context Type: clinical_context")
        
        # Verify the save by retrieving the document
        try:
            from bson import ObjectId
            verified_doc = await context_data_collection.find_one({"_id": result.inserted_id})
            if verified_doc:
                logger.info(f"🔍 Verification: Document successfully retrieved from database")
                logger.info(f"   - Patient ID in DB: {verified_doc.get('patient_id')}")
                logger.info(f"   - Doctor ID in DB: {verified_doc.get('doctor_id')}")
                logger.info(f"   - Appointment ID in DB: {verified_doc.get('appointment_id')}")
            else:
                logger.warning("⚠️ Verification failed: Could not retrieve saved document")
        except Exception as verify_err:
            logger.warning(f"⚠️ Verification error: {str(verify_err)}")
        
        logger.info("=" * 50)
        
        return {
            "status": "success",
            "message": "Context data saved",
            "id": str(result.inserted_id),
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "appointment_id": appointment_id
        }
        
    except HTTPException:
        raise
    except Exception as e:
        # ==========================================================
        # ❌ LOGGER - SAVE FAILED
        # ==========================================================
        logger.error("=" * 50)
        logger.error("❌ CONTEXT SAVE FAILED")
        logger.error("=" * 50)
        logger.error(f"Error Type: {type(e).__name__}")
        logger.error(f"Error Message: {str(e)}")
        logger.error(f"Patient ID: {payload.get('patient_id')}")
        logger.error(f"Doctor ID: {payload.get('doctor_id')}")
        logger.error(f"Appointment ID: {payload.get('appointment_id')}")
        
        # Log the payload (excluding large context data)
        safe_payload = {
            "patient_id": payload.get("patient_id"),
            "doctor_id": payload.get("doctor_id"),
            "appointment_id": payload.get("appointment_id"),
            "has_current_context": bool(payload.get("current_clinical_context")),
            "has_medical_context": bool(payload.get("medical_clinical_context"))
        }
        logger.error(f"Payload Summary: {safe_payload}")
        logger.error("=" * 50)
        
        raise HTTPException(status_code=500, detail=str(e))
