@router.post("/anaesthesia-checklist/save")
async def save_anaesthesia_checklist(payload: dict):
    """
    Save Anaesthesia Checklist (OT Part C) data
    """
    try:
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        booking_id = payload.get("booking_id")
        checklist = payload.get("checklist")

        if not patient_id or not doctor_id or not booking_id:
            raise HTTPException(status_code=400, detail="Missing patient_id, doctor_id or booking_id")

        if not checklist or not isinstance(checklist, dict):
            raise HTTPException(status_code=400, detail="Checklist data is required")

        result = await anaesthesia_checklist_collection.update_one(
            {
                "patient_id": patient_id,
                "booking_id": booking_id
            },
            {
                "$set": {
                    "doctor_id": doctor_id,
                    "checklist": checklist,
                    "updated_at": datetime.utcnow(),
                    "type": "anaesthesia_checklist"
                },
                "$setOnInsert": {
                    "patient_id": patient_id,
                    "booking_id": booking_id,
                    "created_at": datetime.utcnow()
                }
            },
            upsert=True
        )

        return {
            "status": "success",
            "message": "Anaesthesia checklist saved",
            "id": str(result.upserted_id) if result.upserted_id else None
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



