@router.post("/pain-management/save")
async def save_pain_management(payload: dict):
    """
    Save a Pain Management assessment (New / Follow Up forms only).
 
    Nerve Block assessments are NO LONGER stored here — they are saved to
    a separate collection (`nerve_block_assessments_collection`) via the
    same request, since nerve block procedures are tracked independently
    from the New -> Follow Up pain assessment history.
 
    Expected payload (from PainManagementNewFollowUp.jsx's onSave):
    {
        "patient_id": "...",
        "doctor_id": "...",
        "newForm": {...},
        "followUpForm": {...},
        "nerveBlockForm": {...},   # optional — routed to separate collection
        "saved_at": "ISO timestamp"   # optional, generated client-side
    }
    """
    try:
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")
        new_form = payload.get("newForm") or {}
        follow_up_form = payload.get("followUpForm") or {}
        nerve_block_form = payload.get("nerveBlockForm") or {}
 
        if not patient_id or not doctor_id:
            raise HTTPException(status_code=400, detail="Missing patient_id or doctor_id")
 
        if not new_form and not follow_up_form and not nerve_block_form:
            raise HTTPException(status_code=400, detail="At least one form section is required")
 
        saved_ids = {}
 
        # ── New / Follow Up assessment → pain_management_collection ────────
        if new_form or follow_up_form:
            document = {
                "patient_id": patient_id,
                "doctor_id": doctor_id,
                "new_form": new_form,
                "follow_up_form": follow_up_form,
                "created_at": datetime.utcnow(),
                "updated_at": datetime.utcnow(),
                "type": "pain_management",
            }
            result = await pain_management_collection.insert_one(document)
            saved_ids["pain_management_id"] = str(result.inserted_id)
 
        # ── Nerve Block → separate collection ───────────────────────────────
        if nerve_block_form:
            nerve_block_document = {
                "patient_id": patient_id,
                "doctor_id": doctor_id,
                "nerve_block_form": nerve_block_form,
                "created_at": datetime.utcnow(),
                "updated_at": datetime.utcnow(),
                "type": "nerve_block",
            }
            nerve_result = await nerve_block_assessments_collection.insert_one(nerve_block_document)
            saved_ids["nerve_block_id"] = str(nerve_result.inserted_id)
 
        return {
            "status": "success",
            "message": "Pain management assessment saved",
            **saved_ids,
        }
 
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
 
 
@router.get("/pain-management/history/{patient_id}/{doctor_id}")
async def get_pain_management_history(patient_id: str, doctor_id: str):
    """
    Fetch all Pain Management assessments (New / Follow Up only — nerve
    block lives in its own collection now) for a patient, most recent first.
 
    Used by PainManagementHistoryTables.jsx to render read-only history
    tables in the Clinical tab, right under Clinical Dictation.
    """
    try:
        cursor = pain_management_collection.find(
            {"patient_id": patient_id, "doctor_id": doctor_id}
        ).sort("created_at", -1)
 
        records = []
        async for doc in cursor:
            doc["_id"] = str(doc["_id"])
            if isinstance(doc.get("created_at"), datetime):
                doc["created_at"] = doc["created_at"].isoformat()
            if isinstance(doc.get("updated_at"), datetime):
                doc["updated_at"] = doc["updated_at"].isoformat()
            records.append(doc)
 
        return {
            "status": "success",
            "count": len(records),
            "data": records,
        }
 
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
 
# ─────────────────────────────────────────────────────────────────────────
# PATIENT DETAILS AUTO-FILL (New Form → General Details: Name, Age, Gender, Phone)
# ─────────────────────────────────────────────────────────────────────────

@router.get("/pain-management/patient-details/{patient_id}/{doctor_id}")
async def get_pain_management_patient_details(patient_id: str, doctor_id: str):
    """
    Auto-fill for Pain Management New Form's "General Details" section
    (Patient Name, Age, Gender, Phone) from the patient_users collection.

    IMPORTANT: patient_users documents key on "sys_user_id" for the
    "PAT-..." format used everywhere else in this app — NOT "patient_id"
    (patient_users has its own unrelated "patient_id" field with a
    different value, e.g. "PAT-6a5b1a5b...9915a86f" vs the sys_user_id
    "PAT-3a457415...68c9da8"). This mirrors get_patient_info in
    surgical_oncology_api.py: try "patient_id" first (in case some
    records do use it directly), then fall back to "sys_user_id".

    doctor_id is accepted only for route-shape consistency with the other
    pain-management endpoints — patient_users isn't doctor-scoped, so it's
    unused in the actual lookup.

    Age is computed server-side from date_of_birth (stored as "YYYY-MM-DD"
    string, confirmed against a real document) so the frontend doesn't
    need its own date-parsing logic.
    """
    result = {"patientName": "", "age": None, "gender": "", "phone": ""}
    try:
        doc = await patient_users_collection.find_one({"patient_id": patient_id})
        if not doc:
            doc = await patient_users_collection.find_one({"sys_user_id": patient_id})

        if doc:
            result["patientName"] = doc.get("name") or ""
            result["gender"] = doc.get("gender") or ""
            result["phone"] = doc.get("phone_number") or ""

            dob = doc.get("date_of_birth")
            if dob:
                try:
                    birth_date = datetime.strptime(dob, "%Y-%m-%d")
                    today = datetime.utcnow()
                    age = today.year - birth_date.year - (
                        (today.month, today.day) < (birth_date.month, birth_date.day)
                    )
                    result["age"] = age
                except Exception as e:
                    logger.warning(
                        f"Pain management patient-details: couldn't parse date_of_birth "
                        f"'{dob}' for {patient_id}: {e}"
                    )
    except Exception as e:
        logger.warning(f"Pain management patient-details lookup failed for {patient_id}: {e}")

    return {"status": "success", "data": result}
# ─────────────────────────────────────────────────────────────────────────
# PAIN CHARACTERISTICS + QUALITY OF LIFE — VOICE DICTATION FIELD EXTRACTION
# (New Form only — mirrors nerve-block extract-fields below)
# ─────────────────────────────────────────────────────────────────────────

PAIN_CHAR_TEXT_FIELD_KEYS = [
    "site", "radiatesTo", "referredTo", "duration", "relieving",
]

PAIN_CHAR_NUMERIC_FIELD_KEYS = ["painScore", "btpEpisodes"]

# Single-select fields: value must be exactly one of these options
PAIN_CHAR_SINGLE_SELECT_OPTS = {
    "distribution": ["Localised", "Generalised"],
    "course": ["Continuous", "Intermittent"],
    "pattern": ["Breakthrough", "Incidental"],
    "perfScaleType": ["Karnofsky", "ECOG"],
}

# Multi-select fields: value must be a list, each item one of these options
PAIN_CHAR_MULTI_SELECT_OPTS = {
    "typeOfPain": ["Burning", "Stabbing", "Dull Aching", "Numbness", "Pricking",
                   "Shooting", "Spasmodic", "Tingling", "Throbbing Pain"],
    "aggravating": ["After meals", "On movement", "Not related", "On Swallowing",
                     "Coughing", "Others"],
    "pathophysiology": ["Somatic", "Visceral", "Neuropathic", "Psychogenic"],
    "painSyndrome": ["Head and Neck Cancer Pain Syndrome", "Post Mastectomy Pain",
                      "Visceral Pain Syndrome", "Pelvic Pain Syndrome", "Skeletal Metastasis",
                      "STS Pain Syndrome", "Bracheal Plexopathy", "Lumbosacral Plexopathy",
                      "Post Thoracotomy Pain", "Post RT Pain", "Post CT Pain",
                      "Phantom Limb Pain", "CRPS", "Others"],
    "painDiagnosis": ["Due to cancer", "Cancer Therapy", "Unrelated"],
    "diagnosisMadeBy": ["Clinical", "X-Ray", "CT", "Bone Scan", "USG", "MRI", "PET"],
    "affect": ["Sleep", "Mood", "Bladder", "Bowel", "Appetite", "Others", "None"],
}

# perfStatus is conditional on perfScaleType — validated against the union
# of both option sets, since the LLM extracts it independent of which
# scale the doctor later picks in the UI.
PERF_STATUS_ALLOWED = set([
    ">80% Normal activity, no special care",
    "50–70% Unable to work, lives at home",
    "<50% Needs Hospital Care",
    "0", "1", "2", "3", "4",
])

PAIN_CHAR_EXTRACT_FIELDS_PROMPT = """You are a clinical documentation assistant extracting structured
fields from a doctor's spoken dictation about a cancer patient's pain assessment.

Extract ONLY information explicitly stated or clearly implied in the dictation. Do not guess or
fabricate values for anything not mentioned. Return a single JSON object with these possible keys:

TEXT FIELDS (free text, extract as spoken, keep concise):
- site: where the pain is located (e.g. "forehead", "lower back")
- radiatesTo: where the pain radiates to
- referredTo: where the pain is referred to
- duration: duration/onset of pain (e.g. "3 weeks", "since yesterday")
- relieving: relieving factors, free text

NUMERIC FIELDS:
- painScore: integer 0-10 (Numeric Rating Scale)
- btpEpisodes: integer, number of breakthrough pain episodes

SINGLE-SELECT FIELDS (pick exactly ONE matching option, omit if not mentioned):
- distribution: one of ["Localised", "Generalised"]
- course: one of ["Continuous", "Intermittent"]
- pattern: one of ["Breakthrough", "Incidental"]
- perfScaleType: one of ["Karnofsky", "ECOG"]
- perfStatus: performance status matching whichever scale was mentioned

MULTI-SELECT FIELDS (return as a JSON array of matching options, omit if none mentioned):
- typeOfPain: any of ["Burning", "Stabbing", "Dull Aching", "Numbness", "Pricking", "Shooting", "Spasmodic", "Tingling", "Throbbing Pain"]
- aggravating: any of ["After meals", "On movement", "Not related", "On Swallowing", "Coughing", "Others"]
- pathophysiology: any of ["Somatic", "Visceral", "Neuropathic", "Psychogenic"]
- painSyndrome: any of ["Head and Neck Cancer Pain Syndrome", "Post Mastectomy Pain", "Visceral Pain Syndrome", "Pelvic Pain Syndrome", "Skeletal Metastasis", "STS Pain Syndrome", "Bracheal Plexopathy", "Lumbosacral Plexopathy", "Post Thoracotomy Pain", "Post RT Pain", "Post CT Pain", "Phantom Limb Pain", "CRPS", "Others"]
- painDiagnosis: any of ["Due to cancer", "Cancer Therapy", "Unrelated"]
- diagnosisMadeBy: any of ["Clinical", "X-Ray", "CT", "Bone Scan", "USG", "MRI", "PET"]
- affect: any of ["Sleep", "Mood", "Bladder", "Bowel", "Appetite", "Others", "None"]

Only use the exact option strings given above — do not invent new option values.
Return ONLY the JSON object, no explanation, no markdown formatting.
"""


@router.post("/pain-management/extract-fields")
async def extract_pain_management_fields(payload: dict):
    """
    Extracts Pain Characteristics + Quality of Life fields from a doctor's
    voice dictation, for the New Form in PainManagementNewFollowUp.jsx.

    Expected payload:
    {
        "doctor_id": "...",
        "patient_id": "...",
        "dictation": "free text transcript",
        "target_section": "pain_characteristics_qol"   # currently unused, reserved
    }

    Returns:
    {
        "status": "success",
        "finaloutput": { "site": "...", "typeOfPain": [...], "painScore": 6, ... }
    }
    """
    if groq_client is None:
        raise HTTPException(status_code=500, detail="GROQ_API_KEY not configured on server")

    try:
        dictation = (payload.get("dictation") or "").strip()
        if not dictation:
            raise HTTPException(status_code=400, detail="dictation is required")

        completion = groq_client.chat.completions.create(
            model="llama-3.3-70b-versatile",
            messages=[
                {"role": "system", "content": PAIN_CHAR_EXTRACT_FIELDS_PROMPT},
                {"role": "user", "content": dictation},
            ],
            temperature=0,
            response_format={"type": "json_object"},
        )

        raw_content = completion.choices[0].message.content
        try:
            parsed = json.loads(raw_content)
        except (json.JSONDecodeError, TypeError):
            logger.error(f"Pain management extract-fields returned non-JSON: {raw_content}")
            parsed = {}

        if not isinstance(parsed, dict):
            parsed = {}

        # ── Sanitize before returning to the frontend ──────────────────────
        clean = {}

        for key in PAIN_CHAR_TEXT_FIELD_KEYS:
            if parsed.get(key):
                clean[key] = str(parsed[key])[:1000]

        for key in PAIN_CHAR_NUMERIC_FIELD_KEYS:
            if key in parsed:
                try:
                    val = int(parsed[key])
                    if key == "painScore" and not (0 <= val <= 10):
                        continue
                    if val < 0:
                        continue
                    clean[key] = val
                except (TypeError, ValueError):
                    pass

        for key, allowed in PAIN_CHAR_SINGLE_SELECT_OPTS.items():
            val = parsed.get(key)
            if key == "perfStatus":
                continue  # handled separately below
            if val in allowed:
                clean[key] = val

        for key, allowed in PAIN_CHAR_MULTI_SELECT_OPTS.items():
            val = parsed.get(key)
            if isinstance(val, list):
                filtered = [v for v in val if v in allowed]
                if filtered:
                    clean[key] = filtered
            elif isinstance(val, str) and val in allowed:
                # Model occasionally returns a single string instead of a list
                clean[key] = [val]

        # perfStatus validated against the union of Karnofsky/ECOG options,
        # since the UI's option set depends on perfScaleType (which the
        # doctor may not have finalized yet in the toggle).
        perf_status = parsed.get("perfStatus")
        if isinstance(perf_status, (str, int)) and str(perf_status) in PERF_STATUS_ALLOWED:
            clean["perfStatus"] = str(perf_status)

        return {"status": "success", "finaloutput": clean}

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Pain management extract-fields failed: {e}")
        raise HTTPException(status_code=500, detail=str(e))
# ─────────────────────────────────────────────────────────────────────────
#  NEW: Nerve block — separate save + history routes
# ─────────────────────────────────────────────────────────────────────────
 

NERVE_BLOCK_TEXT_FIELD_KEYS = [
    "approach", "drugUsed", "concentration", "contrastUsed",
    "procedureDescription", "complications", "prePerfActivity",
    "preBP", "postBP",
]
NERVE_BLOCK_NUMERIC_FIELD_KEYS = [
    "volume", "contrastVolume", "prePainScore", "postPainScore",
    "prePulse", "postPulse",
]

NERVE_BLOCK_POST_ACTIVITY_OPTS = ["Worsened", "No change", "Improved"]
 
NERVE_BLOCK_EXTRACT_FIELDS_PROMPT = f"""
You are a clinical assistant extracting structured Nerve Block procedure
data from a doctor's spoken/dictated note about a pain-management nerve
block procedure.
 
Return a JSON object with these optional keys — include a key ONLY if the
dictation clearly states or implies a value for it:
 
Free-text keys:
  - "approach": the approach/technique used to perform the block (short text).
  - "drugUsed": name(s) of the local anesthetic / neurolytic / other drug
    used for the block.
  - "concentration": concentration of the drug used (e.g. "0.5%", "2%").
  - "contrastUsed": name of contrast agent used, if any.
  - "procedureDescription": a short clinical description of how the
    procedure was carried out.
  - "complications": any immediate complications mentioned. If the
    dictation explicitly says there were none, return "None".
  - "prePerfActivity": a short description of the patient's activity/
    functional level before the procedure, if mentioned.
- "preBP": pre-procedure blood pressure as written/spoken (e.g. "120/80").
- "postBP": post-procedure blood pressure as written/spoken.
 
Numeric keys (integers):
  - "volume": volume of the block drug used, in ml.
  - "contrastVolume": volume of contrast used, in ml.
  - "prePainScore": pre-procedure pain score, 0-10 (0 = no pain, 10 = worst
    possible pain). Only include if the dictation states or clearly implies
    a pre-procedure score.
  - "postPainScore": post-procedure pain score, 0-10, same scale. Only
    include if the dictation states or clearly implies a post-procedure
    score.
- "prePulse": pre-procedure pulse rate, in beats per minute (integer).
- "postPulse": post-procedure pulse rate, in beats per minute (integer).
Enum key:
  - "postProcedureActivity": ONLY one of exactly these strings —
    {json.dumps(NERVE_BLOCK_POST_ACTIVITY_OPTS)} — if the dictation
    indicates how the patient's activity changed after the procedure.
 
Rules:
- Do NOT guess a numeric score or enum value if the dictation does not
  clearly state or strongly imply it — omit the key instead.
- Do NOT invent findings, drugs, or details not present in the dictation.
- Return valid JSON only — no markdown, no commentary, no extra keys.
"""
 
 
@router.post("/pain-management/nerve-block/extract-fields")
async def extract_nerve_block_fields(payload: dict):
    """
    Expected payload:
    {
        "doctor_id": "...",
        "patient_id": "...",
        "dictation": "free text transcript"
    }
 
    Returns:
    {
        "status": "success",
        "finaloutput": { "approach": "...", "prePainScore": 6, ... }
    }
    """
    if groq_client is None:
        raise HTTPException(status_code=500, detail="GROQ_API_KEY not configured on server")
 
    try:
        dictation = (payload.get("dictation") or "").strip()
        if not dictation:
            raise HTTPException(status_code=400, detail="dictation is required")
 
        completion = groq_client.chat.completions.create(
            model="llama-3.3-70b-versatile",
            messages=[
                {"role": "system", "content": NERVE_BLOCK_EXTRACT_FIELDS_PROMPT},
                {"role": "user", "content": dictation},
            ],
            temperature=0,
            response_format={"type": "json_object"},
        )
 
        raw_content = completion.choices[0].message.content
        try:
            parsed = json.loads(raw_content)
        except (json.JSONDecodeError, TypeError):
            logger.error(f"Nerve block extract-fields returned non-JSON: {raw_content}")
            parsed = {}
 
        if not isinstance(parsed, dict):
            parsed = {}
 
        # Sanitize before returning to the frontend.
        clean = {}
 
        for key in NERVE_BLOCK_TEXT_FIELD_KEYS:
            if parsed.get(key):
                clean[key] = str(parsed[key])[:1000]
 
        for key in NERVE_BLOCK_NUMERIC_FIELD_KEYS:
            if key in parsed:
                try:
                    val = int(parsed[key])
                    if key in ("prePainScore", "postPainScore") and not (0 <= val <= 10):
                        continue
                    if val < 0:
                        continue
                    clean[key] = val
                except (TypeError, ValueError):
                    pass
 
        if parsed.get("postProcedureActivity") in NERVE_BLOCK_POST_ACTIVITY_OPTS:
            clean["postProcedureActivity"] = parsed["postProcedureActivity"]
 
        return {"status": "success", "finaloutput": clean}
 
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Nerve block extract-fields failed: {e}")
        raise HTTPException(status_code=500, detail=str(e))
        
