@router.delete("/delete/{patient_id}/{document_name}")
async def delete_document(patient_id: str, document_name: str):
    try:
        # -------------------------------
        # 1. DELETE FROM MONGODB
        # -------------------------------
        delete_result = processed_documents.delete_one({
            "metadata.patient_id": patient_id,
            "file_name": document_name
        })

        if delete_result.deleted_count == 0:
            raise HTTPException(status_code=404, detail="Document not found")

        # -------------------------------
        # 2. DELETE FROM NEO4J (PATIENT-SPECIFIC)
        # -------------------------------
        query = """
        MATCH (p:Patient {patient_id: $patient_id})-[r]->(n)
        OPTIONAL MATCH (n)-[se:SUPPORTED_BY_EVIDENCE]->(e:Evidence {document_name: $document_name})

        WITH p, n, r, se, e
        WHERE e IS NOT NULL

        // 1. delete evidence relationships
        DELETE se

        // 2. delete patient -> entity relationship
        WITH n, r, e
        DELETE r

        // 3. delete entity nodes if no longer connected
        WITH n, e
        OPTIONAL MATCH (n)<-[rel]-()
        WITH n, e, count(rel) AS rel_count
        WHERE rel_count = 0
        DETACH DELETE n

        // 4. delete evidence if unused
        WITH e
        OPTIONAL MATCH (e)<-[rel]-()
        WITH e, count(rel) AS rel_count
        WHERE rel_count = 0
        DETACH DELETE e
        """

        neo4j_error = None

        try:
            async with neo4j_driver.session() as session:
                result = await session.run(
                    query,
                    patient_id=patient_id,
                    document_name=document_name
                )
                await result.consume()   # ✅ IMPORTANT (ensures execution)

        except Exception as neo_err:
            import traceback
            neo4j_error = str(neo_err)

            print("==== NEO4J ERROR ====")
            traceback.print_exc()

        # -------------------------------
        # 3. RESPONSE HANDLING
        # -------------------------------
        if neo4j_error:
            return {
                "status": "partial_success",
                "message": f"Document '{document_name}' deleted from MongoDB but Neo4j failed",
                "neo4j_error": neo4j_error
            }

        return {
            "status": "success",
            "message": f"Document '{document_name}' deleted successfully"
        }

    except HTTPException:
        raise

    except Exception as e:
        import traceback
        print("==== BACKEND ERROR ====")
        traceback.print_exc()

        raise HTTPException(status_code=500, detail=str(e))
    
    
    
    
