from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from datetime import datetime


class ClinicalFindings(BaseModel):
    vitals_analysis: Optional[Dict] = None
    complaint_analysis: Optional[str] = None
    history_analysis: Optional[str] = None


class RiskAnalysis(BaseModel):
    level: str
    reasoning: str
    deterioration_risk: str


class ImmediateAction(BaseModel):
    priority: str
    action: str
    rationale: str
    who: str


class MonitoringPlan(BaseModel):
    vital_signs_frequency: str
    specific_parameters_to_watch: List[str]
    escalation_triggers: str
    reassessment_timing: str


class Referral(BaseModel):
    specialty: str
    urgency: str
    reason: str


class TransferDecision(BaseModel):
    required: bool
    destination: str
    reason: str


class TriageSimpleRequest(BaseModel):
    patient_id: str
    doctor_id: str
    triage_timestamp: datetime
    processing_time_ms: int
    triage_level: int
    triage_category: str
    triage_standard_used: str
    why_this_level: str
    why_this_standard: str

    clinical_findings: Optional[ClinicalFindings] = None
    risk_analysis: Optional[RiskAnalysis] = None

    immediate_actions: List[ImmediateAction] = []
    monitoring_plan: Optional[MonitoringPlan] = None
    referrals_needed: List[Referral] = []

    transfer_decision: Optional[TransferDecision] = None

    triage_summary: str
    disposition_plan: str

    raw_data: Optional[Any] = None
    errors: List[str] = []


