@router.get("/get_latest_simple_triage/{patient_id}")
async def get_latest_simple_triage(patient_id: str):
    try:
        document = triage_assessment_collection.find_one(
            {"patient_id": patient_id},
            sort=[("updated_at", -1)]
        )

        if not document:
            return {
                "status": "not_found",
                "message": f"No triage found for patient {patient_id}",
                "data": None
            }

        # Convert ObjectId → string
        if "_id" in document:
            document["_id"] = str(document["_id"])

        # Convert datetime → ISO
        for field in ["triage_timestamp", "updated_at"]:
            if field in document and isinstance(document[field], datetime):
                document[field] = document[field].isoformat()

        return {
            "status": "success",
            "data": document
        }

    except Exception as e:
        return JSONResponse(
            status_code=500,
            content={"status": "error", "detail": str(e)}
        )





class DictationSa(BaseModel):
    patient_id: str
    doctor_id: str
    nurse_id:str
    conversation: str  
    
@router.post("/general/nurse/dictation/save")
async def save_nurse_dictation(data: DictationSa):
    try:
        if not data.conversation.strip():
            raise HTTPException(status_code=400, detail="Empty dictation")

        # ================= SAVE TO NURSENOTE =================
        filter_query = {
            "patient_id": data.patient_id,
            "doctor_id": data.doctor_id,
            "nurse_id": data.nurse_id
        }

        note_entry = {
            "text": data.conversation,
            "created_at": datetime.utcnow(),
            "type": "nurse_note"
        }

        nursenote.update_one(
            filter_query,
            {"$push": {"notes": note_entry}},
            upsert=True
        )

        # ==========================================================
        # 🔥 TEMP DATA SAVE TRIGGER (SAME AS DOCTOR FLOW)
        # ==========================================================
        temp_payload = {
            "patient_id": data.patient_id,
            "doctor_id": data.doctor_id,
            "conversation": [data.conversation],   # 👈 important change
            "dictation": [data.conversation]
        }

        try:
            async with httpx.AsyncClient(timeout=15.0) as client:
                temp_response = await client.post(
                    f"{api_base_url}hms/users/data/context/general/temp/save",
                    json=temp_payload
                )

            if temp_response.status_code != 200:
                logger.error(
                    "Temp save trigger failed",
                    extra={
                        "status_code": temp_response.status_code,
                        "response": temp_response.text
                    }
                )

        except Exception as e:
            logger.error(f"Temp save exception: {str(e)}")

        # ==========================================================
        # 🚀 MONGO PROCESSING TRIGGER (CELERY)
        # ==========================================================
        from users.celery_client import celery_app

        try:
            celery_app.send_task(
                "legacy_lab_ai.process_mongo_batch",
                kwargs={
                    "patient_id": data.patient_id,
                    "doctor_id": data.doctor_id
                },
                queue="agentic_queue",
                routing_key="agentic"
            )

            logger.info(
                "🚀 Nurse Mongo processing triggered | patient=%s",
                data.patient_id
            )

        except Exception as e:
            logger.error(f"Celery trigger failed: {str(e)}")

        # ==========================================================
        # ✅ RESPONSE
        # ==========================================================
        return {
            "status": "success",
            "message": "Nurse dictation saved + triggers executed"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    
    
    
@router.get("/general/nurse/dictation/latest")
async def get_latest_nurse_note(patient_id: str, doctor_id: str):
    try:
        doc = nursenote.find_one(
            {
                "patient_id": patient_id,
                "doctor_id": doctor_id
            },
            {"notes": 1, "_id": 0}
        )

        if not doc or "notes" not in doc or len(doc["notes"]) == 0:
            return {
                "status": "success",
                "latest_note": None,
                "message": "No nurse notes found"
            }

        # Get latest based on created_at
        latest_note = max(doc["notes"], key=lambda x: x["created_at"])

        return {
            "status": "success",
            "latest_note": latest_note
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    
    
    



