# ─────────────────────────────────────────
class ClinicalSummaryUpdate(BaseModel):
    patient_id: str
    content: Dict[str, Any]   # paragraph_1, paragraph_2... bottom_line


# ─────────────────────────────────────────
# UPDATE ENDPOINT
# ─────────────────────────────────────────
@router.post("/update-clinical-summary")
async def update_clinical_summary(payload: ClinicalSummaryUpdate):
    try:
        patient_id = payload.patient_id
        content = payload.content

        # find latest summary
        doc = await summary_collection.find_one(
            {"patient_id": patient_id},
            sort=[("generated_at", -1)]
        )

        if not doc:
            raise HTTPException(
                status_code=404,
                detail=f"No summary found for patient_id={patient_id}"
            )

        # ─────────────────────────────────────────
        # Clean + normalize content
        # ─────────────────────────────────────────
        updated_summary = {}

        for key, value in content.items():
            if key.startswith("paragraph_") or key == "bottom_line":
                updated_summary[key] = value

        # optional: regenerate deduplication check
        paragraphs = [v for k, v in updated_summary.items() if k.startswith("paragraph_")]

        dedup_check = {
            "total_paragraphs": len(paragraphs),
            "last_updated": datetime.utcnow().isoformat()
        }

        updated_summary["deduplication_check"] = dedup_check

        # ─────────────────────────────────────────
        # Update DB
        # ─────────────────────────────────────────
        await summary_collection.update_one(
            {"_id": doc["_id"]},
            {
                "$set": {
                    "clinical_summary": updated_summary,
                    "updated_at": datetime.utcnow()
                }
            }
        )

        return {
            "status": "success",
            "message": "Clinical summary updated successfully",
            "data": updated_summary
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))





@router.get("/documentation-treatment-plans/{patient_id}/{doctor_id}")
async def get_treatment_plan_by_patient_doctor(
    patient_id: str,
    doctor_id: str,
    limit: int = Query(5, ge=1),
    offset: int = Query(0, ge=0),
):
    try:
        # Count total documents
        total_count = await documentation_treatment_plan_collection.count_documents({
            "doctor_id": doctor_id,
            "patient_id": patient_id
        })

        if total_count == 0:
            raise HTTPException(
                status_code=404,
                detail="No treatment plan found for this doctor and patient"
            )

        # Fetch paginated + sorted data
        cursor = (
            documentation_treatment_plan_collection
            .find({
                "doctor_id": doctor_id,
                "patient_id": patient_id
            })
            .sort("created_at", -1)  # 🔥 Latest first
            .skip(offset)
            .limit(limit)
        )

        data = await cursor.to_list(length=limit)

        result = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "total_count": total_count,  # helpful for frontend
            "limit": limit,
            "offset": offset,
            "data": []
        }

        for entry in data:
            created_at = entry.get("created_at")

            if isinstance(created_at, datetime):
                date_str = created_at.strftime("%Y-%m-%d")
            else:
                date_str = None

            treatment_plan_data = {
                "date": date_str,
                "finaloutput": entry.get("finaloutput"),
                "status": entry.get("status"),
            }

            result["data"].append(treatment_plan_data)

        return result

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.get("/clinical-notes-by-patient-doctor/{patient_id}/{doctor_id}")
async def get_clinical_notes_by_patient_doctor(patient_id: str, doctor_id: str):
    try:
        # Fetch all documents based on patient_id and doctor_id
        data_cursor = documentation_clinical_notes_collection.find({
            "doctor_id": doctor_id,
            "patient_id": patient_id
        })
        data = await data_cursor.to_list(length=None)

        if not data:
            raise HTTPException(status_code=404, detail="No clinical notes found for this doctor and patient")

        # Prepare the response data with date on top and structured format
        result = {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "data": []
        }

        for entry in data:
            # Extract the date from the created_at field and format it
            created_at = entry.get("created_at")
            if isinstance(created_at, datetime):
                date_str = created_at.strftime("%Y-%m-%d")
            else:
                raise HTTPException(status_code=400, detail="Invalid date format in document")

            # Remove unnecessary fields
            clinical_notes_data = {
                "date": date_str,
                "clinical_validation": entry.get("finaloutput", {}).get("clinical_validation"),
                "doctor_edits": entry.get("finaloutput", {}).get("doctor_edits"),
                "status": entry.get("status"),
            }


            result["data"].append(clinical_notes_data)

        return result

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    
    


