@router.post("/verify-patient-summary")
async def verify_patient_summary(payload: dict):

    try:

        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")

        # =========================
        # GET LATEST SUMMARY
        # =========================
        summary = await summary_collection.find_one(
            {
                "patient_id": patient_id,
                "doctor_id": doctor_id
            },
            sort=[("generated_at", -1)]
        )

        if not summary:

            return {
                "success": False,
                "message": "No summary found"
            }

        summary_payload = {

            "tag": "patient_summary",

            "summary_id":
                str(summary.get("_id")),

            "patient_id":
                patient_id,

            "doctor_id":
                doctor_id,

            "summary":
                summary.get("summary"),

            "generated_at":
                str(summary.get("generated_at")),

            "full_data":
                summary
        }

        # =========================
        # HOSPITAL INTEGRATOR
        # =========================
        try:

            await trigger_hospital_integrator_patientsummary(
                summary_payload,
                doctor_id,
                patient_id
            )

            logger.info(
                f"✅ Summary integrator triggered | patient={patient_id}"
            )

        except Exception as integrator_error:

            logger.error(
                f"❌ Summary integrator failed | "
                f"patient={patient_id} | "
                f"error={str(integrator_error)}",
                exc_info=True
            )

        return {
            "success": True,
            "message":
                "Patient summary verified successfully"
        }

    except Exception as e:

        logger.error(
            f"Verify patient summary failed: {str(e)}",
            exc_info=True
        )

        return {
            "success": False,
            "message": str(e)
        }


