# ============================================================
# SINGLE GET ENDPOINT - DIRECT DB ACCESS
# ============================================================

@router.get("/api/pipeline/tasks/{doctor_id}")
async def get_doctor_tasks(
    doctor_id: str,
    status: Optional[str] = Query(None, description="Filter by status: processing, completed, failed"),
    limit: int = Query(50, ge=1, le=200),
    skip: int = Query(0, ge=0)
):
    """
    Retrieve all pipeline tasks for a specific doctor directly from database
    """
    # ✅ FIXED: Use 'db' instead of 'mongo_db'
    tracker = db["agent_pdf_tracker"]
    
    # Build query
    query = {"doctor_id": doctor_id}
    if status:
        if status not in ["processing", "completed", "failed"]:
            raise HTTPException(status_code=400, detail="Invalid status")
        query["status"] = status
    
    # Get total count
    total = tracker.count_documents(query)
    
    # Get tasks from database
    cursor = tracker.find(query).sort("started_at", -1).skip(skip).limit(limit)
    tasks = []
    
    for task in cursor:
        # Convert ObjectId to string for JSON response
        task["_id"] = str(task["_id"])
        tasks.append(task)
    
    # Get statistics from database
    pipeline = [
        {"$match": {"doctor_id": doctor_id}},
        {"$group": {
            "_id": "$status",
            "count": {"$sum": 1}
        }}
    ]
    
    stats_result = list(tracker.aggregate(pipeline))
    statistics = {
        "total": total,
        "processing": 0,
        "completed": 0,
        "failed": 0
    }
    
    for item in stats_result:
        status_key = item["_id"]
        count = item["count"]
        if status_key in statistics:
            statistics[status_key] = count
    
    return {
        "doctor_id": doctor_id,
        "total": total,
        "tasks": tasks,
        "statistics": statistics
    }


