@router.get("/api/pipeline/task/{task_id}")
async def get_task_by_id(task_id: str):
    """
    Get a specific task by its Celery task ID directly from database
    """
    # ✅ FIXED: Use 'db' instead of 'mongo_db'
    tracker = db["agent_pdf_tracker"]
    task = tracker.find_one({"task_id": task_id})
    
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    
    # Convert ObjectId to string
    task["_id"] = str(task["_id"])
    
    return task





