@router.delete("/delete/pipeline/tasks/{doctor_id}")
async def delete_doctor_tasks(
    doctor_id: str,
    status: Optional[str] = Query(None, description="Filter by status: processing, completed, failed")
):
    """
    Delete all pipeline tasks for a specific doctor
    Optionally filter by status
    """
    tracker = db["agent_pdf_tracker"]
    
    # Build query
    query = {"doctor_id": doctor_id}
    if status:
        if status not in ["processing", "completed", "failed"]:
            raise HTTPException(status_code=400, detail="Invalid status")
        query["status"] = status
    
    # Delete matching documents
    result = tracker.delete_many(query)
    
    return {
        "status": "success",
        "doctor_id": doctor_id,
        "status_filter": status if status else "all",
        "deleted_count": result.deleted_count,
        "message": f"Deleted {result.deleted_count} task(s) for doctor {doctor_id}"
    }


@router.delete("/delete/pipeline/task/{task_id}")
async def delete_task_by_id(task_id: str):
    """
    Delete a specific task by its Celery task ID
    """
    tracker = db["agent_pdf_tracker"]
    
    # Check if task exists first
    task = tracker.find_one({"task_id": task_id})
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    
    # Delete the task
    result = tracker.delete_one({"task_id": task_id})
    
    return {
        "status": "success",
        "task_id": task_id,
        "deleted_count": result.deleted_count,
        "message": f"Task {task_id} deleted successfully"
    }


