@router.delete("/api/pipeline/tasks/older-than/{days}")
async def delete_old_tasks(days: int):
    """
    Delete tasks older than specified days
    """
    tracker = db["agent_pdf_tracker"]
    
    # Calculate cutoff date
    cutoff_date = datetime.utcnow() - timedelta(days=days)
    
    # Build query for tasks older than cutoff
    query = {
        "started_at": {"$lt": cutoff_date}
    }
    
    # Delete matching documents
    result = tracker.delete_many(query)
    
    return {
        "status": "success",
        "days": days,
        "cutoff_date": cutoff_date.isoformat(),
        "deleted_count": result.deleted_count,
        "message": f"Deleted {result.deleted_count} task(s) older than {days} days"
    }


