@router.get("/api/pipeline/tasks/{doctor_id}/status/batch")
async def get_tasks_status_batch(
    doctor_id: str,
    task_ids: str = Query(..., description="Comma-separated task IDs")
):
    """
    Check status of multiple tasks in one request
    """
    tracker = db["agent_pdf_tracker"]
    task_id_list = task_ids.split(',')
    
    results = {}
    for task_id in task_id_list:
        task = tracker.find_one({"task_id": task_id}, {"_id": 0, "status": 1, "completed_at": 1, "failed_at": 1, "error": 1})
        if task:
            results[task_id] = task
        else:
            results[task_id] = {"status": "not_found"}
    
    return results

