class ConversationStructureRequest(BaseModel):
    conversation_text: Optional[str] = None

@router.post("/structure_conversation_simple")
async def structure_conversation_simple(request: ConversationStructureRequest):
    try:
        logger.info("Received /structure_conversation_simple request")

        if not request.conversation_text or not request.conversation_text.strip():
            logger.warning("Conversation text is missing or empty")
            raise HTTPException(
                status_code=400,
                detail="Conversation text is missing or empty."
            )

        prompt = f"""
You are a professional clinical AI assistant specializing in medical conversation analysis and documentation. 
Carefully analyze the provided conversation transcript, translate all content strictly into professional English, 
and assign roles to each sentence as "Doctor" or "Patient".

**Instructions:**
1. Process ONLY the provided conversation text — do NOT add, infer, or create any external content or dialogue.
2. Process every speaker turn individually; preserve multi-sentence turns for the same speaker in a single block.
3. Do not split consecutive sentences from the same speaker into multiple "Doctor:" or "Patient:" entries.
4. Conversations may start with Doctor or Patient; detect the speaker correctly.
5. Translate all text strictly into professional English; preserve medical terminology, grammar, and exact meaning.
6. Assign each speaker turn exactly as "Doctor:" or "Patient:".
7. Patient introductions (e.g., name, self-identification) always belong to Patient.
8. Patient greetings to the doctor (e.g., "Hi doctor", "Hello doctor") always belong to Patient.
9. Any diagnostic, history-taking, or symptom-related question is always Doctor.
10. Any patient response, acknowledgment, or symptom report is always Patient.
11. Correct any misassigned roles if the original text is wrong.
12. Maintain the original sequence of the conversation.
13. Output must contain ONLY the processed conversation in valid JSON format — do NOT include explanations, comments, or summaries.

**Speaker Identification Rules:**
- Doctor: asks medical questions, provides advice, prescriptions, or instructions.
- Patient: greets, introduces themselves, responds to questions, or acknowledges advice.

**Conversation Text (any language):**
{request.conversation_text}

**Required Output (strictly in English, JSON):**
{{"conversation": ["Doctor: text", "Patient: text", ...]}}
"""


        logger.info("Sending prompt to LLM for conversation structuring")

        try:
            completion = groq_client.chat.completions.create(
                model="llama-3.1-8b-instant",
                messages=[{"role": "user", "content": prompt}],
                temperature=0.1,
                response_format={"type": "json_object"},
                max_tokens=2000
            )
        except Exception as e:
            logger.error(f"LLM call failed: {e}")
            raise HTTPException(status_code=500, detail="LLM call failed")

        raw_output = completion.choices[0].message.content.strip()
        logger.info(f"LLM raw output: {raw_output[:300]}")

        # Parse JSON safely
        try:
            parsed_data = json.loads(raw_output)
        except json.JSONDecodeError:
            logger.warning("Direct JSON parse failed, retrying with regex")
            json_match = re.search(r'(\{.*\})', raw_output, re.DOTALL)
            if not json_match:
                logger.error("No JSON structure found in AI output")
                raise HTTPException(status_code=500, detail="Invalid JSON from AI")
            parsed_data = json.loads(json_match.group(1))

        conversation = parsed_data.get("conversation", [])
        if not isinstance(conversation, list):
            conversation = []

        # Enhanced validation with specific rule for patient introductions
        validated_conversation = []
        
        for i, line in enumerate(conversation):
            if not isinstance(line, str) or not line.strip():
                continue
            
            line = line.strip()
            
            # Check if line already has proper speaker prefix
            if re.match(r'^Doctor:', line):
                # Special check: if doctor line contains patient introduction, correct it
                line_content = line.replace('Doctor:', '').strip()
                if any(indicator in line_content.lower() for indicator in 
                      ['hi, doctor', 'hello doctor', 'hi doctor', 'hello, doctor']):
                    validated_conversation.append(f"Patient: {line_content}")
                elif (len(line_content.split()) <= 3 and 
                      line_content[0].isupper() and 
                      not line_content.endswith('?')):
                    # Likely a patient name introduction
                    validated_conversation.append(f"Patient: {line_content}")
                else:
                    validated_conversation.append(line)
                    
            elif re.match(r'^Patient:', line):
                validated_conversation.append(line)
            else:
                # If no prefix, analyze content
                line_lower = line.lower()
                if any(indicator in line_lower for indicator in 
                      ['hi, doctor', 'hello doctor', 'hi doctor', 'hello, doctor']):
                    validated_conversation.append(f"Patient: {line}")
                elif (len(line.split()) <= 3 and 
                      line[0].isupper() and 
                      not line.endswith('?')):
                    validated_conversation.append(f"Patient: {line}")
                else:
                    validated_conversation.append(f"Doctor: {line}")

        result = {
            "conversation": validated_conversation
        }

        return result

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Unhandled error: {e}")
        raise HTTPException(status_code=500, detail="Internal server error")
    
    




class NurseConversationRequestmobER(BaseModel):
    conversation_text: Optional[str] = None


@router.post("/structure_nurse_patient_conversation_mobile")
async def structure_nurse_patient_conversation_mobile(request: NurseConversationRequestmobER):
    """
    Processes a raw conversation between a nurse and a patient using an LLM,
    identifies each speaker, and returns a structured JSON array (parsed as readable text).
    """

    try:
        logger.info("Received /structure_nurse_patient_conversation_mobile request")

        if not request.conversation_text or not request.conversation_text.strip():
            logger.warning("Conversation text is missing or empty")
            raise HTTPException(
                status_code=400,
                detail="Conversation text is missing or empty."
            )

        # ====================== PROMPT ======================
        prompt = f"""
You are a medical AI assistant specializing in **nurse-patient conversation structuring**.
Analyze the conversation transcript and separate each sentence as either spoken by the **Nurse** or the **Patient**.

🔹 *STRICT RULES - FOLLOW EXACTLY:*
1. Only use the conversation provided below. Do NOT invent, infer, or fill in missing text.
2. Identify each speaker as either "Nurse" or "Patient".
3. Maintain the same order of dialogue.
4. Translate everything to clear English (if any other language is used).
5. Output MUST be valid JSON with a single key `"conversation"` containing a list of dialogue lines.
6. ❗ Do NOT hallucinate, generate assumptions, or create any content not explicitly present in the original text.

🔹 *Speaker Identification Guidelines:*
- **Nurse:** greets, explains procedures, asks about pain, vitals, comfort, medication, food intake, urine/stool output, allergies, wound care, sleep, or emotional state; provides instructions for aftercare, medication adherence, or health education.
- **Patient:** responds to nurse’s questions, describes how they feel, reports pain or discomfort, asks for help, or acknowledges instructions.

🧩 *Conversation Text to Process (any language):*
{request.conversation_text}

📦 *Required Output Format (strictly in English):*
{{"conversation": ["Nurse: text", "Patient: text", "Nurse: text", ...]}}
"""
        # =====================================================

        logger.info("Sending nurse-patient prompt to LLM")

        try:
            completion = groq_client.chat.completions.create(
                model="llama-3.1-8b-instant",
                messages=[{"role": "user", "content": prompt}],
                temperature=0.1,
                response_format={"type": "json_object"},
                max_tokens=1200,
            )
        except Exception as e:
            logger.error(f"LLM call failed: {e}")
            raise HTTPException(status_code=500, detail="LLM call failed")

        # === Parse LLM Output ===
        raw_output = completion.choices[0].message.content.strip()
        logger.info(f"=== RAW LLM OUTPUT START ===\n{raw_output}\n=== RAW LLM OUTPUT END ===")

        parsed_data = {}
        try:
            parsed_data = json.loads(raw_output)
        except json.JSONDecodeError:
            logger.warning("Direct JSON parse failed, retrying with regex")
            json_match = re.search(r'\{[\s\S]*\}', raw_output)
            if json_match:
                try:
                    parsed_data = json.loads(json_match.group(0))
                except Exception as e:
                    logger.error(f"Second parse failed: {e}")
            else:
                logger.error("No JSON found in LLM output")

        # === Normalize output ===
        conversation = parsed_data.get("conversation") or parsed_data.get("dialogue") or parsed_data.get("data") or []

        # If conversation is a list of objects, flatten it
        parsed_conversation = []
        for item in conversation:
            if isinstance(item, dict):
                for speaker, text in item.items():
                    parsed_conversation.append(f"{speaker}: {text}")
            elif isinstance(item, str):
                parsed_conversation.append(item)

        result = {"conversation": parsed_conversation}

        logger.info(f"✅ Parsed nurse-patient conversation generated with {len(parsed_conversation)} lines")
        return result

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Unhandled error in /structure_nurse_patient_conversation_mobile: {e}")
        raise HTTPException(status_code=500, detail="Internal server error")
    
    
