import uuid

@router.post("/save-chemotherapy-record")
async def save_chemotherapy_record(request: Request):
    try:
        data = await request.json()
        doc_id = data.get("doctorId")
        patient_id = data.get("patientId")
        hospital_id = data.get("hospitalId", "")
        treatment_id = data.get("treatmentId")
        status = data.get("status", "active")
        
        if not doc_id or not patient_id:
            raise HTTPException(status_code=400, detail="doctorId and patientId are required")
            
        if not hospital_id and doc_id:
            try:
                async with httpx.AsyncClient(timeout=10.0) as client:
                    doc_resp = await client.get(f"{api_base_url}hms/users/doctors/get_doctor/{doc_id}")
                    if doc_resp.status_code == 200:
                        doc_data = doc_resp.json()
                        data_obj = doc_data.get("data") or doc_data.get("doctor") or doc_data
                        if isinstance(data_obj, dict):
                            hospital_id = data_obj.get("hospital_id", "")
            except Exception as e:
                logger.error(f"Failed to fetch hospital ID for doctor {doc_id}: {e}")
                
        record = {
            "doctorId": doc_id,
            "patientId": patient_id,
            "hospitalId": hospital_id,
            "status": status,
            "data": data.get("formData", {}),
            "treatment": data.get("treatment", {}),
            "updatedAt": datetime.utcnow()
        }
        
        # Determine if we update an existing record or create a new one
        if treatment_id:
            record["treatmentId"] = treatment_id
            await chemotherapy_records_collection.update_one(
                {"treatmentId": treatment_id},
                {"$set": record},
                upsert=True
            )
        else:
            # Check for active or legacy record missing a status
            existing = await chemotherapy_records_collection.find_one({
                "patientId": patient_id,
                "doctorId": doc_id,
                "$or": [{"status": "active"}, {"status": {"$exists": False}}]
            })
            if existing:
                treatment_id = existing.get("treatmentId", str(uuid.uuid4()))
                record["treatmentId"] = treatment_id
                await chemotherapy_records_collection.update_one(
                    {"_id": existing["_id"]},
                    {"$set": record}
                )
            else:
                treatment_id = str(uuid.uuid4())
                record["treatmentId"] = treatment_id
                await chemotherapy_records_collection.insert_one(record)
                
        # Remove _id for JSON serializability in response
        if "_id" in record:
            del record["_id"]

        # ==========================================================
        # 🔥 TEMP DATA SAVE
        # ==========================================================
        from fastapi.encoders import jsonable_encoder
        temp_payload = jsonable_encoder({
            "patient_id": patient_id,
            "doctor_id": doc_id,
            "chemotherapy_workflow": [record]
        })

        try:
            async with httpx.AsyncClient(timeout=15.0) as client:
                temp_response = await client.post(
                    f"{api_base_url}hms/users/data/context/general/temp/save",
                    json=temp_payload
                )

            if temp_response.status_code != 200:
                logger.error(
                    f"Temp save failed: {temp_response.status_code} - {temp_response.text}"
                )

        except Exception as e:
            logger.error(f"Temp save exception: {str(e)}")

        return {
            "status": "success",
            "message": "Chemotherapy record saved successfully",
            "treatmentId": treatment_id
        }
    except Exception as e:
        logger.error(f"Failed to save chemotherapy record: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")

@router.get("/get-chemotherapy-record")
async def get_chemotherapy_record(patientId: str, doctorId: str, hospitalId: str = "", treatmentId: str = None):
    try:
        if not patientId or not doctorId:
            raise HTTPException(status_code=400, detail="Missing required parameters")
            
        if treatmentId:
            record = await chemotherapy_records_collection.find_one(
                {"treatmentId": treatmentId},
                {"_id": 0}
            )
        else:
            record = await chemotherapy_records_collection.find_one(
                {"patientId": patientId, "doctorId": doctorId, "status": "active"},
                {"_id": 0}
            )
            # Fallback for old legacy records
            if not record:
                record = await chemotherapy_records_collection.find_one(
                    {"patientId": patientId, "doctorId": doctorId, "treatmentId": {"$exists": False}},
                    {"_id": 0}
                )
                
        data = record.get("data", {}) if record else {}
        treatment = record.get("treatment", {}) if record else {}
        ret_treatment_id = record.get("treatmentId") if record else None
        ret_status = record.get("status", "active") if record else "active"

        # Fetch latest medication analysis to auto-populate medsGiven
        latest_med_event = await documentation_medication_analysis_collection.find_one(
            {"patient_id": patientId, "feature_id": "documentation-medication-analysis"},
            sort=[("created_at", -1)]
        )
        
        if latest_med_event and "finaloutput" in latest_med_event:
            prescriptions = latest_med_event["finaloutput"].get("prescriptions", [])
            if prescriptions:
                # Retrieve the latest medication if there are multiple
                latest_medication = prescriptions[-1].get("medication", "")
                
                # Update data with latest medication if not already set
                if "cycle_admin" not in data:
                    data["cycle_admin"] = {}
                if not data["cycle_admin"].get("medsGiven"):
                    data["cycle_admin"]["medsGiven"] = latest_medication

        return {
            "status": "success", 
            "data": data, 
            "treatment": treatment,
            "treatmentId": ret_treatment_id,
            "treatmentStatus": ret_status
        }
    except Exception as e:
        logger.error(f"Failed to get chemotherapy record: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")

@router.get("/get-patient-chemotherapy-history")
async def get_patient_chemotherapy_history(patientId: str, doctorId: str):
    try:
        if not patientId or not doctorId:
            raise HTTPException(status_code=400, detail="Missing required parameters")
            
        cursor = chemotherapy_records_collection.find(
            {"patientId": patientId, "doctorId": doctorId},
            {"_id": 0, "treatmentId": 1, "status": 1, "updatedAt": 1, "data.cycles.1.regimen": 1, "treatment.plannedCycles": 1}
        ).sort("updatedAt", -1)
        
        history = []
        async for record in cursor:
            regimen = record.get("data", {}).get("cycles", {}).get("1", {}).get("regimen", {})
            planned_cycles = record.get("treatment", {}).get("plannedCycles", "0")
            history.append({
                "treatmentId": record.get("treatmentId"),
                "status": record.get("status", "active"),
                "updatedAt": record.get("updatedAt"),
                "protocolName": regimen.get("selectedProtocol", "Unknown Protocol"),
                "startDate": regimen.get("startDate", "Unknown Date"),
                "cycles": str(planned_cycles)
            })
            
        return {"status": "success", "history": history}
    except Exception as e:
        logger.error(f"Failed to get chemotherapy history: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")
        
        
