@router.post("/preventive-screening/save")
async def save_preventive_screening(request: Request):
    try:
        payload = await request.json()
        doctor_id = payload.get("doctor_id")
        patient_id = payload.get("patient_id")
        appointment_id = payload.get("appointment_id")
        case_history = payload.get("case_history")
        examination = payload.get("examination")

        if not patient_id:
            raise HTTPException(status_code=400, detail="patient_id is required")
        if case_history is None or examination is None:
            raise HTTPException(status_code=400, detail="case_history and examination are required")

        update_doc = {
            "$set": {
                "patient_id": patient_id,          # ✅ always stamped on the record
                "doctor_id": doctor_id,
                "appointment_id": appointment_id,
                "case_history": case_history,       # ✅ full nested object, every field
                "examination": examination,         # ✅ full nested object, every field
            },
            "$setOnInsert": {
                "created_at": datetime.utcnow(),
            },
            "$currentDate": {"updated_at": True},
        }

        result = await preventive_screening_collection.update_one(
            {"patient_id": patient_id},
            update_doc,
            upsert=True,
        )

        return {
            "status": "success",
            "patient_id": patient_id,
            "matched": result.matched_count,
            "upserted": result.upserted_id is not None,
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.exception("Preventive screening save failed")
        raise HTTPException(status_code=500, detail=f"Save error: {str(e)}")


