@router.put("/approve-tumor-board-plan/{patient_id}/{doctor_id}")
async def approve_tumor_board_plan(
    patient_id: str,
    doctor_id: str
):
    try:
        # Find latest tumor board plan for this patient and doctor
        latest_plan = await tumor_board_plan_collection.find_one(
            {
                "patient_id": patient_id,
                "doctor_approvals": {
                    "$elemMatch": {
                        "doctor_id": doctor_id
                    }
                }
            },
            sort=[("created_at", -1)]
        )

        if not latest_plan:
            raise HTTPException(
                status_code=404,
                detail="Latest tumor board plan not found for this patient and doctor"
            )

        # Update only that doctor's approval status in the latest record
        result = await tumor_board_plan_collection.update_one(
            {
                "_id": latest_plan["_id"],
                "doctor_approvals.doctor_id": doctor_id
            },
            {
                "$set": {
                    "doctor_approvals.$[doctor].status": "approved",
                    "updated_at": datetime.utcnow()
                }
            },
            array_filters=[
                {
                    "doctor.doctor_id": doctor_id
                }
            ]
        )

        if result.modified_count == 0:
            raise HTTPException(
                status_code=400,
                detail="Doctor approval status was not updated"
            )
        # ==========================================================
        # FETCH UPDATED PLAN
        # ==========================================================
        updated_plan = await tumor_board_plan_collection.find_one(
            {"_id": latest_plan["_id"]}
        )

        # ==========================================================
        # CHECK IF ALL DOCTORS APPROVED
        # ==========================================================
        all_approved = all(
            approval.get("status") == "approved"
            for approval in updated_plan.get("doctor_approvals", [])
        )

        # ==========================================================
        # TEMP SAVE ONLY AFTER ALL DOCTORS APPROVED
        # ==========================================================
        if all_approved:
            updated_plan.pop("_id", None)
            temp_payload = jsonable_encoder({
                "patient_id": patient_id,
                "doctor_id": doctor_id,
                "tumor_board_plan": [updated_plan]
            })

            try:
                async with httpx.AsyncClient(timeout=15.0) as client:
                    temp_response = await client.post(
                        f"{api_base_url}hms/users/data/context/general/temp/save",
                        json=temp_payload
                    )

                if temp_response.status_code != 200:
                    logger.error(
                        f"Tumor Board Temp Save Failed: "
                        f"{temp_response.status_code} - {temp_response.text}"
                    )

            except Exception as e:
                logger.error(f"Tumor Board Temp Save Exception: {str(e)}")
        return {
            "message": "Latest tumor board plan doctor approval updated successfully",
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "status": "approved"
        }

    except HTTPException:
        raise

    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=f"Failed to update doctor approval status: {str(e)}"
        )

        
@router.get("/get-documentation-outputs")
async def get_documentation_outputs(patient_id: str, doctor_id: str):

    logger.info(f"[get-documentation-outputs] START — patient_id={patient_id}, doctor_id={doctor_id}")

    # ==========================================================
    # 1️⃣ RESOLVE CURRENT + PREVIOUS APPOINTMENT FROM DB
    # ==========================================================
    appt_doc = patient_appointments_collection.find_one(
        {"sys_user_id": patient_id},
        {"_id": 0, "appointments": 1}
    )

    logger.info(f"[get-documentation-outputs] appt_doc found: {appt_doc is not None}")

    if not appt_doc:
        logger.warning(f"[get-documentation-outputs] No appointments doc found for sys_user_id={patient_id}")
        raise HTTPException(
            status_code=404,
            detail="No appointments found for this patient"
        )

    logger.info(f"[get-documentation-outputs] total appointments for patient: {len(appt_doc.get('appointments', []))}")
    logger.info(f"[get-documentation-outputs] all doctor_ids in appointments: {[a.get('doctor_id') for a in appt_doc.get('appointments', [])]}")

    doctor_appts = [
        a for a in appt_doc.get("appointments", [])
        if a.get("doctor_id") == doctor_id
    ]
    logger.info(f"[get-documentation-outputs] doctor_appts (matched count={len(doctor_appts)}): {doctor_appts}")

    if not doctor_appts:
        logger.warning(f"[get-documentation-outputs] No appointments matched doctor_id={doctor_id}")
        raise HTTPException(
            status_code=404,
            detail="No appointments found for this patient with this doctor"
        )

    # sort chronologically ascending (date, then scheduled_time as tiebreaker)
    doctor_appts.sort(
        key=lambda a: (a.get("date") or "", a.get("scheduled_time") or "")
    )
    logger.info(f"[get-documentation-outputs] doctor_appts sorted: {[(a.get('appointment_id'), a.get('date')) for a in doctor_appts]}")

    current_appointment_id = doctor_appts[-1].get("appointment_id")   # latest = current
    previous_appointment_id = (
        doctor_appts[-2].get("appointment_id") if len(doctor_appts) >= 2 else None
    )
    logger.info(f"[get-documentation-outputs] current_appointment_id={current_appointment_id}")
    logger.info(f"[get-documentation-outputs] previous_appointment_id={previous_appointment_id}")

    if not previous_appointment_id:
        logger.warning(f"[get-documentation-outputs] Only {len(doctor_appts)} appointment(s) found — no previous appointment available")
        raise HTTPException(
            status_code=404,
            detail="No previous appointment found for this patient and doctor"
        )

    # ==========================================================
    # 2️⃣ QUERY DOCUMENTATION FOR THAT PREVIOUS APPOINTMENT ONLY
    # ==========================================================
    query = {
        "metadata.patient_id": patient_id,
        "metadata.doctor_id": doctor_id,
        "appointment_id": previous_appointment_id,
        "status": "success"
    }
    logger.info(f"[get-documentation-outputs] documentation query: {query}")

    projection = {
        "_id": 1,
        "feature_id": 1,
        "feature_name": 1,
        "display_method": 1,
        "finaloutput": 1,
        "metadata": 1,
        "appointment_id": 1,
        "created_at": 1
    }

    collections = [
        documentation_treatment_plan_collection,
        documentation_investigation_notes_collection,
        documentation_medication_analysis_collection,
        documentation_clinical_notes_collection,
    ]

    results = []

    for collection in collections:
        docs = await collection.find(query, projection).to_list(length=None)
        logger.info(f"[get-documentation-outputs] {collection.name} — matched {len(docs)} docs with strict query")
        for doc in docs:
            doc["_id"] = str(doc["_id"])
            if isinstance(doc.get("created_at"), datetime):
                doc["created_at"] = doc["created_at"].isoformat()
            results.append(doc)

    logger.info(f"[get-documentation-outputs] total results after strict query: {len(results)}")

    # 🔍 DEBUG — if nothing matched, show what's actually stored (ignoring appointment_id/status filters)
    if not results:
        logger.warning("[get-documentation-outputs] No results with strict query — running debug lookup without appointment_id/status filters")
        debug_query = {
            "metadata.patient_id": patient_id,
            "metadata.doctor_id": doctor_id,
        }
        logger.info(f"[get-documentation-outputs] debug_query: {debug_query}")
        for collection in collections:
            debug_docs = await collection.find(
                debug_query,
                {"appointment_id": 1, "status": 1, "metadata": 1, "created_at": 1, "feature_id": 1}
            ).to_list(length=None)
            logger.info(f"[get-documentation-outputs][DEBUG] {collection.name} — ALL docs for this patient/doctor ({len(debug_docs)}): {debug_docs}")

    if not results:
        logger.warning(f"[get-documentation-outputs] Returning 404 — no documentation found for appointment_id={previous_appointment_id}")
        raise HTTPException(
            status_code=404,
            detail=f"No documentation outputs found for appointment '{previous_appointment_id}'"
        )

    results.sort(key=lambda x: x.get("created_at", ""), reverse=True)
    logger.info(f"[get-documentation-outputs] final sorted results count: {len(results)}")

    # ==========================================================
    # 3️⃣ FETCH VITALS FOR THAT PREVIOUS APPOINTMENT ONLY
    # ==========================================================
    vitals_doc = await patient_vitals_collection.find_one(
        {"sys_user_id": patient_id},
        {"_id": 0, "sys_user_id": 1, "patient_id": 1, "updated_at": 1, "vitals": 1}
    )
    logger.info(f"[get-documentation-outputs] vitals_doc found: {vitals_doc is not None}")

    vitals_data = None
    if vitals_doc:
        raw_vitals = vitals_doc.get("vitals", {})
        logger.info(f"[get-documentation-outputs] raw_vitals timestamp keys: {list(raw_vitals.keys())}")
        logger.info(f"[get-documentation-outputs] raw_vitals appointment_ids: {[(ts, entry.get('appointment_id')) for ts, entry in raw_vitals.items()]}")

        sorted_vitals = sorted(
            [
                {
                    "timestamp": ts,
                    "doctor_id": entry.get("doctor_id"),
                    "appointment_id": entry.get("appointment_id"),
                    "blood_pressure": entry.get("blood_pressure"),
                    "respiratory_rate": entry.get("respiratory_rate"),
                    "heart_rate": entry.get("heart_rate"),
                    "electrocardiogram_ecg": entry.get("electrocardiogram_ecg"),
                    "electrolytes": entry.get("electrolytes"),
                    "weight": entry.get("weight"),
                    "arterial_blood_gas_abg": entry.get("arterial_blood_gas_abg"),
                }
                for ts, entry in raw_vitals.items()
                if entry.get("appointment_id") == previous_appointment_id
            ],
            key=lambda x: x["timestamp"],
            reverse=True
        )
        logger.info(f"[get-documentation-outputs] sorted_vitals matched count: {len(sorted_vitals)}")

        if sorted_vitals:
            vitals_data = {
                "sys_user_id": vitals_doc.get("sys_user_id"),
                "patient_id": vitals_doc.get("patient_id"),
                "updated_at": vitals_doc.get("updated_at").isoformat() if isinstance(vitals_doc.get("updated_at"), datetime) else vitals_doc.get("updated_at"),
                "vitals": sorted_vitals
            }

    logger.info(f"[get-documentation-outputs] vitals_data present: {vitals_data is not None}")
    logger.info(f"[get-documentation-outputs] END — returning {len(results)} documentation results")

    return {
        "patient_id": patient_id,
        "doctor_id": doctor_id,
        "current_appointment_id": current_appointment_id,
        "previous_appointment_id": previous_appointment_id,
        "total": len(results),
        "documentation_outputs": results,
        "vitals": vitals_data
    }



