@router.put("/complete-tumor-board-step/{patient_id}/{doctor_id}/{step_number}")
async def complete_tumor_board_step(
    patient_id: str,
    doctor_id: str,
    step_number: int
):
    try:

        # Find latest fully approved tumor board plan
        latest_plan = await tumor_board_plan_collection.find_one(
            {
                "patient_id": patient_id,
                "doctor_approvals": {
                    "$not": {
                        "$elemMatch": {
                            "status": {
                                "$ne": "approved"
                            }
                        }
                    }
                }
            },
            sort=[("created_at", -1)]
        )


        if not latest_plan:
            raise HTTPException(
                status_code=404,
                detail="No fully approved tumor board plan found"
            )


        # Verify doctor exists in approvals
        doctor_exists = any(
            doctor["doctor_id"] == doctor_id
            for doctor in latest_plan.get("doctor_approvals", [])
        )


        if not doctor_exists:
            raise HTTPException(
                status_code=403,
                detail="Doctor is not part of this tumor board plan"
            )


        # Check step exists
        steps = latest_plan["care_pathway_plan"]["steps"]

        step_exists = any(
            step["step_number"] == step_number
            for step in steps
        )


        if not step_exists:
            raise HTTPException(
                status_code=404,
                detail=f"Step {step_number} not found"
            )


        # Update specific step status
        result = await tumor_board_plan_collection.update_one(
            {
                "_id": latest_plan["_id"]
            },
            {
                "$set": {
                    "care_pathway_plan.steps.$[step].status": "completed",
                    "care_pathway_plan.steps.$[step].status_reason": 
                        "Step completed by doctor",
                    "updated_at": datetime.utcnow()
                }
            },
            array_filters=[
                {
                    "step.step_number": step_number
                }
            ]
        )


        if result.modified_count == 0:
            raise HTTPException(
                status_code=400,
                detail="Step status was not updated"
            )


        return {
            "message": "Tumor board step completed successfully",
            "patient_id": patient_id,
            "step_number": step_number,
            "status": "completed"
        }


    except HTTPException:
        raise


    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=f"Failed to complete tumor board step: {str(e)}"
        )


