class CreateInvestigationPayload(BaseModel):
    patient_id: str
    doctor_id: str
    clinical_indication: str
    parameters: Union[list, str]
    investigation_type: str
    order_context: Optional[Dict[str, Any]] = None


@router.post("/oncology-investigations")
async def create_investigation(payload: CreateInvestigationPayload):
    """
    Create a new oncology investigation record for a doctor.
    The id is incremented per doctor starting from 0.
    """
    try:
        # Find the max ID for this doctor to auto-increment
        cursor = (
            oncology_investigations_collection.find({"doctor_id": payload.doctor_id})
            .sort("id", -1)
            .limit(1)
        )

        last_doc = await cursor.to_list(length=1)
        next_id = 0
        if last_doc and "id" in last_doc[0]:
            next_id = last_doc[0]["id"] + 1

        now = datetime.utcnow()
        date_str = now.strftime("%Y%m%d%H%M%S")
        investigation_key = (
            f"{payload.investigation_type}_{date_str}_{payload.doctor_id}"
        )

        document = {
            "patient_id": payload.patient_id,
            "doctor_id": payload.doctor_id,
            "id": next_id,
            "clinical_indication": payload.clinical_indication,
            "investigation": investigation_key,
            "parameters": payload.parameters,
            "document_id": None,
            "status": "pending",
            "date_of_order": now,
            "order_context": payload.order_context,
        }

        await oncology_investigations_collection.insert_one(document)

        return {
            "status": "success",
            "message": "Investigation order created successfully",
            "investigation_id": next_id,
            "investigation_key": investigation_key,
        }

    except Exception as e:
        logger.error(f"Error creating investigation: {e}")
        raise HTTPException(status_code=500, detail="Failed to create investigation")


@router.get("/oncology-investigations/{patient_id}")
async def get_investigations(patient_id: str, doctor_id: Optional[str] = None):
    """
    Get the history of investigations for a patient, optionally filtered by doctor_id.
    """
    try:
        query = {"patient_id": patient_id}
        if doctor_id:
            query["doctor_id"] = doctor_id

        cursor = oncology_investigations_collection.find(query).sort(
            "date_of_order", -1
        )
        docs = await cursor.to_list(length=100)
        

        history = []
        for doc in docs:
            doc["_id"] = str(doc["_id"])
            if "date_of_order" in doc and hasattr(doc["date_of_order"], "isoformat"):
                doc["date_of_order"] = doc["date_of_order"].isoformat()
            history.append(doc)

        return {"status": "success", "data": history}

    except Exception as e:
        logger.error(f"Error fetching investigations: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch investigations")


class UnifiedInvestigationSuggestionPayload(BaseModel):
    patient_id: str
    department: str
    booking_id: Optional[str] = None
    doctor_id: Optional[str] = None
    hospital_id: Optional[str] = None

    

@router.post("/oncology-investigations/generate-suggestion")
async def generate_unified_investigation_suggestion(payload: UnifiedInvestigationSuggestionPayload):
    api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        raise HTTPException(status_code=500, detail="GROQ_API_KEY not configured on server")

    try:
        clinical_summary_text = ""
        booking_data = {}

        # 1. Fetch Clinical Context & Context Data
        if payload.department == "radiation":
            summary_doc = await radiotherapy_records_collection.find_one(
                {"patient_id": payload.patient_id}, sort=[("generated_at", -1)]
            )
            if not summary_doc:
                summary_doc = await summary_collection.find_one(
                    {"patient_id": payload.patient_id}, sort=[("generated_at", -1)]
                )
            if summary_doc:
                clinical_summary_text = summary_doc.get("summary", "")
                if not clinical_summary_text and "clinical_summary" in summary_doc:
                    clinical_summary_text = str(summary_doc["clinical_summary"])
        elif payload.department == "surgical":
            from .surgical_oncology import format_patient_summary_text
            summary_doc = await database["patient_summary"].find_one(
                {"patient_id": payload.patient_id}, sort=[("updated_at", -1)]
            )
            clinical_summary_text = format_patient_summary_text(summary_doc)
            if payload.booking_id:
                booking_doc = await database["surgical_oncology"].find_one({"booking_id": payload.booking_id})
                if booking_doc:
                    booking_data = booking_doc.get("booking", {})
        elif payload.department == "anaesthesia":
            from .surgical_oncology import format_patient_summary_text
            summary_doc = await database["patient_summary"].find_one(
                {"patient_id": payload.patient_id}, sort=[("updated_at", -1)]
            )
            clinical_summary_text = format_patient_summary_text(summary_doc)
            anaes_doc = await database["anaesthesia_records"].find_one({
                "$or": [
                    {"record_id": payload.booking_id},
                    {"linked_booking_id": payload.booking_id},
                    {"patient_id": payload.patient_id, "status": "active"}
                ]
            })
            if anaes_doc:
                booking_data = anaes_doc.get("pac", {})
                
                linked_booking_id = anaes_doc.get("linked_booking_id")
                if linked_booking_id and str(linked_booking_id).lower() not in ["null", "none"]:
                    surgical_doc = await database["surgical_oncology"].find_one({"booking_id": linked_booking_id})
                    if surgical_doc and "booking" in surgical_doc:
                        surgical_booking = surgical_doc["booking"]
                        if surgical_booking.get("procedureName") or surgical_booking.get("procedure_name"):
                            booking_data["Linked Surgery Name"] = surgical_booking.get("procedureName") or surgical_booking.get("procedure_name")
                        if surgical_booking.get("surgeryDate") or surgical_booking.get("surgery_date"):
                            booking_data["Linked Surgery Date"] = surgical_booking.get("surgeryDate") or surgical_booking.get("surgery_date")
                        if surgical_booking.get("treatingDoctor") or surgical_booking.get("treating_doctor"):
                            booking_data["Linked Surgeon"] = surgical_booking.get("treatingDoctor") or surgical_booking.get("treating_doctor")
        else:
            docs = await summary_collection.find(
                {"patient_id": payload.patient_id}
            ).sort("generated_at", -1).limit(1).to_list(1)
            if docs:
                paragraphs = docs[0].get("summary", {}).get("paragraphs", [])
                if paragraphs:
                    clinical_summary_text = "\n".join([p if isinstance(p, str) else p.get("text", "") for p in paragraphs])


        # 2. Dynamic Prompting
        prompt_context = ""
        import json
        if payload.department == "surgical":
            prompt_context = f"suggest the necessary pre-induction lab and radiology investigations.\n\nSurgery Booking Details:\n{json.dumps(booking_data, indent=2)}"
        elif payload.department == "anaesthesia":
            prompt_context = f"suggest the necessary pre-anaesthesia lab and radiology investigations for the upcoming procedure.\n\nPre-Anaesthesia Record Details:\n{json.dumps(booking_data, indent=2)}"
        elif payload.department == "medical":
            prompt_context = "suggest the necessary pre-induction lab and radiology investigations for their upcoming chemotherapy."
        elif payload.department == "radiation":
            prompt_context = "suggest the rationale for lab investigations (clinical indication) and recommend which specific lab and radiology tests should be ordered from the provided lists for their radiotherapy."
        else:
            prompt_context = f"suggest the necessary lab and radiology investigations for their upcoming {payload.department} treatment."

        lab_fields = [
            "Blood Group and RH Type", "CBC (Complete Blood Count)", "Haemoglobin (Hb)", "PCV / Haematocrit", "WBC Count",
            "Total Leucocyte Count (TLC)", "Platelets", "PT / INR", "aPTT",
            "Serum Creatinine", "Blood Urea", "Serum Na⁺", "Serum K⁺", "Total Bilirubin", "SGOT / AST",
            "SGPT / ALT", "Alkaline Phosphatase (ALP)", "Serum Albumin", "Random Blood Sugar", "FBS (Fasting Blood Sugar)", "PPBS (Post Prandial)", "HbA1c", "Serum Calcium", "Lipid Profile",
            "ECG Result", "Echo LVEF", "BNP", "TSH", "Free T3", "Free T4", "CRP", "Procalcitonin",
            "Arterial Blood Gas (ABG)", "HIV", "HBsAg", "HCV",
            "Sr. PSA", "CA 125", "CA 19.9", "CEA", "AFP",
            "PAP Smear", "HPV DNA", "Cytology (Brush/Fluid)", "FNAC", "Biopsy (Punch/Excision)"
        ]
        
        rad_fields = [
            "CT Scan (Computed Tomography)", "MRI (Magnetic Resonance Imaging)", 
            "PET Scan (Positron Emission Tomography)", "PET-CT", "X-Ray", "Ultrasound (USG)",
            "Mammography", "Bone Scan", "SPECT Scan", "Fluoroscopy", "Angiography",
            "2D Echo", "PFT (Pulmonary Function Test)", "Stress Test"
        ]

        prompt = f"""
You are an expert medical assistant. Based on the patient's clinical summary below, {prompt_context}

Patient Clinical Summary:
{clinical_summary_text or "No summary available."}

Available Lab Tests:
{json.dumps(lab_fields)}

Available Radiology Tests:
{json.dumps(rad_fields)}

Output ONLY a valid JSON object with the following keys:
- "isLabRequired": A boolean indicating if any lab tests are required.
- "labClinicalIndication": A string providing your brief reasoning for the selected lab tests. Explicitly explain WHY these specific tests are required. If isLabRequired is false, this can be empty.
- "labTests": An array of strings containing ONLY the exact names of the suggested lab tests from the Available Lab Tests list.
- "isRadRequired": A boolean indicating if any radiology tests are required.
- "radClinicalIndication": A string providing your brief reasoning for the selected radiology tests. Explicitly explain WHY these specific tests are required. If isRadRequired is false, this can be empty.
- "radTests": An array of strings containing ONLY the exact names of the suggested radiology tests from the Available Radiology Tests list.

Do not include markdown formatting like ```json.
        """

        groq_client = Groq(api_key=api_key)
        completion = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.1,
            response_format={"type": "json_object"},
            max_tokens=1500,
        )

        llm_output = json.loads(completion.choices[0].message.content)

        # 3. Data Persistence
        if payload.department == "surgical" and payload.booking_id:
            await database["surgical_oncology"].update_one(
                {"booking_id": payload.booking_id},
                {"$set": {
                    "doctors_note.investigationSuggestion": llm_output,
                    "updated_at": datetime.utcnow()
                }}
            )
        elif payload.department == "anaesthesia":
            await database["anaesthesia_records"].update_one(
                {"$or": [{"record_id": payload.booking_id}, {"linked_booking_id": payload.booking_id}, {"patient_id": payload.patient_id, "status": "active"}]},
                {"$set": {
                    "investigationSuggestion": llm_output,
                    "updated_at": datetime.utcnow()
                }}
            )
        elif payload.department == "medical":
            await chemotherapy_records_collection.update_one(
                {"patientId": payload.patient_id, "doctorId": payload.doctor_id, "hospitalId": payload.hospital_id},
                {"$set": {
                    "investigationSuggestion": llm_output,
                    "updatedAt": datetime.utcnow()
                }},
                upsert=True
            )
        elif payload.department == "radiation":
            await database["investigation_suggestions"].update_one(
                {"patient_id": payload.patient_id},
                {"$set": {"patient_id": payload.patient_id, "suggestion": llm_output, "updated_at": datetime.utcnow()}},
                upsert=True
            )
        else:
            await database["investigation_suggestions"].update_one(
                {"patient_id": payload.patient_id, "department": payload.department},
                {"$set": {"patient_id": payload.patient_id, "department": payload.department, "suggestion": llm_output, "updated_at": datetime.utcnow()}},
                upsert=True
            )

        return {"status": "success", "data": llm_output}

    except Exception as e:
        logger.error(f"Error generating unified investigation suggestion: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate investigation suggestion")


@router.post("/oncology-investigations/all-completed-documents")
async def get_all_completed_oncology_documents(payload: dict):
    try:
        patient_id = payload.get("patient_id")
        doctor_id = payload.get("doctor_id")

        if not patient_id:
            raise HTTPException(
                status_code=400,
                detail="patient_id is required"
            )

        # ---------------------------------------------
        # Get completed investigations across all doctors
        # ---------------------------------------------
        investigations_cursor = oncology_investigations_collection.find(
            {
                "patient_id": patient_id,
                "status": "completed"
            }
        ).sort("date_of_order", -1)

        investigations = await investigations_cursor.to_list(length=None)

        if not investigations:
            return {
                "status": "success",
                "message": "No completed investigations found",
                "data": []
            }

        response_data = []

        # ---------------------------------------------
        # Retrieve processed documents across all doctors
        # ---------------------------------------------
        for investigation in investigations:
            document_id = investigation.get("document_id")

            if not document_id:
                continue

            processed_document = processed_documents.find_one(
                {
                    "document_id": document_id,
                    "patient_id": patient_id
                }
            )

            if not processed_document:
                continue

            doc_entry = {
                "investigation": investigation.get("investigation"),
                "clinical_indication": investigation.get("clinical_indication"),
                "date_of_order": investigation.get("date_of_order"),
                "parameters": investigation.get("parameters"),
                "document_id": document_id,
                "doctor_id": investigation.get("doctor_id"),
                "raw_markdown": processed_document.get("raw_markdown"),
                "parameterwise_markdown": processed_document.get("parameterwise_markdown"),
                "sections": processed_document.get("sections"),
                "parameterwise_content": processed_document.get("parameterwise_content")
            }
            if "id" in investigation and investigation["id"] is not None:
                doc_entry["id"] = investigation["id"]

            response_data.append(doc_entry)

        return {
            "status": "success",
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "total_documents": len(response_data),
            "data": response_data
        }

    except HTTPException:
        raise

    except Exception as e:
        logger.exception("Failed retrieving all completed oncology documents")
        raise HTTPException(
            status_code=500,
            detail=str(e)
        )



# Radiotherapy dictation Retrieval by Rishy
@router.get("/radiotherapy-treatment-extraction/{patient_id}")
async def radiotherapy_treatment_extraction(patient_id: str):
    try:
        # 1. Fetch latest dictation
        logger.info(f"Retrieving radiotherapy dictation for patient: {patient_id}")
        cursor = dictation_collection.find({"patient_id": patient_id}).sort("created_at", -1).limit(1)
        latest_dictation = None
        async for doc in cursor:
            latest_dictation = doc
            break

        if not latest_dictation:
            logger.info("No dictation found.")
            return {"status": "success", "data": None, "message": "No dictation found"}

        latest_dictation_id = str(latest_dictation["_id"])
        logger.info(f"Latest dictation ID: {latest_dictation_id}")

        # 2. Fetch radiotherapy record
        record = await radiotherapy_records_collection.find_one({"patientId": patient_id}, sort=[("updatedAt", -1)])
        
        # 3. Check cache
        if record and record.get("last_dictation_id") == latest_dictation_id and "extracted_treatment" in record:
            logger.info("Cache hit: Returning extracted_treatment from radiotherapy_records")
            return {"status": "success", "data": record["extracted_treatment"]}

        # 4. Process dictation to extract raw text
        raw_text = ""
        for item in latest_dictation.get("raw_data", []):
            if isinstance(item, dict) and "content" in item:
                raw_text += str(item["content"]) + "\n"

        if not raw_text.strip():
            logger.info("Dictation found but contains no raw text.")
            return {"status": "success", "data": None, "message": "Dictation has no text"}

        # 5. Call LLM
        logger.info("Calling LLM to extract radiotherapy treatment details")
        api_key = os.getenv("GROQ_API_KEY")
        if not api_key:
            raise Exception("GROQ_API_KEY not configured.")
        
        local_groq_client = Groq(api_key=api_key)

        prompt = f"""
You are an expert medical assistant. Based on the following clinical dictation for a patient, extract the radiotherapy treatment details to prefill a form.

Fields to extract:
- "Treatment Intent": Must be EXACTLY one of ["Curative", "Adjuvant", "Neoadjuvant", "Definitive", "Palliative", "Salvage", "Prophylactic"]. Default to "" if not mentioned.
- "rtRole": A concise string describing the role of radiotherapy.
- "rtSetting": Must be EXACTLY one of ["Per Primum", "Re-Irradiation"]. Default to "Per Primum" if not mentioned.
- "rtType": Must be EXACTLY one of ["EBRT", "Brachytherapy", "Both"]. Default to "" if not mentioned.
- "consentTaken": Must be EXACTLY one of ["Yes", "No"]. Default to "" if not mentioned.
- "consentDate": A date string in "YYYY-MM-DD" format if mentioned, else "".

Clinical Dictation:
{raw_text}

Output ONLY a valid JSON object with EXACTLY the keys listed above. Do not invent details not mentioned in the text.
"""

        response = local_groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            response_format={"type": "json_object"},
            temperature=0.1,
            max_tokens=2000,
        )

        result_str = response.choices[0].message.content
        import json
        extracted_data = json.loads(result_str)
        logger.info(f"LLM extraction successful: {extracted_data}")

        # 6. Save to DB
        if record:
            await radiotherapy_records_collection.update_one(
                {"_id": record["_id"]},
                {"$set": {
                    "last_dictation_id": latest_dictation_id,
                    "extracted_treatment": extracted_data,
                    "updatedAt": datetime.utcnow()
                }}
            )
        else:
            await radiotherapy_records_collection.insert_one({
                "patientId": patient_id,
                "last_dictation_id": latest_dictation_id,
                "extracted_treatment": extracted_data,
                "createdAt": datetime.utcnow(),
                "updatedAt": datetime.utcnow()
            })

        logger.info("Successfully saved extracted radiotherapy treatment to DB.")
        return {"status": "success", "data": extracted_data}

    except Exception as e:
        logger.error(f"Error extracting radiotherapy treatment: {e}")
        raise HTTPException(status_code=500, detail="Failed to extract radiotherapy treatment data")

# Add this new collection
protocol_master_prefills_collection = database["protocol_master_prefills"]
# ═════════════════════════════════════════════════════════════════════════════
# PROTOCOL MASTER PREFILL ENDPOINT
# ═════════════════════════════════════════════════════════════════════════════

@router.get("/protocol-master/prefill/{patient_id}")
async def get_protocol_master_prefill(
    patient_id: str, 
    doctor_id: Optional[str] = None,
    department: Optional[str] = Query(None, description="Filter dictation by department"),
    encounter_type: Optional[str] = Query(None, description="Filter dictation by encounter type")
):
    """
    On-demand endpoint to fetch or extract protocol master prefill data using the latest dictation.
    """
    try:
        logger.info(f"Fetching protocol master prefill for patient: {patient_id}, doctor: {doctor_id}, department: {department}")
        
        # 1. Fetch latest dictation from 'dictation' collection
        query = {"patient_id": patient_id}
        if doctor_id:
            query["doctor_id"] = doctor_id
        if department:
            query["$or"] = query.get("$or", []) + [{"department": department}, {"department": None}, {"department": {"$exists": False}}]
        if encounter_type:
            query["$or"] = query.get("$or", []) + [{"encounter_type": encounter_type}, {"encounter_type": None}, {"encounter_type": {"$exists": False}}]
            
        latest_dictation = await dictation_collection.find_one(
            query,
            sort=[("created_at", -1)]
        )

        if not latest_dictation:
            logger.info(f"No dictation found for patient {patient_id}")
            return {"status": "success", "data": None, "message": "No dictation found"}
        
        dictation_id = str(latest_dictation["_id"])
        logger.info(f"Found latest dictation {dictation_id} for patient {patient_id}")

        # 2. Check if already processed
        existing_prefill = await protocol_master_prefills_collection.find_one(
            {"dictation_id": dictation_id}
        )

        if existing_prefill:
            logger.info(f"Returning cached prefill data for dictation {dictation_id}")
            # Return cached version
            existing_prefill["_id"] = str(existing_prefill["_id"])
            return {"status": "success", "data": existing_prefill["data"]}

        logger.info(f"No cached prefill found. Processing dictation {dictation_id} with LLM...")
        # 3. Process with LLM
        api_key = os.getenv("GROQ_API_KEY")
        if not api_key:
            raise HTTPException(status_code=500, detail="GROQ_API_KEY not configured on server")
        
        local_groq_client = Groq(api_key=api_key)

        transcript_text = "No transcript found"
        # Extract transcript based on voice_dictation schema
        if "conversation" in latest_dictation and latest_dictation["conversation"]:
            conversation = latest_dictation["conversation"]
            if isinstance(conversation, list) and len(conversation) > 0:
                transcript_text = conversation[0].get("text", "")
            elif isinstance(conversation, dict):
                transcript_text = conversation.get("text", "")
            elif isinstance(conversation, str):
                transcript_text = conversation
        elif "raw_data" in latest_dictation and latest_dictation["raw_data"]:
            raw_data = latest_dictation["raw_data"]
            if isinstance(raw_data, list) and len(raw_data) > 0:
                transcript_text = raw_data[0].get("content", "")

        if not transcript_text or transcript_text == "No transcript found":
            return {"status": "success", "data": None, "message": "No transcript text to process"}

        prompt = f"""
You are an expert medical assistant. Extract the following fields from the given clinical dictation for prefilling the Protocol Master.
Ensure keys match exactly as requested, and format as a valid JSON object. Do not include markdown formatting like ```json.

Fields to extract:
- "intent": Intent of Treatment (e.g. Curative, Palliative, Neo-adjuvant, Adjuvant)
- "chemoType": Type of Chemotherapy (Allowed values: "cytotoxic", "targeted", "immunotherapy", "hormonal", "chemo-immuno", "chemo-targeted", "other" - or empty string if not applicable)
- "protocolName": Protocol Name
- "startDate": Start Date of Protocol (MUST be strictly in YYYY-MM-DD format. If not possible, return an empty string)
- "cycles": Number of Cycles (integer as string, e.g. "6")
- "daysBetween": Days Between Cycles (integer as string, e.g. "21")
- "protocolDetails": Protocol Details (Drug combination, route, schedule, cycles)
- "doseAdjustments": Dose Adjustments (for organ function, comorbidities, etc.)
- "concurrentTherapy": Concurrent Therapy Plans (Radiation, surgery, etc.)
- "reasonForChange": Reason for Regimen Change If switching from a prior plan (Allowed values: "progression", "poor-response", "toxicity", "comorbidity", "lab-parameters", "drug-unavailability", "cost-access", "patient-choice", "physician-preference", "protocol-update", "other" - or empty string if not applicable)
- "protocolMasterRef": Protocol Master Reference (Institutional formulary link or ID)

Clinical Dictation:
"{transcript_text}"
"""

        response = local_groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            response_format={"type": "json_object"},
            temperature=0.1,
            max_tokens=2000,
        )

        result_str = response.choices[0].message.content
        logger.info(f"LLM successfully extracted data for {dictation_id}")
        extracted_data = json.loads(result_str)

        # Ensure values are strings for frontend consistency
        for k in extracted_data:
            if extracted_data[k] is None:
                extracted_data[k] = ""
            else:
                extracted_data[k] = str(extracted_data[k])
                
        # Force chemoType to lowercase to match exact frontend dropdown values
        if "chemoType" in extracted_data and extracted_data["chemoType"]:
            extracted_data["chemoType"] = extracted_data["chemoType"].lower().strip()

        # 4. Save to collection
        prefill_doc = {
            "patient_id": patient_id,
            "dictation_id": dictation_id,
            "data": extracted_data,
            "timestamp": datetime.utcnow()
        }
        await protocol_master_prefills_collection.insert_one(prefill_doc)
        logger.info(f"Saved new prefill data for patient {patient_id}")

        return {"status": "success", "data": extracted_data}

    except Exception as e:
        logger.error(f"Error extracting protocol master prefill for patient {patient_id}: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail="Failed to extract prefill data")
        
        
       
