@router.get("/get-patient-radiotherapy-summary-oprecord")
async def get_patient_radiotherapy_summary_oprecord(patientId: str):
    try:
        if not patientId:
            raise HTTPException(status_code=400, detail="Missing required parameters")
            
        record = await radiotherapy_records_collection.find_one(
            {"patientId": patientId, "status": "active"},
            {"_id": 0},
            sort=[("updatedAt", -1)]
        )
        
        if record and "data" in record:
            data = record["data"]
            intent = data.get("intent", {})
            treatment = data.get("treatment", {})
            setup = data.get("setup", {})
            
            import re
            radiotherapy_record = {}
            
            def add_to_record(source_dict):
                if not isinstance(source_dict, dict):
                    return
                for k, v in source_dict.items():
                    if isinstance(v, (str, int, float, bool)) and v != "" and k not in ["patientId", "doctorId", "status", "id", "_id"]:
                        title_key = re.sub(r"([A-Z])", r" \1", k).title().strip()
                        radiotherapy_record[title_key] = v

            add_to_record(data)
            add_to_record(intent)
            add_to_record(setup)
            add_to_record(treatment)
            
            radiotherapy_record = {k: v for k, v in radiotherapy_record.items() if v != "" and v != [] and v is not None}
            
            result_data = {}
            if radiotherapy_record:
                result_data["Radiotherapy Record"] = radiotherapy_record

            treatment_sessions = treatment.get("sessions", [])
            if not treatment_sessions and "sessions" in data:
                treatment_sessions = data["sessions"]
            if not treatment_sessions and "treatment_sessions" in data:
                treatment_sessions = data["treatment_sessions"]

            if isinstance(treatment_sessions, list) and len(treatment_sessions) > 0:
                result_data["Treatment Sessions"] = treatment_sessions
                
            imaging_shifts = treatment.get("imagingShifts", [])
            if not imaging_shifts and "imagingShifts" in data:
                imaging_shifts = data["imagingShifts"]
            if not imaging_shifts and "imaging_shifts" in data:
                imaging_shifts = data["imaging_shifts"]
                
            if isinstance(imaging_shifts, list) and len(imaging_shifts) > 0:
                result_data["Imaging Shifts"] = imaging_shifts

            return {"status": "success", "data": result_data}
        
        return {"status": "success", "data": {}}
    except Exception as e:
        logger.error(f"Failed to get patient radiotherapy summary for oprecord: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")


