# ================= NURSE REFERRAL LETTER =================
# This section handles referral letters created from the Nurse's Notes tab.
# A nurse can refer a patient who wishes to take chemotherapy from an
# outside hospital. The referral letter captures both doctor details
# (from-doctor and to-doctor), hospital info, patient info, and the
# reason for referral.

class ReferralLetterRequest(BaseModel):
    """Schema for a nurse-initiated referral letter."""
    patient_id: str
    patient_name: Optional[str] = None
    doctor_id: str                              # The referring doctor's ID
    hospital_id: Optional[str] = None           # Hospital where the referral originates
    from_doctor_name: Optional[str] = None      # Name of the referring doctor
    from_doctor_speciality: Optional[str] = None
    to_doctor_name: Optional[str] = None        # Name of the doctor being referred to
    to_doctor_hospital: Optional[str] = None    # Outside hospital name
    to_doctor_speciality: Optional[str] = None
    reason_for_referral: Optional[str] = None   # Why the patient is being referred
    additional_notes: Optional[str] = None      # Any extra clinical context
    referred_by_nurse: Optional[str] = None     # Nurse who initiated the referral
    nurse_signed: bool = False                  # Whether the nurse signed the referral
    from_doctor_id: Optional[str] = None
    to_doctor_id: Optional[str] = None
    reason: Optional[str] = None
    date: Optional[str] = None


@router.post("/nurse_note/referral/create")
async def create_nurse_referral_letter(payload: ReferralLetterRequest):
    """
    Create a referral letter from the Nurse's Notes tab.
    Saves the letter to the nurse_referral_letters collection.
    """
    try:
        if not payload.patient_id.strip():
            raise HTTPException(status_code=400, detail="patient_id is required.")
        if not payload.doctor_id.strip():
            raise HTTPException(status_code=400, detail="doctor_id is required.")
        if not payload.reason_for_referral or not payload.reason_for_referral.strip():
            raise HTTPException(status_code=400, detail="reason_for_referral is required.")

        # Build the document to store
        referral_doc = payload.dict()
        referral_doc["referral_id"] = str(uuid.uuid4())
        referral_doc["status"] = "pending"              # pending / completed / cancelled
        referral_doc["created_at"] = datetime.utcnow().isoformat()
        referral_doc["updated_at"] = datetime.utcnow().isoformat()

        # Ensure mandatory fields are present in the database document
        referral_doc["from_doctor_id"] = payload.from_doctor_id or payload.doctor_id
        
        to_doctor_id = payload.to_doctor_id or ""
        if not to_doctor_id and payload.to_doctor_name:
            to_doc = doctor_user_collection.find_one({"name": payload.to_doctor_name})
            if to_doc:
                to_doctor_id = str(to_doc.get("sys_user_id", to_doc.get("_id", "")))
        referral_doc["to_doctor_id"] = to_doctor_id
        
        referral_doc["from_doctor_name"] = payload.from_doctor_name or ""
        referral_doc["to_doctor_name"] = payload.to_doctor_name or ""
        referral_doc["patient_id"] = payload.patient_id or ""
        referral_doc["reason"] = payload.reason or payload.reason_for_referral or ""
        referral_doc["date"] = payload.date or referral_doc["created_at"]

        result = await nurse_referral_letters_collection.insert_one(referral_doc)

        if result.inserted_id:
            return {
                "status": "success",
                "message": "Referral letter created successfully.",
                "referral_id": referral_doc["referral_id"],
                "patient_id": payload.patient_id,
                "doctor_id": payload.doctor_id
            }

        raise HTTPException(status_code=500, detail="Failed to create referral letter.")

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Error creating nurse referral letter: {e}")
        raise HTTPException(status_code=500, detail="Internal server error")


@router.get("/nurse_note/referral/{patient_id}/{doctor_id}")
async def get_nurse_referral_letters(patient_id: str, doctor_id: str):
    """
    Retrieve all referral letters for a specific patient + doctor.
    Returns them sorted newest-first.
    """
    try:
        if not patient_id.strip():
            raise HTTPException(status_code=400, detail="patient_id is required.")
        if not doctor_id.strip():
            raise HTTPException(status_code=400, detail="doctor_id is required.")

        cursor = nurse_referral_letters_collection.find(
            {"patient_id": patient_id, "doctor_id": doctor_id}
        ).sort("created_at", -1)

        referrals = []
        async for doc in cursor:
            doc["_id"] = str(doc["_id"])  # Convert ObjectId to string
            referrals.append(doc)

        return {
            "status": "success",
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "referrals": referrals,
            "count": len(referrals)
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Error retrieving nurse referral letters: {e}")
        raise HTTPException(status_code=500, detail="Internal server error")

        
