# ═════════════════════════════════════════════════════════════════════════════
# DRUG SAFETY CHECKER (ALLERGIES & TOXICITY)
# ═════════════════════════════════════════════════════════════════════════════

class DrugSafetyRequest(BaseModel):
    prescribed_drugs: List[str]
    allergies: str
    toxicities: str

@router.post("/check-drug-safety")
async def check_drug_safety(request: DrugSafetyRequest):
    try:
        if not request.prescribed_drugs:
            return {"status": "success", "data": {"is_safe": True, "warnings": [], "alternative_suggestions": ""}}

        import os
        from groq import Groq
        import json

        api_key = os.getenv("GROQ_API_KEY")
        if not api_key:
            raise Exception("GROQ_API_KEY not configured.")
        
        local_groq_client = Groq(api_key=api_key)
        
        prompt = f'''
You are an expert medical oncology AI assistant ensuring drug safety.
A doctor is prescribing the following drug: {request.prescribed_drugs[0] if len(request.prescribed_drugs) > 0 else ""}

Patient's Known Allergies:
{request.allergies if request.allergies else 'None documented'}

Patient's Previous Severe Toxicities / Side Effects:
{request.toxicities if request.toxicities else 'None documented'}

Task: 
1. Allergy/Toxicity Check: Compare the prescribed drug against the known allergies/toxicities. 
   - CRITICAL: ONLY flag an allergy if there is an EXACT NAME MATCH or an absolute contraindication. 
   - Do NOT flag acceptable alternatives (e.g., if allergic to Paclitaxel, prescribing Docetaxel is SAFE. Do not flag cross-reactivity).

If ANY severe allergy or toxicity is found:
- set "is_safe": false
- provide specific, brief clinical warnings
- suggest alternative regimens or drugs if applicable

If it is safe (no exact allergy match):
- set "is_safe": true

Return a JSON object strictly matching this schema:
{{
    "is_safe": true or false,
    "warnings": ["warning 1", "warning 2"],
    "alternative_suggestions": "Suggest alternatives here, or empty string if safe",
    "alternative_drug_names": ["Alternative1", "Alternative2"]
}}
'''
        response = local_groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            response_format={"type": "json_object"},
            temperature=0.0,
            max_tokens=1000,
        )

        result_str = response.choices[0].message.content
        logger.info(f"Drug safety check LLM result: {result_str}")
        extracted_data = json.loads(result_str)
        
        # HARDCODED SAFEGUARD TO PREVENT LLM LOOPS & FALSE NEGATIVES
        if request.allergies:
            allergy_drug_name = request.allergies.split("-")[0].strip().lower()
            
            is_direct_match = False
            for pd in request.prescribed_drugs:
                if pd.strip().lower() == allergy_drug_name:
                    is_direct_match = True
                    break
                    
            if not extracted_data.get("is_safe") and not is_direct_match:
                logger.info(f"Safeguard triggered: Overriding LLM hallucination for non-matching drug. Allergy: {allergy_drug_name}, Prescribed: {request.prescribed_drugs}")
                extracted_data["is_safe"] = True
                extracted_data["warnings"] = []
                extracted_data["alternative_suggestions"] = ""
                extracted_data["alternative_drug_names"] = []
            elif extracted_data.get("is_safe") and is_direct_match:
                logger.info(f"Safeguard triggered: LLM missed direct allergy match. Forcing unsafe. Prescribed: {request.prescribed_drugs}")
                extracted_data["is_safe"] = False
                extracted_data["warnings"] = [f"CRITICAL: Patient has a known severe allergy to {allergy_drug_name.title()}."]
                extracted_data["alternative_suggestions"] = "Consider an alternative drug."
                extracted_data["alternative_drug_names"] = []

        return {"status": "success", "data": extracted_data}
    except Exception as e:
        logger.error(f"Error in /check-drug-safety: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail="Failed to check drug safety")

@router.post("/check-drug-interactions")
async def check_drug_interactions(request: DrugSafetyRequest):
    try:
        if not request.prescribed_drugs or len(request.prescribed_drugs) < 2:
            return {"status": "success", "data": {"is_safe": True, "warnings": [], "alternative_suggestions": "", "warning_type": "none", "alternative_drug_names": []}}

        import os
        from groq import Groq
        import json

        api_key = os.getenv("GROQ_API_KEY")
        if not api_key:
            raise Exception("GROQ_API_KEY not configured.")

        logger.info(request.prescribed_drugs)
        logger.info(request.allergies)

        local_groq_client = Groq(api_key=api_key)

        # ── FIX 1: Truncate potentially long free-text fields before prompt injection ──
        MAX_FIELD_LEN = 300
        allergies_text = (request.allergies or "None documented")[:MAX_FIELD_LEN]
        toxicities_text = (request.toxicities or "None documented")[:MAX_FIELD_LEN]
        drugs_list = ", ".join(request.prescribed_drugs)

        prompt = f"""You are a medical oncology AI ensuring drug safety. Be concise.

Prescribed drugs: {drugs_list}
Known allergies: {allergies_text}
Previous severe toxicities: {toxicities_text}

Rules:
1. Drug-Drug Interactions: Flag only absolute contraindications between the prescribed drugs. Do NOT flag expected additive chemotherapy toxicities (neutropenia, nausea, bone marrow suppression, etc.).
2. Allergy/Toxicity Check: Flag ONLY exact name matches or absolute contraindications. Do NOT flag cross-reactivity or mention acceptable alternatives as unsafe.
3. Cardiac Safety Check: Assess the prescribed drug combination for cardiotoxic risk.
   - Flag if any drug is a known cardiotoxin (e.g., anthracyclines: Doxorubicin, Epirubicin; HER2 agents: Trastuzumab, Pertuzumab; TKIs: Sunitinib, Sorafenib; alkylating agents: Cyclophosphamide at high doses).
   - Flag cumulative/additive cardiac risk when MULTIPLE cardiotoxic drugs are prescribed together (e.g., Doxorubicin + Trastuzumab significantly increases cardiomyopathy risk beyond either alone).
   - Flag if the patient's toxicity history documents prior cardiac events (cardiomyopathy, reduced LVEF, heart failure, arrhythmia, QT prolongation) AND any prescribed drug carries cardiac risk.
   - Specify the cardiac risk type: cardiomyopathy, QT prolongation, hypertension, arrhythmia, or ischemia.
   - Do NOT flag drugs with no established cardiotoxicity. Do NOT flag mild or theoretical risks.

If ANY issue is found:
- set "is_safe": false
- set "warning_type" to "allergy", "interaction", "cardiac", or a combination like "interaction|cardiac"
- set "cardiac_warning" to a brief clinical description of the cardiac risk, or empty string if none
- provide specific, brief clinical warnings
- suggest alternatives if applicable

If everything is safe:
- set "is_safe": true
- set "warning_type": "none"
- set "cardiac_warning": ""

Return ONLY this JSON, no other text:
{{
    "is_safe": true or false,
    "warning_type": "allergy" | "interaction" | "cardiac" | "allergy|cardiac" | "interaction|cardiac" | "both" | "both|cardiac" | "none",
    "cardiac_warning": "brief cardiac risk or empty string",
    "warnings": ["brief warning"],
    "alternative_suggestions": "brief alternatives or empty string",
    "alternative_drug_names": ["Drug1"]
}}"""

        # ── FIX 2: Raise max_tokens so JSON mode can always complete the document ──
        try:
            response = local_groq_client.chat.completions.create(
                model="llama-3.1-8b-instant",
                messages=[{"role": "user", "content": prompt}],
                response_format={"type": "json_object"},
                temperature=0.0,
                max_tokens=2048,  # was 1000 — the root cause of the 400
            )
            result_str = response.choices[0].message.content
            logger.info(f"Drug interactions check LLM result: {result_str}")
            extracted_data = json.loads(result_str)

        # ── FIX 3: Fallback so a Groq failure never returns a 500 to the user ──
        except Exception as llm_err:
            logger.error(f"LLM call failed in /check-drug-interactions: {llm_err}")
            extracted_data = {
                "is_safe": True,
                "warning_type": "none",
                "warnings": [],
                "alternative_suggestions": "",
                "alternative_drug_names": [],
            }

        # ── Safeguard logic unchanged below ──
        if request.allergies:
            allergy_drug_name = request.allergies.split("-")[0].strip().lower()

            is_direct_match = any(
                pd.strip().lower() == allergy_drug_name
                for pd in request.prescribed_drugs
            )

            if not extracted_data.get("is_safe") and not is_direct_match:
                warning_type = extracted_data.get("warning_type", "")
                if warning_type == "allergy":
                    logger.info(f"Safeguard: Overriding hallucinated allergy. Prescribed: {request.prescribed_drugs}")
                    extracted_data.update({"is_safe": True, "warnings": [], "alternative_suggestions": "", "alternative_drug_names": []})
                elif warning_type in ("both", "interaction"):
                    filtered_warnings = [
                        w for w in extracted_data.get("warnings", [])
                        if "allergy" not in w.lower()
                        and "cross-reactivity" not in w.lower()
                        and allergy_drug_name not in w.lower()
                    ]
                    extracted_data["warnings"] = filtered_warnings
                    if not filtered_warnings:
                        extracted_data.update({"is_safe": True, "alternative_suggestions": "", "alternative_drug_names": []})
                    else:
                        logger.info("Safeguard: Removed hallucinated allergy warnings, kept valid interactions.")

            elif extracted_data.get("is_safe") and is_direct_match:
                logger.info(f"Safeguard: LLM missed direct allergy. Forcing unsafe. Prescribed: {request.prescribed_drugs}")
                extracted_data.update({
                    "is_safe": False,
                    "warning_type": "allergy",
                    "warnings": [f"CRITICAL: Patient has a known severe allergy to {allergy_drug_name.title()}."],
                    "alternative_suggestions": "Consider an alternative drug.",
                    "alternative_drug_names": [],
                })

        return {"status": "success", "data": extracted_data}

    except Exception as e:
        logger.error(f"Error in /check-drug-interactions: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail="Failed to check drug interactions")
    
    
    
    
    
