@router.post("/generate-chemo-toxicity-summary")
async def generate_chemo_toxicity_summary(request: Request):
    """
    Generates a natural language narrative summary of the toxicities during chemotherapy
    based on the toxicities data stored in each cycle's post_chemo section.
    Used by OPRecord Part E (Discharge Summary) — Requirement 8.2.
    """
    try:
        payload = await request.json()
        patient_id = payload.get("patientId", "")

        if not patient_id:
            raise HTTPException(status_code=400, detail="patientId is required")

        # Find the most recent chemotherapy record for this patient
        doc = await chemotherapy_records_collection.find_one(
            {"patientId": patient_id},
            sort=[("updatedAt", -1)]
        )

        if not doc:
            return {"status": "success", "summary": "No chemotherapy record found for this patient."}

        # Collect toxicities from all cycles
        cycles_data = doc.get("data", {}).get("cycles", {})
        all_toxicities = []

        for cycle_key, cycle_obj in cycles_data.items():
            post_chemo = cycle_obj.get("post_chemo", {})
            toxicities = post_chemo.get("toxicities", [])

            for tox in toxicities:
                # Only include entries that have meaningful data
                if tox.get("event") or tox.get("description") or tox.get("system"):
                    all_toxicities.append({
                        "cycle": cycle_key,
                        "event": tox.get("event", ""),
                        "description": tox.get("description", ""),
                        "grade": tox.get("grade", ""),
                        "system": tox.get("system", ""),
                        "attribution": tox.get("attribution", ""),
                        "onset": tox.get("onset", ""),
                        "managementPlace": tox.get("managementPlace", ""),
                        "gradingSystem": tox.get("gradingSystem", ""),
                    })

            # Also check for legacy adverseEvents string
            if not toxicities and post_chemo.get("adverseEvents"):
                all_toxicities.append({
                    "cycle": cycle_key,
                    "event": post_chemo["adverseEvents"],
                    "description": "",
                    "grade": "",
                    "system": "",
                    "attribution": "",
                    "onset": "",
                    "managementPlace": "",
                    "gradingSystem": "",
                })

        prompt = f"""
        You are an expert clinical oncology assistant. Given the following structured toxicities data collected across all chemotherapy cycles, generate a single, cohesive, well-written narrative summary paragraph that can be used in a patient's discharge summary.

        Toxicities Data:
        {json.dumps(all_toxicities, indent=2)}

        If there are no toxicities, state that no significant toxicities were noted during the course of chemotherapy.
        Keep the tone professional, objective, and clinical.
        Mention the cycle numbers, grading system used, specific adverse events, their grades, and management where available.
        Return ONLY a valid JSON object with a single key "summary" containing the text. Do not include markdown formatting like ```json.
        """

        completion = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
            response_format={"type": "json_object"},
            max_tokens=500,
        )

        llm_output = json.loads(completion.choices[0].message.content)
        final_summary = llm_output.get("summary", "")

        return {"status": "success", "summary": final_summary}

    except Exception as e:
        logger.error(f"Error generating chemo toxicity summary: {e}")
        raise HTTPException(status_code=500, detail=str(e))

#Chemo redflags by rishy
@router.get("/get-chemo-suspension-details/{patient_id}")
async def get_chemo_suspension_details(patient_id: str):
    try:
        # Find the latest chemo record for this patient
        dbRecord = await chemotherapy_records_collection.find_one(
            {"patientId": patient_id},
            sort=[("_id", -1)]
        )
        
        if not dbRecord:
            return {"status": "success", "data": {"suspendedCycles": [], "incompleteTreatmentDetails": None}}
            
        suspended_cycles = []
        cycles = dbRecord.get("data", {}).get("cycles", {})
        
        for cycle_num, cycle_data in cycles.items():
            # Check if postponed during post-chemo
            post_chemo = cycle_data.get("post_chemo", {})
            regimen = cycle_data.get("regimen", {})
            cycle_admin = cycle_data.get("cycle_admin", {})
            
            if post_chemo.get("postponeTreatment") == "yes":
                suspended_cycles.append({
                    "cycle": cycle_num,
                    "status": "Postponed (Post Chemo)",
                    "reason": post_chemo.get("postponeReason", ""),
                    "fromDate": post_chemo.get("postponeFromDate", ""),
                    "untilDate": post_chemo.get("postponeUntilDate", "")
                })
            # Check if postponed/suspended during doctor's regimen review
            elif regimen.get("postponeFromDate") or (regimen.get("treatmentDecision") and regimen.get("treatmentDecision") != "continue"):
                doc_reasons = regimen.get("docReasons", {})
                reasons_list = [k for k, v in doc_reasons.items() if v]
                reason_str = ", ".join(reasons_list) if reasons_list else regimen.get("treatmentDecision", "")
                
                suspended_cycles.append({
                    "cycle": cycle_num,
                    "status": "Suspended/Postponed (Regimen Review)",
                    "reason": reason_str,
                    "fromDate": regimen.get("postponeFromDate", ""),
                    "untilDate": regimen.get("postponeUntilDate", "")
                })
            # Check if administration was started but failed to complete
            elif cycle_admin.get("cycleCompleted") == "no" or cycle_admin.get("notCompletedReason"):
                suspended_cycles.append({
                    "cycle": cycle_num,
                    "status": "Incomplete Administration",
                    "reason": cycle_admin.get("notCompletedReason", ""),
                    "date": cycle_admin.get("cycleDate1", "")
                })
                
        treatment = dbRecord.get("treatment", {})
        completion = dbRecord.get("data", {}).get("completion", {})
        
        planned_cycles = treatment.get("plannedCycles", 0)
        completed_cycles = treatment.get("completedCycles", 0)
        
        is_early_termination = (
            completion.get("treatmentCompletionStatus") == "incomplete" or
            (completion.get("treatmentNotCompletedReason") and completion.get("treatmentNotCompletedReason") != "") or
            (treatment.get("treatmentCompleted") is True and completed_cycles < planned_cycles)
        )
        
        incomplete_treatment_details = None
        if is_early_termination:
            incomplete_treatment_details = {
                "plannedCycles": planned_cycles,
                "completedCycles": completed_cycles,
                "reason": completion.get("treatmentNotCompletedReason", ""),
                "notes": completion.get("treatmentNotCompletedNotes", "")
            }
            
        return {
            "status": "success",
            "data": {
                "suspendedCycles": suspended_cycles,
                "incompleteTreatmentDetails": incomplete_treatment_details
            }
        }
    except Exception as e:
        logger.error(f"Error fetching chemo suspension details for {patient_id}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))


