class RadiotherapyEbrtBrachyStructurePayload(BaseModel):
    text: str
    module_type: str

@router.post("/radiotherapy-ebrt-brachy-structure")
async def structure_radiotherapy_ebrt_brachy(payload: RadiotherapyEbrtBrachyStructurePayload):
    """
    Structure transcribed dictation text into JSON format for the EBRT and Brachytherapy modules in RadiotherapyRecord using Groq LLM.
    """
    api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        raise HTTPException(
            status_code=500, detail="GROQ_API_KEY not configured on server"
        )

    try:
        groq_client = Groq(api_key=api_key)
        
        if payload.module_type == "ebrt":
            prompt = f"""
You are an expert medical assistant. Extract the following radiotherapy EBRT module data from the given dictation text and output it as a valid JSON object. Do not invent details not mentioned in the text.

Fields to extract and format into the following nested JSON structure (ensure keys match exactly and output ONLY JSON):
{{
  "simulationSets": [
    {{
      "intentPrimary": "Boolean (true/false)",
      "intentAdaptive": "Boolean (true/false)",
      "intentReplanning": "Boolean (true/false)",
      "intentSecondary": "Boolean (true/false)",
      "immobilisation": "String",
      "imaging": "String (CT, CT / MRI, CT / PET, X-Ray, Clinical)",
      "patientPos": "String (Supine, Prone, Lateral, Others)",
      "specialTech": "String (SRS, SRT, DIBH, DEBH, Gating, Tracking, Fiducials)",
      "totalDose": "String (Extract numeric value only, e.g. 6000)",
      "totalFractions": "String (Extract numeric value only, e.g. 30)",
      "fracSched": "String (Alternate Day, Daily, Once Weekly, Others)",
      "fracSchedOther": "String",
      "sibBoost": "String (Yes or No)",
      "dosePerFrac": "String",
      "machine": "String",
      "startDate": "String (YYYY-MM-DD)",
      "endDate": "String (YYYY-MM-DD)",
      "peerReview": "String (Yes or No)",
      "peerComments": "String"
    }}
  ],
  "procedure": {{
    "machine": "String (Cobalt, LA, CyberKnife, MRI LINAC, Proton)",
    "systemicTherapy": "String (Chemotherapy, Targeted Therapy, Immunotherapy, Combination)",
    "combinationSpecify": "String",
    "technique": "String (Single Portal, 2 Dimensional, 3DCRT, IMRT, VMAT)",
    "doseConstraints": "String (Yes or No)",
    "doseConstraintsComment": "String",
    "energy": {{
      "photon": "Boolean (true/false)",
      "photonMV": "String",
      "electron": "Boolean (true/false)",
      "electronMeV": "String",
      "proton": "Boolean (true/false)",
      "protonMeV": "String"
    }}
  }},
  "planning": {{
    "verification": "String (Yes or No)",
    "verificationType": "String (CBCT, EPID)",
    "verificationFrequency": "String (Daily, Once Weekly, Thrice Weekly)",
    "adaptiveRadiation": "String (Yes or No)",
    "adaptiveReason": "String (Tumor Related, Patient Related, Treatment Related)"
  }},
  "interruption": {{
    "continueTreatment": "String (Continue with the same treatment, Suspend the treatment, Stop the treatment)",
    "interruptReason": "String",
    "interruptedDate": "String (YYYY-MM-DD)",
    "resumeDate": "String (YYYY-MM-DD)",
    "completionDate": "String (YYYY-MM-DD)"
  }},
  "completion": {{
    "rtCompletion": "String (Planned or Unplanned)",
    "rtCompletionJustification": "String",
    "responseCriteria": "String (WHO, RECIST)",
    "clinResponse": "String (CR, PR, SD, PD)",
    "weightStart": "String",
    "weightCompletion": "String",
    "overallTreatmentTime": "String",
    "txGap": "String (Yes or No)",
    "gapFrom": "String (YYYY-MM-DD)",
    "gapTo": "String (YYYY-MM-DD)",
    "gapReason": "String",
    "gapCorrection": "String",
    "gapCorrectionDetails": "String",
    "interruptionDetails": "String"
  }},
  "adverseEvents": [
    {{
      "date": "String (YYYY-MM-DD)",
      "event": "String",
      "gradingSystem": "String (CTCAE 5 or RTOG)",
      "grade": "String (Grade 1, Grade 2, Grade 3, Grade 4, Grade 5)",
      "management": "String"
    }}
  ],
  "followUp": {{
    "date": "String (YYYY-MM-DD)",
    "time": "String (HH:mm in 24-hour format)",
    "imagingAdvised": "String (CT, MRI, PET-CT, USG, X-Ray, Other)",
    "imagingAdvisedOther": "String",
    "postCompletionPlan": "String",
    "adviceOnCompletion": "String"
  }}
}}

Text to analyze:
{payload.text}
"""
        elif payload.module_type == "brachy":
            prompt = f"""
You are an expert medical assistant. Extract the following radiotherapy Brachytherapy module data from the given dictation text and output it as a valid JSON object. Do not invent details not mentioned in the text.

Fields to extract and format into the following nested JSON structure (ensure keys match exactly and output ONLY JSON):
{{
  "treatment": {{
    "clinicalAssessment": "String",
    "planOfTreatment": "String"
  }},
  "prevEBRT": {{
    "intent": "String",
    "totalDose": "String (Extract numeric value only, e.g. 6000)",
    "totalFractions": "String (Extract numeric value only, e.g. 30)",
    "fracSched": "String",
    "fracSchedOther": "String",
    "dosePerFrac": "String",
    "oar1": "String",
    "oar2": "String",
    "oar3": "String",
    "oar4": "String"
  }},
  "procedure": {{
    "dateOfProcedure": "String (YYYY-MM-DD)",
    "anaesthesiaType": "String (General Anaesthesia (GA), Spinal Anaesthesia (SA), Epidural, Local Anaesthesia (LA), Sedation, None, Other)",
    "anaesthesiaTypeOther": "String",
    "implantUsed": "String (Tandem & Ovoid, Tandem & Ring, Vaginal Cylinder (30 mm), Utrecht Applicator with Interstitial Needles, Venezia Applicator, Syed-Neblett Template, MUPIT, Transperineal Template Grid, Multi-catheter Implant, SAVI Applicator, Freiburg Flap, Leipzig Applicator, COMS Plaque, Other)",
    "implantUsedOther": "String",
    "euaFindings": "String",
    "tubesNeedles": "String (Extract numeric value only)",
    "planes": "String (Extract numeric value only)",
    "remarks": "String"
  }},
  "imaging": {{
    "technique": "String (CT, MRI, PET-CT, USG, X-Ray, Other)",
    "targetDefinition": "String",
    "gtv": "Boolean (true/false)",
    "ctv": "Boolean (true/false)",
    "ptv": "Boolean (true/false)"
  }},
  "dosePrescription": {{
    "technique": "String (HDR, LDR, PDR)",
    "prescriptionDose": "String(Extract numeric value only, e.g. 7)"",
    "fractionationSchedule": "String (AlternateDay, Daily, Once Weekly, Others)",
    "numberOfFractions": "String (Extract numeric value only, e.g. 30)",
    "prescriptionTarget": "String",
    "dosePerFraction": "String (Extract numeric value only, e.g. 7)",
    "totalDose": "String (Extract numeric value only, e.g. 60)",
    "doseConstraints": "String"
  }},
  "interruption": {{
    "continueTreatment": "String (Continue with the same treatment, Suspend the treatment, Stop the treatment)",
    "interruptReason": "String",
    "interruptedDate": "String (YYYY-MM-DD)",
    "resumeDate": "String (YYYY-MM-DD)",
    "completionDate": "String (YYYY-MM-DD)"
  }},
  "followUp": {{
    "date": "String (YYYY-MM-DD)",
    "time": "String (HH:mm in 24-hour format)",
    "imagingAdvised": "String (CT, MRI, PET-CT, USG, X-Ray, Other)",
    "imagingAdvisedOther": "String",
    "postCompletionPlan": "String",
    "adviceOnCompletion": "String"
  }}
}}

Text to analyze:
{payload.text}
"""
        else:
            raise HTTPException(status_code=400, detail="Invalid module_type. Must be 'ebrt' or 'brachy'.")

        response = groq_client.chat.completions.create(
            messages=[{"role": "user", "content": prompt}],
            model="llama-3.3-70b-versatile",
            temperature=0.1,
            max_tokens=1500,
        )

        llm_output = response.choices[0].message.content.strip()

        # Try to parse the JSON output
        try:
            # Find the JSON object in case the LLM returned extra text
            start_idx = llm_output.find("{")
            end_idx = llm_output.rfind("}")
            if start_idx != -1 and end_idx != -1:
                json_str = llm_output[start_idx : end_idx + 1]
                data = json.loads(json_str)
                return {"status": "success", "data": data}
            else:
                return {"status": "error", "message": "Failed to parse JSON structure from LLM output", "raw": llm_output}
        except json.JSONDecodeError as e:
            logger.error(f"JSON Parsing Error: {str(e)} - Raw Output: {llm_output}")
            return {"status": "error", "message": "Failed to parse JSON structure from LLM output", "raw": llm_output}

    except Exception as e:
        logger.error(f"Error extracting radiotherapy structure: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))



class ChemoDoctorNoteStructurePayload(BaseModel):
    text: str

@router.post("/chemo-doctor-note-structure")
async def structure_chemo_doctor_note(payload: ChemoDoctorNoteStructurePayload):
    """
    Structure free-text / voice-dictated doctor's notes from the Chemo OP Record
    (CT Part B: Doctor's Notes tab) into a structured JSON object using Groq LLM.
    The frontend uses this to auto-fill empty partB form fields only — it will
    NOT overwrite any field that already has a value.
    Returns:
        {
          "status": "success",
          "data": { ...extracted fields... }
        }
    """
    api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        raise HTTPException(
            status_code=500,
            detail="GROQ_API_KEY not configured on server"
        )
    try:
        groq_client = Groq(api_key=api_key)
        prompt = f"""
You are an expert oncology medical assistant. Extract clinical information from the following doctor's note text and return a valid JSON object.
IMPORTANT RULES:
- Do NOT invent or assume values that are not explicitly stated in the text.
- If a field is not mentioned, return an empty string ("") for string fields, or false for boolean fields.
- For enum fields, only use the exact allowed values listed. If the text is ambiguous, return "".
Fields to extract:
1. "currentLabs": string — Free text summary of current lab results (e.g. CBC, LFT, RFT, tumor markers). Extract any mentioned lab values, counts, or test results.
2. "docOngoingTox": string — Free text description of any ongoing toxicity or tolerance issues the patient is experiencing (e.g. nausea, neuropathy, fatigue, mucositis).
3. "treatmentDecision": string — The doctor's decision about chemotherapy. Must be exactly one of: "continue", "modify", "change", "postpone". Return "" if not mentioned.
4. "treatmentDecisionJustification": string — The reason or justification provided for a modify/change/postpone decision. Leave "" if decision is "continue" or not mentioned.
5. "docReasonTolerance": boolean — true if intolerance to treatment is mentioned as a reason for a decision.
6. "docReasonProgression": boolean — true if disease progression is mentioned as a reason for a decision.
7. "docReasonChoice": boolean — true if patient choice or patient preference is mentioned as a reason for a decision.
8. "venousAccess": string — The type of venous access mentioned. Must be exactly one of: "peripheral", "central", "picc", "port". Return "" if not mentioned.
9. "safetyVerified": string — Whether the systemic therapy safety checklist has been verified. Must be exactly one of: "yes", "no". Return "" if not mentioned.
10. "emergencyMeds": string — Any emergency medications mentioned that should be kept available.
11. "consultantName": string — Name of the attending or consultant doctor if explicitly mentioned in the note.
12. "postponeFromDate": string — Date (YYYY-MM-DD) from which treatment is postponed if mentioned.
13. "postponeUntilDate": string — Date (YYYY-MM-DD) until which treatment is postponed if mentioned.
14. "postponeDays": string — Number of days treatment is postponed as string (e.g. "7").
15. "postponeReassessmentPlan": string — Description of the re-assessment plan during or after postponement.
16. "patientConsent": string — Whether signed patient consent is taken/obtained. Must be "yes" or "no". Return "" if not mentioned.
17. "drugPreparations": Array of objects for dose modifications. Each object must have:
    - "drugName": string
    - "whetherMod": string ("yes" or "no")
    - "modDose": string (Number/value of modified dose)
    - "modReasonTox": boolean (True if modified due to toxicity)
    - "modReasonComorb": boolean (True if modified due to comorbidities)
    - "modReasonPerf": boolean (True if modified due to performance status)
    - "modReasonNutri": boolean (True if modified due to nutrition)
    - "modReasonGen": boolean (True if modified due to general/other)
18. "drugs": Array of objects for current medications. Each object must have:
    - "name": string
    - "dose": string
    - "unit": string (e.g. "mg", "mg/m2")
    - "route": string (e.g. "Intravenous", "Oral")
    - "frequency": string (e.g. "Once Daily", "SOS")
    - "instructions": string (Any specific admin instructions)

Text to process:
"{payload.text}"

Return format MUST BE:
{{
  "currentLabs": "",
  "docOngoingTox": "",
  "treatmentDecision": "",
  "treatmentDecisionJustification": "",
  "docReasonTolerance": false,
  "docReasonProgression": false,
  "docReasonChoice": false,
  "venousAccess": "",
  "safetyVerified": "",
  "emergencyMeds": "",
  "consultantName": "",
  "postponeFromDate": "",
  "postponeUntilDate": "",
  "postponeDays": "",
  "postponeReassessmentPlan": "",
  "patientConsent": "",
  "drugPreparations": [],
  "drugs": []
}}
Return ONLY a valid JSON object. Do not include markdown formatting like ```json.
        """
        completion = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.1,
            response_format={"type": "json_object"},
            max_tokens=1500,
        )
        llm_output = json.loads(completion.choices[0].message.content)
        return {"status": "success", "data": llm_output}
    except json.JSONDecodeError as e:
        logger.error(f"Error parsing Groq LLM JSON for chemo doctor note: {e}")
        raise HTTPException(
            status_code=500,
            detail="Failed to parse LLM output as JSON"
        )
    except Exception as e:
        logger.error(f"Error structuring chemo doctor note: {e}")
        raise HTTPException(
            status_code=500,
            detail=f"Failed to structure chemo doctor note: {str(e)}"
        )


