@router.post("/update-structured-note")
async def update_structured_note(request: Request):
    try:
        data = await request.json()

        doctor_id = data["doctor_id"]
        patient_id = data["patient_id"]
        structured_note = data["structured_note"]

        # Get existing document
        doc = structured_note_collection.find_one(
            {
                "doctor_id": doctor_id,
                "patient_id": patient_id
            }
        )

        if not doc:
            raise HTTPException(status_code=404, detail="Structured note not found")

        if not doc.get("structured_notes"):
            raise HTTPException(status_code=404, detail="No structured notes found")

        # Update the latest note
        latest_index = len(doc["structured_notes"]) - 1

        structured_note_collection.update_one(
            {
                "doctor_id": doctor_id,
                "patient_id": patient_id
            },
            {
                "$set": {
                    f"structured_notes.{latest_index}.structured_note": structured_note,
                    "updated_at": datetime.utcnow()
                }
            }
        )

        return {
            "status": "success",
            "message": "Structured note updated successfully"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))




@router.get("/nurse-referral-letters/doctor/{doctor_id}")
async def get_nurse_referral_letters_by_doctor(doctor_id: str):

    try:
        referrals = []

        cursor = nurse_referral_letters_collection.find({
            "to_doctor_id": doctor_id,
            "status": "pending"
        })

        async for referral in cursor:

            patient_age = None

            patient = patient_user_collection.find_one({
                "sys_user_id": referral.get("patient_id")
            })

            if patient and patient.get("date_of_birth"):

                try:
                    dob = datetime.strptime(
                        patient["date_of_birth"],
                        "%Y-%m-%d"
                    )

                    today = datetime.today()

                    patient_age = today.year - dob.year

                    if (today.month, today.day) < (dob.month, dob.day):
                        patient_age -= 1

                except Exception:
                    patient_age = None


            referrals.append({
                "_id": str(referral["_id"]),

                # Added referral id for PUT endpoint
                "referral_id": referral.get("referral_id"),

                "patient_name": referral.get("patient_name"),
                "patient_id": referral.get("patient_id"),
                "patient_age": patient_age,

                "from_doctor_name": referral.get("from_doctor_name"),

                "to_doctor_name": referral.get("to_doctor_name"),
                "to_doctor_id": referral.get("to_doctor_id"),

                "reason": referral.get("reason"),

                "status": referral.get("status"),

                "date": referral.get("date"),
                "created_at": referral.get("created_at"),
                "updated_at": referral.get("updated_at")
            })


        return {
            "status": "success",
            "doctor_id": doctor_id,
            "count": len(referrals),
            "data": referrals
        }


    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=f"Error fetching nurse referral letters: {str(e)}"
        )


