async def seed():
    seed_file_path = os.path.join(os.path.dirname(__file__), "..", "data", "protocol_master_seed.json")
    with open(seed_file_path, "r") as f:
        protocols = json.load(f)

    count = 0
    for proto in protocols:
        await protocol_master_collection.update_one(
            {"protocol_id": proto["protocol_id"]},
            {"$set": proto},
            upsert=True
        )
        count += 1
        print(f"  Upserted: {proto['protocol_name']} ({proto['protocol_id']})")

    await protocol_master_collection.create_index("disease_sites")
    await protocol_master_collection.create_index("protocol_name")
    await protocol_master_collection.create_index([("disease_sites", 1), ("intent", 1)])

    print(f"\nDone. {count} protocols seeded.")

if __name__ == "__main__":
    asyncio.run(seed())
    
    
    
    
@router.get("/doctor-summary/{doctor_id}")
async def get_doctor_patient_summaries(doctor_id: str):
    try:
        pipeline = [
            {
                "$match": {
                    "doctor_id": doctor_id
                }
            },
            {
                "$sort": {
                    "generated_at": -1
                }
            },
            {
                "$group": {
                    "_id": "$patient_id",
                    "latest": {"$first": "$$ROOT"}
                }
            }
        ]

        cursor = summary_collection.aggregate(pipeline)
        docs = await cursor.to_list(length=None)

        if not docs:
            raise HTTPException(
                status_code=404,
                detail=f"No summaries found for doctor_id={doctor_id}"
            )

        result = []

        for item in docs:
            doc = item["latest"]

            result.append({
                "patient_id": doc["patient_id"],
                "generated_at": doc["generated_at"],
                "paragraphs": doc.get("summary", {}).get("paragraphs", []),
                "timeline": [
                    {
                        "date": t.get("date"),
                        "narrative": t.get("narrative")
                    }
                    for t in doc.get("timeline", {}).get("timeline", [])
                ]
            })

        return {
            "status": "success",
            "count": len(result),
            "data": result
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

