GROQ_MODEL_FAST = "llama-3.1-8b-instant"
GROQ_MODEL_SMART = "llama-3.3-70b-versatile"
 
# type: ignore  # e.g. db["paragraph_embeddings"]
 
 
OPENROUTER_API_KEY = os.getenv("OPENAI_API_ROUTER_KEY", "")
OPENROUTER_EMBED_URL = "https://openrouter.ai/api/v1/embeddings"
EMBEDDING_MODEL = "openai/text-embedding-3-large"
EMBEDDING_DIMENSION = 3072


async def embed_texts(texts: list[str]) -> list[list[float]]:
    headers = {
        "Authorization": f"Bearer {OPENROUTER_API_KEY}",
        "Content-Type": "application/json",
    }

    payload = {
        "model": EMBEDDING_MODEL,
        "input": texts,
    }

    async with httpx.AsyncClient(timeout=60.0) as client:
        response = await client.post(
            OPENROUTER_EMBED_URL,
            headers=headers,
            json=payload,
        )

    print("Status Code:", response.status_code)
    print("Response:", response.text)

    response.raise_for_status()

    data = response.json()

    if "data" not in data:
        raise Exception(f"Embedding API Error: {data}")

    return [item["embedding"] for item in data["data"]]
 
 
# ---------------------------------------------------------------------------
# 1. TNM -> Stage tables (deterministic, NOT LLM-derived)
# ---------------------------------------------------------------------------
# NOTE: map_tnm_to_stage() is a plain synchronous function (no I/O, no LLM
# call) so it correctly has NO await anywhere it's called. This was already
# right in your version — left untouched.
 
STAGE_TABLES: dict[str, dict[tuple[str, str, str], str]] = {
    "esophageal_adenocarcinoma": {
        ("T1", "N0", "M0"): "I",
        ("T2", "N0", "M0"): "IIA",
        ("T3", "N0", "M0"): "IIB",
        ("T1", "N1", "M0"): "IIB",
        ("T2", "N1", "M0"): "III",
        ("T3", "N1", "M0"): "III",
        ("T3", "N1-2", "M0"): "III",
        ("T4", "N0", "M0"): "IVA",
        ("T4", "N1", "M0"): "IVA",
        ("T4", "N1-2", "M0"): "IVA",
    },
    "gastric_adenocarcinoma": {
        ("T1", "N0", "M0"): "IA",
        ("T2", "N0", "M0"): "IB",
        ("T1", "N1", "M0"): "IB",
        ("T3", "N0", "M0"): "IIA",
        ("T2", "N1", "M0"): "IIA",
        ("T3", "N1", "M0"): "IIB",
        ("T3", "N1-2", "M0"): "IIB",
        ("T4", "N0", "M0"): "IIB",
    },
    # Add more cancer-type tables here, clinician-reviewed.
}
 
 
def map_tnm_to_stage(t: Optional[str], n: Optional[str], m: Optional[str],
                      cancer_type: Optional[str]) -> Optional[str]:
    """Deterministic TNM -> stage lookup. Returns None if unmappable —
    never guesses."""
    if not (t and n and m and cancer_type):
        return None
    if "M1" in m:
        return "IV"
    table = STAGE_TABLES.get(cancer_type)
    if not table:
        return None
    return table.get((t, n, m))
 
 
# ---------------------------------------------------------------------------
# 2. Extraction pipeline (run once per generated summary, not per query)
# ---------------------------------------------------------------------------
 
EXTRACTION_PROMPT = """Extract ONLY information explicitly stated in the text below.
 
CRITICAL RULES:
- Do NOT infer, calculate, or guess any value not literally written.
- Do NOT round, approximate, or "helpfully" complete partial data.
- If a field is not explicitly present, set it to null — never leave it blank or guess.
- Do NOT use medical knowledge to derive a value the text doesn't state
  (e.g. do not calculate an overall stage from TNM notation).
- For every non-null field, include the exact source sentence you drew it from.
 
Return JSON only, no preamble, no markdown fences, matching this shape:
{{
  "cancer_type": string|null,
  "cancer_type_source": string|null,
  "tnm_raw": string|null,
  "t_stage": string|null,
  "n_stage": string|null,
  "m_stage": string|null,
  "staging_type": "clinical"|"pathological"|null,
  "tnm_source": string|null,
  "treatment_phase": "pre-treatment"|"chemoradiotherapy"|"post-surgery"|"follow-up"|null,
  "treatment_phase_source": string|null,
  "current_medications": [string],
  "last_event_date": string|null,
  "last_event_summary": string|null
}}
 
Text:
{text}
"""
 
VERIFY_PROMPT = """You are checking a clinical data extraction for hallucination.
 
Original source text:
{text}
 
Extracted field: {field}
Extracted value: {value}
Cited source sentence: "{source_quote}"
 
Does the source text ACTUALLY and UNAMBIGUOUSLY state this value? Be strict —
if the cited sentence doesn't literally support the value, mark it false.
 
Return JSON only: {{"verified": true|false, "issue": string|null}}
"""
 
 
async def _call_json(prompt: str, model: str = GROQ_MODEL_SMART, max_tokens: int = 700,
                      temperature: float = 0.2) -> dict:
    """Call Groq's chat completions endpoint and parse a JSON response.
 
    Using AsyncGroq, so this create() call IS awaitable — this is the one
    (and only) SDK call in the file that needed `await` added back for the
    right reason (it was never the source of your original error; the sync
    Groq() client was).
    """
    completion = groq_client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt}],
        temperature=temperature,
        max_tokens=max_tokens,
    )
    raw = completion.choices[0].message.content.strip()
    raw = raw.removeprefix("```json").removeprefix("```").removesuffix("```").strip()
    return json.loads(raw)
 
 
async def _call_text(prompt: str, model: str = GROQ_MODEL_SMART, max_tokens: int = 800,
                      temperature: float = 0.2) -> str:
    """Same as _call_json but for plain-text (non-JSON) responses, e.g. the
    final grounded answers shown to the doctor."""
    completion = groq_client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt}],
        temperature=temperature,
        max_tokens=max_tokens,
    )
    return completion.choices[0].message.content.strip()
 
 
async def extract_fields(paragraphs: list[str]) -> dict:
    text = "\n\n".join(paragraphs)
    # FIX: _call_json is an async function — must be awaited or you get
    # "coroutine object has no attribute 'get'" the moment calling code
    # tries fields.get(...) on what is actually a coroutine.
    return await _call_json(EXTRACTION_PROMPT.format(text=text), model=GROQ_MODEL_SMART)
 
 
async def verify_field(text: str, field: str, value: Any, source_quote: str) -> bool:
    if value in (None, "", []):
        return True  # nothing to verify
    if not source_quote:
        return False  # a non-null value with no cited source is suspect
    # FIX: added await — result was being treated as a dict (`result.get(...)`)
    # a few lines down, which crashes with a coroutine.
    result = await _call_json(
        VERIFY_PROMPT.format(text=text, field=field, value=value, source_quote=source_quote),
        model=GROQ_MODEL_FAST,
        max_tokens=150,
    )
    if not result.get("verified"):
        logger.warning("Extraction verification FAILED for %s=%s: %s", field, value, result.get("issue"))
    return bool(result.get("verified"))
 
 
async def run_extraction_pipeline(patient_id: str, doctor_id: str, paragraphs: list[str]) -> dict:
    """Extract structured fields, verify each against source, drop anything
    that fails verification, resolve TNM -> stage deterministically, store."""
    # FIX: await — extract_fields is async; without await `fields` would be
    # a coroutine and `fields.get(field)` below would raise
    # "'coroutine' object has no attribute 'get'".
    fields = await extract_fields(paragraphs)
    text = "\n\n".join(paragraphs)
 
    field_source_pairs = [
        ("cancer_type", "cancer_type_source"),
        ("tnm_raw", "tnm_source"),
        ("treatment_phase", "treatment_phase_source"),
    ]
    for field, source_key in field_source_pairs:
        value = fields.get(field)
        source_quote = fields.get(source_key)
        if value is not None:
            # FIX: await — verify_field is async; `if not ok` on a coroutine
            # is always truthy/falsy-wrong and never actually checks anything.
            ok = await verify_field(text, field, value, source_quote)
            if not ok:
                fields[field] = None
                fields[f"{field}_verification_failed"] = True
 
    # Deterministic TNM -> stage — sync function, no await (correct as-is).
    resolved_stage = map_tnm_to_stage(
        fields.get("t_stage"), fields.get("n_stage"), fields.get("m_stage"),
        fields.get("cancer_type"),
    )
    fields["resolved_stage"] = resolved_stage
    fields["stage_basis"] = (
        "TNM-derived via lookup table, not explicitly stated as a numbered stage"
        if resolved_stage else None
    )
    fields["extracted_at"] = datetime.utcnow().isoformat()
 
    # FIX: await — Motor's update_one is a coroutine. Without await this
    # never actually runs (RuntimeWarning: coroutine '...' was never awaited)
    # and the write silently doesn't happen.
    await summary_collection.update_one(
        {"patient_id": patient_id, "doctor_id": doctor_id},
        {"$set": {"structured_fields": fields}},
        upsert=False,
    )
 
    # FIX: await — _embed_and_store_paragraphs is async.
    await _embed_and_store_paragraphs(patient_id, doctor_id, paragraphs)
 
    return fields
 
 
async def _embed_and_store_paragraphs(patient_id: str, doctor_id: str, paragraphs: list[str]) -> None:
    # FIX: await — Motor delete_many is a coroutine.
    await vector_collection.delete_many({"patient_id": patient_id})
    if not paragraphs:
        return
    # FIX: await — embed_texts is async; without await, `zip(paragraphs, embeddings)`
    # would try to zip against a coroutine object -> "object is not iterable".
    embeddings = await embed_texts(paragraphs)
    docs = [
        {
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "text": para,
            "embedding": emb,
            "indexed_at": datetime.utcnow().isoformat(),
        }
        for para, emb in zip(paragraphs, embeddings)
    ]
    # FIX: await — Motor insert_many is a coroutine.
    await vector_collection.insert_many(docs)
 
 
# ---------------------------------------------------------------------------
# 3. Query normalization (fixes spelling before anything else runs)
# ---------------------------------------------------------------------------
 
NORMALIZE_PROMPT = """Fix any spelling errors in this doctor's medical query.
Preserve meaning exactly — do not add, remove, or infer information.
Return ONLY the corrected text, nothing else.
 
Query: {question}
"""
 
 
async def normalize_query(question: str) -> str:
    # FIX: await — _call_text is async; without it, callers downstream that
    # do string formatting/prompt building on `question` would be operating
    # on a coroutine instead of a str.
    return await _call_text(
        NORMALIZE_PROMPT.format(question=question),
        model=GROQ_MODEL_FAST,
        max_tokens=150,
    )
 
 
# ---------------------------------------------------------------------------
# 4. Intent classification + fuzzy patient-name resolution
# ---------------------------------------------------------------------------
 
INTENT_PROMPT = """Classify this doctor's question and extract any patient name
mentioned (even if misspelled). Return JSON only:
 
{{"type": "cohort" | "single_patient", "patient_name_mentioned": string|null}}
 
- "cohort": asking about a group/filter across patients (e.g. "which patients have X")
- "single_patient": asking about one specific named patient
 
Question: {question}
"""
 
 
async def resolve_patient_name(doctor_id: str, name_query: str,
                                confirm_threshold: int = 75,
                                clarify_threshold: int = 60) -> dict:
    """Fuzzy-match a (possibly misspelled) name against this doctor's patients.
    Returns a dict with status: 'matched' | 'clarify' | 'not_found'."""
    # FIX: await — Motor's .to_list(...) is a coroutine. Without await,
    # `docs` would be a coroutine and the list comprehension below
    # ("for d in docs") would raise "'coroutine' object is not iterable".
    docs = await summary_collection.find(
        {"doctor_id": doctor_id}, {"patient_id": 1, "patient_name": 1}
    ).to_list(length=None)
 
    choices = {d["patient_name"]: d["patient_id"] for d in docs if d.get("patient_name")}
    if not choices:
        return {"status": "not_found"}
 
    # process.extractOne (rapidfuzz/thefuzz) is sync — correctly no await.
    match = process.extractOne(name_query, choices.keys(), scorer=fuzz.WRatio)
    if not match:
        return {"status": "not_found"}
 
    matched_name, score, _ = match
    if score >= confirm_threshold:
        return {"status": "matched", "patient_id": choices[matched_name],
                "matched_name": matched_name, "confidence": score}
    if score >= clarify_threshold:
        return {"status": "clarify", "matched_name": matched_name, "confidence": score}
    return {"status": "not_found"}
 
 
async def classify_intent(question: str, doctor_id: str) -> dict:
    # FIX: await — _call_json is async.
    parsed = await _call_json(INTENT_PROMPT.format(question=question),
                               model=GROQ_MODEL_FAST, max_tokens=200)
 
    if parsed.get("type") == "single_patient" and parsed.get("patient_name_mentioned"):
        # FIX: await — resolve_patient_name is async; without it,
        # match["status"] would fail since match is a coroutine, not a dict.
        match = await resolve_patient_name(doctor_id, parsed["patient_name_mentioned"])
        if match["status"] == "matched":
            parsed["patient_id"] = match["patient_id"]
            parsed["resolved_name"] = match["matched_name"]
        elif match["status"] == "clarify":
            return {"type": "clarify",
                    "message": f"Did you mean '{match['matched_name']}'? "
                               f"(confidence {match['confidence']:.0f}%)"}
        else:
            return {"type": "clarify",
                    "message": f"I couldn't find a patient matching "
                               f"'{parsed['patient_name_mentioned']}' for this doctor."}
    return parsed
 
 
# ---------------------------------------------------------------------------
# 5. Structured filter builder (question -> Mongo filter, not free-text scan)
# ---------------------------------------------------------------------------
 
FILTER_PROMPT = """Convert the doctor's question into a MongoDB filter using
ONLY these known fields on `structured_fields`. Return JSON only.
 
Available fields:
- structured_fields.cancer_type: string
- structured_fields.resolved_stage: string, one of ["I","IA","IB","IIA","IIB","III","IVA","IVB","IV"]
  (this is TNM-derived, present ONLY when TNM notation was explicitly documented)
- structured_fields.treatment_phase: one of ["pre-treatment","chemoradiotherapy","post-surgery","follow-up"]
- structured_fields.current_medications: array of strings
- structured_fields.last_event_date: date string (YYYY-MM-DD)
 
Rules:
- If the question needs a field not listed here, or needs a fact this schema
  cannot represent (e.g. "formal stage" when only descriptive extent-of-disease
  text exists), return {{"unsupported_field": "<plain explanation>"}} instead
  of inventing a filter.
- Use real MongoDB query operators ($in, $gte, $regex, etc.) as needed.
- Stage questions like "stage 3" should map to "resolved_stage": {{"$in": ["III"]}}
  (roman numeral, matches the table above) — but ONLY use this filter, never guess
  a stage some other way.
 
Question: {question}
 
Return JSON: {{"filter": {{...}}}} or {{"unsupported_field": "..."}}
"""
 
 
async def build_mongo_filter(question: str) -> dict:
    # FIX: await — _call_json is async.
    return await _call_json(FILTER_PROMPT.format(question=question),
                             model=GROQ_MODEL_SMART, max_tokens=300)
 
 
# ---------------------------------------------------------------------------
# 6. Semantic fallback search
# ---------------------------------------------------------------------------
 
async def semantic_fallback_search(doctor_id: str, question: str, limit: int = 20) -> list[dict]:
    # FIX: await — embed_texts is async. Without it, list-unpacking
    # `[q_embedding] = <coroutine>` raises a TypeError immediately.
    [q_embedding] = await embed_texts([question])
    # FIX: await — Motor aggregate(...).to_list(...) is a coroutine.
    results = await vector_collection.aggregate([
        {"$vectorSearch": {
            "index": "clinical_notes_vector_index",
            "path": "embedding",
            "queryVector": q_embedding,
            "numCandidates": 200,
            "limit": limit,
            "filter": {"doctor_id": doctor_id},
        }},
        {"$project": {
            "patient_id": 1, "text": 1,
            "score": {"$meta": "vectorSearchScore"},
        }},
    ]).to_list(length=None)
    return results
 
 
# ---------------------------------------------------------------------------
# 7. Answer composition (always grounded + cited)
# ---------------------------------------------------------------------------
 
COHORT_ANSWER_PROMPT = """Doctor's question: {question}
 
Matching patients (structured fields extracted from clinical notes):
{records}
 
Write a short, clear answer listing the matching patient_ids and the specific
field/value that matched for each. Use ONLY the data given — do not add
outside medical knowledge. If a record's relevant field is null, say so
rather than omitting it silently.
"""
 
SINGLE_PATIENT_ANSWER_PROMPT = """Answer the doctor's question using ONLY this
patient's record below. For every factual claim, cite the date it came from
in the format [source: YYYY-MM-DD]. If the records don't contain enough
information to fully answer, say so explicitly instead of filling the gap
with general medical knowledge.
 
Question: {question}
 
Paragraphs:
{paragraphs}
 
Timeline:
{timeline}
"""
 
SEMANTIC_ANSWER_PROMPT = """No exact structured match was found for this
question. Below are notes that are semantically SIMILAR to the question —
these are NOT confirmed matches. Question: {question}
 
Similar notes:
{results}
 
Summarize which patients might be relevant and why, but explicitly state
this is a similarity-based result that needs manual verification, not a
confirmed match.
"""
 
 
class ChatRequest(BaseModel):
    question: str
 
 
@router.post("/doctor-chat/{doctor_id}")
async def doctor_chat(doctor_id: str, req: ChatRequest):
    try:
        # FIX: await — normalize_query is async; without it `question` would
        # be a coroutine and every .format(question=question) call downstream
        # would embed a coroutine repr string into your prompts instead of text.
        question = await normalize_query(req.question)
        # FIX: await — classify_intent is async.
        intent = await classify_intent(question, doctor_id)
 
        if intent["type"] == "clarify":
            return {"answer_type": "clarify", "message": intent["message"]}
 
        if intent["type"] == "single_patient" and intent.get("patient_id"):
            # FIX: await — _answer_single_patient is async.
            return await _answer_single_patient(doctor_id, intent["patient_id"], question)
 
        # FIX: await — _answer_cohort is async.
        return await _answer_cohort(doctor_id, question)
 
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("doctor_chat failed")
        raise HTTPException(status_code=500, detail=str(e))
 
 
async def _answer_single_patient(doctor_id: str, patient_id: str, question: str) -> dict:
    # FIX: await — Motor find_one is a coroutine. Without await, `doc` is a
    # coroutine and `if not doc:` is always False (coroutines are truthy),
    # so you'd skip the 404 and then crash on `doc.get(...)` next.
    doc = await summary_collection.find_one(
        {"doctor_id": doctor_id, "patient_id": patient_id},
        sort=[("generated_at", -1)],
    )
    if not doc:
        raise HTTPException(404, "Patient not found for this doctor")
 
    paragraphs = doc.get("summary", {}).get("paragraphs", [])
    timeline_entries = doc.get("timeline", {}).get("timeline", [])
    timeline_text = "\n".join(f"{t.get('date')}: {t.get('narrative')}" for t in timeline_entries)
 
    # FIX: await — _call_text is async.
    answer_text = await _call_text(
        SINGLE_PATIENT_ANSWER_PROMPT.format(
            question=question,
            paragraphs="\n\n".join(paragraphs),
            timeline=timeline_text,
        ),
        model=GROQ_MODEL_SMART,
        max_tokens=800,
    )
    return {
        "answer_type": "single_patient",
        "patient_id": patient_id,
        "answer": answer_text,
    }
 
 
async def _answer_cohort(doctor_id: str, question: str) -> dict:
    # FIX: await — build_mongo_filter is async.
    parsed = await build_mongo_filter(question)
 
    if "unsupported_field" not in parsed:
        query = {"doctor_id": doctor_id, **parsed["filter"]}
        # FIX: await — Motor find(...).to_list(...) is a coroutine.
        docs = await summary_collection.find(query).to_list(length=None)
        if docs:
            records = [
                {"patient_id": d["patient_id"], "fields": d.get("structured_fields", {})}
                for d in docs
            ]
            # FIX: await — _call_text is async.
            answer_text = await _call_text(
                COHORT_ANSWER_PROMPT.format(
                    question=question, records=json.dumps(records, indent=2),
                ),
                model=GROQ_MODEL_SMART,
                max_tokens=600,
            )
            return {
                "answer_type": "exact",
                "confidence": "high",
                "patient_ids": [d["patient_id"] for d in docs],
                "answer": answer_text,
            }
        fallback_note = "No patients matched the exact filter; showing similar notes instead."
    else:
        fallback_note = parsed["unsupported_field"]
 
    # FIX: await — semantic_fallback_search is async.
    return {
    "answer_type": "no_match",
    "confidence": "none",
    "message": fallback_note,
}
 
    strong = [r for r in results if r["score"] > 0.80]
    weak = [r for r in results if r["score"] <= 0.80]
 
    # FIX: await — _call_text is async.
    answer_text = await _call_text(
        SEMANTIC_ANSWER_PROMPT.format(
            question=question, results=json.dumps(results, indent=2, default=str),
        ),
        model=GROQ_MODEL_SMART,
        max_tokens=600,
    )
    return {
        "answer_type": "semantic_fallback",
        "confidence": "medium" if strong else "low",
        "note": fallback_note,
        "patient_ids": list({r["patient_id"] for r in results}),
        "answer": answer_text,
    }
    
    
    
    
async def get_latest_patient_summaries(doctor_id: str):

    pipeline = [
        {
            "$match": {
                "doctor_id": doctor_id
            }
        },
        {
            "$sort": {
                "generated_at": -1
            }
        },
        {
            "$group": {
                "_id": "$patient_id",
                "latest": {
                    "$first": "$$ROOT"
                }
            }
        }
    ]

    docs = await summary_collection.aggregate(pipeline).to_list(None)

    return [item["latest"] for item in docs]




async def extract_patient_paragraphs(doctor_id: str):

    summaries = await get_latest_patient_summaries(doctor_id)

    documents = []

    MAX_CHARS = 20000   # Safe for text-embedding-3-large

    for summary in summaries:

        patient_id = summary["patient_id"]

        summary_data = summary.get("summary", {})
        timeline_data = summary.get("timeline", {})

        timeline_text = "\n\n".join(
            item.get("narrative", "")
            for item in timeline_data.get("timeline", [])
        )

        paragraph_text = "\n\n".join(
            summary_data.get("paragraphs", [])
        )

        combined_text = f"""
Timeline:
{timeline_text}

Clinical Summary:
{paragraph_text}
"""

        # Split into chunks by character length
        for i in range(0, len(combined_text), MAX_CHARS):

            chunk = combined_text[i:i + MAX_CHARS]

            documents.append({
                "id": f"{patient_id}_{i // MAX_CHARS}",
                "doctor_id": doctor_id,
                "patient_id": patient_id,
                "text": chunk
            })

    return documents



async def generate_patient_embeddings(doctor_id: str):

    documents = await extract_patient_paragraphs(doctor_id)

    texts = [doc["text"] for doc in documents]

    embeddings = await embed_texts(texts)

    for doc, embedding in zip(documents, embeddings):
        doc["embedding"] = embedding

    return documents





import chromadb

chroma_client = chromadb.PersistentClient(path="./doctor_rag")




async def search_doctor_rag(
    doctor_id: str,
    question: str,
    top_k: int = 5
):

    logger.info("=" * 80)
    logger.info("Doctor ID: %s", doctor_id)
    logger.info("Question: %s", question)

    collection = chroma_client.get_collection(
        name=f"doctor_{doctor_id}"
    )

    query_embedding = (await embed_texts([question]))[0]

    logger.info("Query embedding generated.")

    results = collection.query(
        query_embeddings=[query_embedding],
        n_results=top_k
    )

    logger.info("Raw Chroma Results: %s", results)

    documents = results.get("documents", [[]])[0]
    metadatas = results.get("metadatas", [[]])[0]

    rag_context = []
    patient_results = {}

    for index, (doc, meta) in enumerate(zip(documents, metadatas), start=1):

        logger.info("-" * 80)
        logger.info("Result #%d", index)
        logger.info("Metadata: %s", meta)
        logger.info("Patient ID: %s", meta["patient_id"])

        patient = patient_user_collection.find_one(
            {"sys_user_id": meta["patient_id"]},
            {
                "_id": 0,
                "name": 1
            }
        )

        logger.info("Mongo Patient Document: %s", patient)

        patient_name = meta["patient_id"]

        if patient:
            patient_name = patient.get("name") or meta["patient_id"]

        logger.info("Resolved Patient Name: %s", patient_name)

        rag_context.append(
            f"""
Patient Name: {patient_name}
Patient ID: {meta['patient_id']}

Clinical Summary:
{doc}
"""
        )

        # Remove duplicate patients
        patient_results[meta["patient_id"]] = {
            "patient_id": meta["patient_id"],
            "patient_name": patient_name
        }

    logger.info("=" * 80)
    logger.info("RAG Context:\n%s", "\n".join(rag_context))

    prompt = f"""
You are an expert oncology clinical assistant helping a doctor review patient records.

Answer ONLY using the clinical summaries provided below. Do not use outside
medical knowledge to fill gaps.

Response requirements:
- Give a thorough, clinically useful answer — not a one-line summary. Include
  relevant details such as diagnosis, staging/TNM findings, treatment phase,
  medications, and key dates when they appear in the summaries.
- Structure the answer per patient: start with the patient's name and ID,
  then the relevant findings, then any caveats or missing information.
- If multiple patients match the question, address each one separately —
  don't merge them into a single generic statement.
- Quote or reference the specific detail from the summary that supports each
  claim (e.g. "per the 2024-03-01 note...") so the doctor can verify it.
- Summarize and synthesize rather than copying summaries verbatim.
- Do not repeat the same patient twice.
- Explicitly flag any relevant field that is missing or not documented,
  rather than omitting it silently.
- If the summaries don't contain enough information to answer, reply exactly:
"I could not find enough information in the available patient summaries."

======================
Clinical Summaries
======================
{chr(10).join(rag_context)}

======================
Doctor Question
======================
{question}

"""

    logger.info("=" * 80)
    logger.info("LLM Prompt:\n%s", prompt)

    answer = call_llm(prompt)

    logger.info("=" * 80)
    logger.info("LLM Answer:\n%s", answer)

    logger.info("=" * 80)
    logger.info("Patient Results: %s", list(patient_results.values()))

    return {
        "answer": answer,
        "patients": list(patient_results.values())
    }


