@router.post("/doctor-rag/build/{doctor_id}")
async def build_rag(doctor_id: str):
    result = await store_doctor_embeddings(doctor_id)
    return result




async def store_doctor_embeddings(doctor_id: str):

    collection = chroma_client.get_or_create_collection(
        name=f"doctor_{doctor_id}"
    )

    documents = await generate_patient_embeddings(doctor_id)

    if not documents:
        return {
            "status": "error",
            "message": "No patient summaries found."
        }

    collection.upsert(
        ids=[d["id"] for d in documents],
        documents=[d["text"] for d in documents],
        embeddings=[d["embedding"] for d in documents],
        metadatas=[
            {
                "doctor_id": d["doctor_id"],
                "patient_id": d["patient_id"]
            }
            for d in documents
        ]
    )

    return {
        "status": "success",
        "documents": len(documents)
    }
    
    
def call_llm(prompt: str) -> str:

    response = groq_client.chat.completions.create(
        model="llama-3.1-8b-instant",
        messages=[
            {
                "role": "system",
                "content": (
                    "You are an expert oncology clinical assistant. "
                    "Answer only using the provided clinical context. "
                    "Do not make up facts. "
                    "If the answer is not present in the context, reply: "
                    "'I could not find enough information in the available patient summaries.'"
                )
            },
            {
                "role": "user",
                "content": prompt
            }
        ],
        temperature=0.2,
        max_tokens=5000
    )

    return response.choices[0].message.content.strip()




