#for fetching hospital id by rishy
async def fetch_hospital_id(doctor_id: str) -> str:
    """Fetch hospitalId for a doctor from the doctor API."""
    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            url = f"{api_base_url}hms/users/doctors/get_doctor/{doctor_id}"
            logger.info(f"[fetch_hospital_id] Fetching doctor info from: {url}")
            response = await client.get(url)
            logger.info(f"[fetch_hospital_id] Response status: {response.status_code}")
            if response.status_code != 200:
                logger.error(f"[fetch_hospital_id] Non-200 response: {response.text}")
                raise HTTPException(
                    status_code=502,
                    detail=f"Failed to fetch doctor info: {response.status_code}"
                )
            doctor_data = response.json()
            logger.info(f"[fetch_hospital_id] Full response keys: {list(doctor_data.keys()) if isinstance(doctor_data, dict) else type(doctor_data)}")
            logger.info(f"[fetch_hospital_id] Full response data: {doctor_data}")
            doctor_info = doctor_data.get("doctor", {})
            hospital_id = doctor_info.get("hospital_id")
            logger.info(f"[fetch_hospital_id] Extracted hospital_id: {hospital_id}")
            if not hospital_id:
                raise HTTPException(
                    status_code=400,
                    detail="Hospital ID not found for this doctor"
                )
            return hospital_id
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[fetch_hospital_id] Unexpected error: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"Error fetching hospital ID: {str(e)}")

