#by rishy
class ExposureLevelsPayload(BaseModel):
    totalFractions: Optional[Union[str, int, float]] = None
    totalDoseGy: Optional[Union[str, int, float]] = None
    doseUnit: Optional[str] = None  # "cGy" or "Gy"
    moduleType: Optional[str] = None  # "ebrt" or "brachy"
    organsAtRisk: Optional[List[str]] = []

@router.post("/calculate-exposure-levels")
async def calculate_exposure_levels(payload: ExposureLevelsPayload):
    try:
        total_fractions = payload.totalFractions or "Not specified"
        raw_dose = str(payload.totalDoseGy or "").strip()
        oars = payload.organsAtRisk or []
        oars_str = ", ".join([o for o in oars if o and str(o).strip()]) if oars else "None specified"
        unit = (payload.doseUnit or "").strip().lower()
        module = (payload.moduleType or "").strip().lower()

        # Unit handling: EBRT defaults to cGy, Brachytherapy defaults to Gy
        total_dose_str = "Not specified"
        if raw_dose:
            clean_num = re.sub(r"[^\d.]", "", raw_dose)
            if clean_num:
                try:
                    val = float(clean_num)
                    if unit == "cgy" or (unit == "" and (val > 150 or module == "ebrt")):
                        gy_val = val / 100.0
                        total_dose_str = f"{gy_val:.1f} Gy ({val} cGy)"
                    else:
                        total_dose_str = f"{val} Gy"
                except Exception:
                    total_dose_str = raw_dose
            else:
                total_dose_str = raw_dose

        prompt = (
            f"You are an expert Radiation Oncology AI assistant.\n"
            f"Evaluate the following radiotherapy treatment prescription parameters:\n"
            f"- Module Type: {payload.moduleType or 'Radiotherapy'}\n"
            f"- Total Fractions: {total_fractions}\n"
            f"- Total Target Prescription Dose: {total_dose_str}\n"
            f"- Organs at Risk (OARs) being monitored: {oars_str}\n\n"
            f"Clinical Guidance:\n"
            f"1. Dose Unit Rule: 1 Gy = 100 cGy (e.g. 5000 cGy is 50 Gy, 28 Gy is 28 Gy). Evaluate doses strictly in Gray (Gy).\n"
            f"2. Target vs OAR: Note that 'Total Target Prescription Dose' is the dose delivered to the tumor/target volume, NOT the direct absorbed dose in each Organ at Risk.\n"
            f"3. EBRT vs Brachytherapy:\n"
            f"   - EBRT: Conventional fractionation (1.8-2.0 Gy/fraction up to 45-66 Gy total target dose) under 3DCRT/IMRT/VMAT routinely satisfies QUANTEC constraints for OARs.\n"
            f"   - Brachytherapy: High-Dose-Rate (HDR) brachytherapy commonly delivers higher dose-per-fraction (e.g. 6-7 Gy x 4-5 fractions = 24-28 Gy total) with steep dose fall-off to protect surrounding OARs.\n"
            f"4. Mark an organ as 'Exceeded' ONLY if the prescription regimen (e.g. total dose or dose per fraction) is clinically extreme/unusual or represents an obvious overdose risk for that anatomical site.\n\n"
            f"Respond ONLY with a valid JSON object with three fields:\n"
            f'1. "status": overall status string, either "Safe" (if standard regimen/acceptable) or "Exceeded" (if extreme/unusual risk).\n'
            f'2. "organ_statuses": an array of objects for each organ at risk evaluated, where each object has:\n'
            f'     - "organ": organ name (e.g. "Heart")\n'
            f'     - "status": exact string "Safe" or "Exceeded"\n'
            f'     - "details": concise explanation of dose tolerance and constraint compliance under standard planning.\n'
            f'3. "details": a single string summary of overall exposure evaluation.'
        )

        chat_completion = groq_client.chat.completions.create(
            messages=[
                {"role": "system", "content": "You are a specialized medical AI that outputs valid JSON only."},
                {"role": "user", "content": prompt}
            ],
            model="llama-3.3-70b-versatile",
            temperature=0.2,
            response_format={"type": "json_object"}
        )

        raw_res = chat_completion.choices[0].message.content
        parsed = json.loads(raw_res)
        return {
            "status": "success",
            "data": parsed
        }
    except Exception as e:
        logger.error(f"Error calculating exposure levels: {e}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail=f"Failed to calculate exposure levels: {str(e)}"
        )


from pymongo import ASCENDING

@router.get("/timeline/{doctor_id}/{patient_id}")
async def get_patient_timeline(
    doctor_id: str,
    patient_id: str,
):
    """
    Returns the patient's complete visit history.
    Each visit contains:
      - Visit metadata
      - Visit summary
      - Timeline entries (without report_content)
    """

    visit_docs = list(
        visit_timeline_collection.find(
            {
                "doctor_id": doctor_id,
                "patient_id": patient_id,
            },
            {"_id": 0},
        ).sort("visit_number", ASCENDING)
    )

    if not visit_docs:
        raise HTTPException(
            status_code=404,
            detail=(
                f"No timeline found for patient '{patient_id}' "
                f"under doctor '{doctor_id}'."
            ),
        )

    visits = []

    for visit in visit_docs:
        timeline = []

        for entry in sorted(
            visit.get("timeline", []),
            key=lambda x: x.get("report_date", "")
        ):
            timeline.append({
                "timeline_entry_id": entry.get("timeline_entry_id"),
                "report_date": entry.get("report_date"),
                "document_id": entry.get("document_id"),
                "file_name": entry.get("file_name"),
                "report_summary": entry.get("report_summary"),
            })

        visits.append({
            "visit_number": visit.get("visit_number"),
            "appointment_id": visit.get("appointment_id"),
            "appointment_date": visit.get("appointment_date"),
            "visit_start_date": visit.get("visit_start_date"),
            "visit_end_date": visit.get("visit_end_date"),
            "visit_summary": visit.get("visit_summary"),
            "timeline": timeline,
        })

    return {
        "doctor_id": doctor_id,
        "patient_id": patient_id,
        "total_visits": len(visits),
        "visits": visits,
    }